const i=[{role:"patrol",label:"Обходчик",matches:["patrol"],ready:!0,intro:"Обход — это одна прогулка по этажу: одновременно проверяете и людей, и состояние комнаты.",steps:[{title:"1. Откройте вкладку «Обход»",text:"Список комнат этажа. Разверните комнату — увидите, кто в ней живёт по документам."},{title:"1а. Нажмите на имя — карточка жильца",text:"Откроется карточка: фото, фирма, дата заселения и до какого числа регистрация. Сверьте лицо с фото — тот ли человек лежит на этой койке; нажмите на фото, чтобы открыть его на весь экран. Срок регистрации жёлтый — осталось 7 дней или меньше, красный — уже истекла: направьте человека в администрацию. У заблокированного там же написано, за что, кем и когда его заблокировали («CRM автоматически» — сработало правило объекта: просрочка, долг фирмы, бельё). При блоке за отсутствие проходов число живое: «Нет проходов уже 2 дня 5 ч» — сколько человек без проходов сейчас, а когда его заблокировали — время после черты. Пометка «Фирма выселила» — фирма сообщила, что больше не держит за человеком место. Ниже — кнопки: выдать постельное, «уехал», комментарий, нарушение, «Отправить в администрацию», блокировка. В «Заданиях» нажатие на имя открывает ту же карточку, а под ней — кнопки исхода этого задания («На месте» / «Нет», «Отправил в администрацию» и т.п.) и блокировка. Паспорта в карточке нет намеренно: он на обходе не нужен."},{title:"2. Отметьте, кто на месте",text:"✓ — человек на месте, ✗ — не нашли. Повторное нажатие снимает отметку. Если в комнате все на месте — не отмечайте по одному, нажмите «Все на месте» в конце списка комнаты."},{title:"3. Если человека нет — укажите причину",text:"Появятся кнопки: «Не открыли», «На работе», «Соседи: уехал», «В другой комнате». Это не обязательно, но сильно помогает администрации потом разобраться, что произошло."},{title:"4. Проверьте порядок в комнате",text:"Кнопка «Порядок» — если чисто. Кнопка «Замечания» — если не убрано, курили или другое нарушение; для серьёзных нарушений (пожарная безопасность, курение, посторонний) система попросит приложить фото — это доказательство, без него разговор с фирмой-заказчиком не построить. Штраф, который выписали вы, вы же можете снять или исправить; чужой (выписал администратор или охрана) снять, удалить или изменить нельзя. А «Оплатил» — если жилец заплатил вам — можно по любому штрафу: отметка ляжет в журнал под вашей учётной записью."},{title:"5. Нашли человека, которого нет в списке?",text:"Кнопка «Лишний в комнате» — впишите, сколько человек и что успели узнать. Это частый признак того, что койку пересдали без ведома администрации."},{title:"6. Нужно что-то выдать жильцу?",text:"Кнопка «Оснащение» на комнате — отметьте, кому и что (матрас, подушка, одеяло, комплект белья). Даже если выбрали нескольких людей сразу, в системе это отдельная заявка на каждого — так и должно быть. Комплект белья с обхода выдаётся не чаще, чем раз в неделю (срок настраивает администратор): если рано — система откажет и назовёт дату следующей смены. Досрочно — только через администратора, с причиной."},{title:"7. Что-то сломано или жилец о чём-то просит",text:"Значок 💬 на комнате — «Поломка» (не работает окно, розетка и т.п.) или «Просьба» (нужна тумбочка, стул). Администрация увидит это в своём журнале."},{title:"8. Сфотографировать комнату",text:"Значок 📷 на комнате — снимки грязи, поломки, чего угодно, что нужно зафиксировать. Снимков можно приложить сразу несколько: комнату обычно снимают с разных ракурсов. Писать текст не обязательно — запись сохранится и с одними фотографиями. Всё видно в журнале обхода."},{title:"9. Заблокированный жилец",text:"В списке он красный, с замком; если фирма сообщила, что выселяет его, — рядом «фирма выселила». За что заблокирован — в карточке по нажатию на имя, скажите это человеку. Нашли — в карточке кнопка «Отправить в администрацию» (в задании — «Отправил в администрацию»): человек сразу отмечается «на месте», в строке появляется «в админ.», и он попадает в список «Ждём в администрации». Так же отправляйте того, у кого регистрация красная или жёлтая или у кого стоит «фирма выселила» — причина допишется сама. Снять отправку нельзя, повторное ✓ её не снимает: когда человек дойдёт, администрация отметит «Пришёл»."},{title:"9а. Задание «Кто внутри по СКУД»",text:"Во вкладке «Задания» может лежать список людей, которых турникет считает внутри на момент, когда задание создали (время написано сверху). Ваша работа — найти каждого и отметить «На месте» или «Нет». «Нет» — важная находка: по турникету человек здесь, а в комнате его нет — значит, прошёл кто-то за ним следом или человек здесь не живёт. Кто вышел после создания задания, из списка не пропадает — задание уже выдано, отмечайте как есть. Если задание дали на бумаге — те же клетки ручкой, лист сдаёте администратору."},{title:"9б. Один исход сразу нескольким в задании",text:"В задании слева у каждого жильца — кружок. Отметьте нескольких — внизу появится панель «Выбрано N чел.» с теми же исходами, что в строке («Отправил в администрацию», «Нет на месте», «На месте», «Выдал»…): нажмите нужный, и он встанет всем выбранным. Над списком — «Отметить всех оставшихся (N)»: выберите исход, CRM переспросит и отметит всех, кто ещё не отмечен. Ставьте так, только если правда проверили каждого. Ошиблись по кому-то — нажмите у него другой исход. После отметки внизу итог: «Отмечено 5 из 5», а если по кому-то не вышло — его имя и причина. На главном экране «Обход» то же для блокировки: «Выделить» → нажмите на жильцов → внизу «Заблокировать» или «Снять блок»; после блокировки в итоге есть «Отменить»."},{title:"10. Закончили обход",text:"Кнопка «Завершить обход» закреплена внизу экрана, пока обход идёт: долистывать список не нужно, она всегда под пальцем. Время нажатия фиксируется — это и есть доказательство, что обход был."},{title:"11. CRM попросила пароль снова",text:"Если ничего не делать в CRM сутки (24 часа), она сама закроет вход — на случай, если телефон потеряли или оставили без присмотра. На экране входа будет написано «Вы вышли из-за долгого бездействия» — это не поломка, просто войдите заново. Открытая вкладка вход не держит: считаются только ваши нажатия. Можно поставить себе срок короче — «Мой профиль» → «Автовыход при простое»."},{title:"12. Календарь: заметки и напоминания",text:"Раздел «Календарь» в меню: кнопка «Заметка», текст, дата, время или «Весь день». В поле «Кому» — себе, сотруднику или всем на объекте. В срок придёт напоминание: колокольчик и карточка в углу экрана. Если вас в этот момент нет в CRM, через 3 минуты придёт письмо: только дата и время, без текста заметки. Куда придёт письмо — внизу экрана, там же адрес можно поменять. Личную заметку видите только вы и адресат. «Сделано» может нажать любой, кто видит заметку; изменить и удалить — автор."}]},{role:"security",label:"Охрана",matches:["security"],ready:!0,intro:"Главная задача — чтобы каждый проход через турникет фиксировался, и чтобы у каждого живущего был действующий пропуск.",steps:[{title:"Первый день на смене",text:"Войдите; на общем компьютере поставьте галочку «Чужой компьютер» — вход пропадёт, как только закроете браузер. Ваши разделы: «Жильцы», «СКУД» (журнал, «Проверить по камере», «Фактическое проживание», «Турникеты»), «Пропускной пункт», «Заблокированные», «Уехавшие» (только просмотр), «Сотрудники» (только пропуска персонала), «Календарь». Начните с «Календаря» — там заметки прошлой смены, потом откройте «СКУД» → «Журнал событий» и убедитесь, что проходы идут. Найти жильца или комнату — Ctrl+K (на Mac ⌘K) или лупа в шапке: две буквы фамилии или номер комнаты. Незнакомое слово (СКУД, пропуск, терминал) — «Инструкции по разделам» → «Словарь»."},{title:"Обычный день по порядку",text:"Начало смены: «Календарь» (заметки), «СКУД» → «Проверить по камере» — число на вкладке показывает, сколько случаев ждут решения. Заселился новый жилец — сразу фото на пропуск (шаг 1). Жилец не проходит — шаг 3; красная карточка в углу экрана — «Иду проверять» (шаг 6б); заблокированный подошёл к турникету — направить к администратору (шаг 6). Конец смены: в «Календаре» оставьте заметку «Всем на объекте» для следующей смены; на вкладке «Проверить по камере» не должно остаться нерешённых случаев — каждый закрывается кнопкой «Подтвердилось» или «Не подтвердилось». Остальные шаги ниже нужны, когда случилось что-то особенное."},{title:"1. Оформляем пропуск жильцу",text:"Откройте карточку жильца: пока фото нет, сверху написано «Не готово: фото на пропуск» и стоит кнопка «Сделать фото на пропуск». Разрешите браузеру доступ к камере, нажмите «Сделать снимок». Пропуск уходит на турникеты сам — заводить что-то на самом терминале не нужно. Переснять готовое фото — на компьютере наведите мышь на фото в шапке карточки, на телефоне кнопки (загрузить, удалить) видны на фото сразу: нажмите значок загрузки. Перед съёмкой у жильца должно быть подписано согласие на проход по пропуску — его печатает администратор при заселении. Паспорта и сканов в карточке у охраны нет: для пропуска они не нужны."},{title:"2. Если камеры нет или снимок не получился",text:"В том же окне есть кнопка загрузки готового фото файлом — как запасной вариант."},{title:"3. Турникет не пускает, хотя жилец заселён",text:"В 9 случаях из 10 дело в пропуске: он не оформлен или устарел. Откройте карточку и переснимите фото (значок загрузки на фото в шапке: на компьютере появляется при наведении мыши, на телефоне виден всегда). Если человек заблокирован — в карточке красная метка, турникет закрыт правильно. Разбор всех похожих случаев — в разделе «Частые вопросы»."},{title:"3а. «Жильцы» с телефона",text:"На телефоне и планшете «Жильцы» — список по комнатам: этажи кнопками сверху, поиск по ФИО. Нажмите на жильца — откроется его карточка (фото на пропуск, блокировка). Зажмите строку — «Комментарий», «Заблокировать» или «Разблокировать». Комментарий записывается под вашим именем и виден под фамилией в этом списке — охране, обходчику и администрации; пометку администратора в карточке он не меняет. Значок сообщения в строке комнаты — заметка по комнате (сломана дверь, курили): администрация видит её в «Журнале обхода». Значок кресла — мебель в комнате: посмотреть можно, добавлять и менять — администрация."},{title:"4. Журнал проходов",text:"Раздел «СКУД» → «Журнал событий»: кто и когда прошёл, вход или выход. Поиск — по ФИО, номеру комнаты или СКУД ID. Кнопка «Фильтры» — дата и время (тот же календарь, что в фильтрах «Жильцов», крестик в поле — сброс, ниже «Сбросить даты и время»): выберите день, и станет доступно время (например 02.10 с 14:00 до 20:00 — минута «до» включается); Excel выгружает тот же отбор. Вкладка «Турникеты» (на объектах с Hikvision) показывает, на связи ли каждый терминал: «На связи», «Давно молчит» или «Ошибка»; списки расхождений и кнопка «Сверить сейчас» — для администратора, при проблемах сообщайте ему. Проход с пометкой «Неизвестно» означает, что CRM не опознала терминал, — направление не записано; сообщите администратору, это настройка терминала, а не человек."},{title:"5. Кто сейчас внутри",text:"Полоса над журналом и на «Главной»: «в хостеле», «на улице», «вошли и не вышли», «нет данных». Клик по цифре открывает список именно этих людей. Проходы считаются по всей сети: прошёл турникет другого объекта — здесь его уже нет. Сотрудники без комнаты (пропуск) в полосу не входят — они здесь работают, а не живут. Сотрудник, который живёт в комнате, — такой же жилец (стоит на учёте, занимает место) и считается во всех числах; на «Главной» над полосой — «из них N сотрудников», по клику список в «Жильцах». «Вошли и не вышли» делится на две группы: «Выход потерян» (до недели: ушёл за кем-то следом или открыли рукой — спросите у смены, следующий проход закроет сам) и «Давно нет проходов» (неделя и дольше: человек, скорее всего, уехал — скажите администратору, карточку надо закрыть). Точно знаете, что человек снаружи (видели, как ушёл за кем-то; уехал в отпуск)? В строке списка — «Отметить выход»: с причиной, под вашим именем; в журнале проходов появится выход текущим временем с пометкой «отметка». Задним числом не пишется."},{hideInDemo:!0,title:"6. Пропускной пункт",text:"Лента проходов крупно. Если объект переведён на ручной пропуск, вверху появляются те, кто стоит у турникета: сверьте фото с камерой и нажмите «Пропустить» или «Отказать». Пока кнопка не нажата, турникет закрыт; карточка краснеет через 30 секунд ожидания. Заблокированного (красная плашка) не пропускаем — к администратору. Если заблокированный пробует пройти сам, наверху появляется красная карточка «Заблокированный у турникета»: фото, комната, с какого числа и за что заблокирован, сколько раз пробовал. Карточка держится 15 минут после последней попытки — направьте человека в администрацию. Если в причине «Уехал на границу» или «На границе», карточка так и пишет: «вернулся с границы — нужны новая миграционная карта и новое уведомление в МВД». Скажите человеку, чтобы шёл к администратору с документами: без новой регистрации пустить его нельзя, это штраф хостелу. Когда администрация его разблокирует, карточка сама станет серой «Уже разблокирован»: пусть посмотрит в терминал ещё раз. «Разблокирован — команда идёт до турникета» — подождите минуту. Жёлтая «Турникет не пускает» значит, что разблокировка уже дошла, а турникет всё равно не пустил: запрет остался на терминале, сообщите администратору."},{title:"6а. «Проверить по камере» — провёл ли жилец постороннего",text:"СКУД → вкладка «Проверить по камере». Строки трёх цветов. Красная — «Чужой в здании?»: жилец открыл турникет второй раз, а рядом стоял человек без пропуска (так выглядит «провёл друга»), или незнакомый терминалу человек выходил изнутри — значит, его кто-то впустил. Оранжевая — жилец открыл турникет 3 раза и больше подряд: так проводят друзей, не показывая их лица. Серая — открыл второй раз без постороннего рядом, обычно просто посмотрел в терминал дважды; серые свёрнуты, а повторы быстрее 8 секунд не показываются вовсе. Посмотрите запись камеры за это время (у строки — точное время, «Снимок» и «Кадры терминала»), потом нажмите «Подтвердилось» или «Не подтвердилось», при желании с комментарием. Решение записывается под вашим именем и никого не наказывает само: штраф — отдельной кнопкой «Записать нарушение» после «Подтвердилось». У незнакомого CRM подсказывает только одно: сколько на объекте новичков без фото для пропуска — терминал их тоже не знает; если это новичок, сфотографируйте его для пропуска. Выселенного за последние 3 дня терминал узнаёт сам — это отдельная красная карточка «Выселенный у турникета» с его фото, комнатой и кнопкой «Открыть карточку». Кому на объекте приходят такие карточки со звуком, директор настраивает таблицей: «Настройки» → «Уведомления» (раздел объекта). Число на вкладке — сколько красных и оранжевых ждут решения. Кадры терминала хранятся 30 дней при любом решении, потом CRM стирает их сама. Кадров терминала нет на объектах, где терминалы работают через мостик на ПК охраны."},{title:"6б. Сигнал на любом экране — «Иду проверять»",text:"Красный или оранжевый случай появляется карточкой в правом нижнем углу на любом экране CRM — со звуком, а вкладка браузера мигает. Сигнал повторяется каждые 30 секунд, пока кто-то из охраны не нажмёт «Иду проверять»: тогда звук стихает у всех, а на карточке видно, кто пошёл. Решение («Подтвердилось» / «Не подтвердилось») — кнопкой «Открыть», на вкладке «Проверить по камере». Если CRM открыли и ещё ни разу не нажимали на странице, браузер звук не пускает — нажмите «Включить звук» на карточке. Кнопка «Уведомлять, когда окно свёрнуто» включает всплывающее сообщение Windows поверх других программ (в нём нет имени — только комната и время). Заблокированный у турникета — оранжевая карточка с одним коротким сигналом: в ней фото, комната и за что заблокирован; направьте человека в администрацию. Красный случай сразу звучит и у администрации — посторонний в здании, реагируют все. Оранжевый и заблокированного у турникета администрация не получает — это ваша работа."},{title:"6в. «Собирает вещи», «выход открыт» и «подходил с закрытым пропуском» в карточке",text:"Под фамилией в карточке бывают такие строки. «Собирает вещи — до 18:45» — администратор выселяет человека и дал ему 30 минут: пропуск у него пока работает, выйдет он сам; выезд подтверждает администратор. «Выселен изнутри: выход открыт до …» — человека выселили, когда он был в здании: сутки терминал выхода выпускает его сам, тревоги нет, выпускать руками не нужно. Вход ему закрыт: подойдёт ко входу — будет красная карточка «Выселенный у турникета». Вышел — в карточке «Вышел после выселения в 18:42», в журнале проходов у выхода пометка «вышел после выселения», пропуск закрыт везде. «Подходил к турникету с закрытым пропуском» — заблокированный пытался пройти с момента нынешней блокировки; если попытка была на выходе, он был внутри — сообщите администратору."},{title:"7. Заблокировать жильца",text:"В карточке жильца — кнопка «Заблокировать» (красная). Без указания причины кнопка не даст сохранить — причина остаётся в истории. После этого турникет ему больше не открывает. Список всех заблокированных — раздел «Заблокированные». Заблокировать сразу всех людей фирмы (или этажа, гражданства — любой отбор): на «Жильцах» выберите фирму в фильтре, нажмите «Отметить всех (N)» над списком комнат (N — сколько человек отметится, свёрнутые комнаты тоже) и внизу — «Заблокировать» с причиной. Повторное нажатие — «Снять отметку». Штраф всей комнате за непорядок: отметьте комнату галочкой в её шапке, внизу — «Штраф», причина и сумма каждому. У каждого появится своё нарушение, как из карточки. После «Штрафа» и после «Заблокировать» галочки остаются — второе действие делается сразу, причина из первого окна уже подставлена (после «Заблокировать» — если в фильтре не выбрано «Активные»: там заблокированные пропадают со списка, и галочки снимаются). Ошиблись — в той же панели «Снять блок»: она появляется, когда среди отмеченных есть заблокированные. Там же «Заметка» — допишет текст к заметке каждого новой строкой с датой, прежнее не сотрётся; в том же окне можно «Заменить» заметку, «Удалить» её или «Убрать строку» с нужным текстом: окно спросит, у скольких она пропадёт, а прежний текст останется в журнале действий. Бригада заплатила штрафы разом — «Заблокированные → Нарушения → Открытые», отметьте людей и «Оплатили»; там же «Изменить сумму» — одна новая сумма всем отмеченным; снять пачкой там можно только штрафы, которые выписали вы."},{title:"8. Разблокировать",text:"Там же появляется кнопка «Разблокировать» — с подтверждением. На Hikvision проход восстанавливается сразу, переснимать человека не нужно. Если человек уезжал на границу, окно подтверждения напомнит про новую миграционную карту и новое уведомление в МВД — такого не разблокируем сами, а ведём к администратору."},{title:"9. Сотрудники: пропуска персонала",text:"Раздел «Сотрудники» (раньше назывался «Пропуски сотрудников») — пропуска персонала (уборщицы, администраторы, охрана других смен). Там же заводится карточка-пропуск нового сотрудника и снимается пропуск уволенного. Здесь видны пропуска, которые пускают на ваш объект. Пропуск, который действует и на другие объекты, целиком не увольняется — уберите из него свой объект; уволить совсем может директор."},{title:"10. Чего охрана не делает",text:"Заселение, правка карточки, переселение и выселение — только администрация; у охраны этих кнопок нет, и сервер такие действия от охраны не принимает. Если жилец должен съехать — сообщите администратору. «Уехавшие» охране видны, но только для просмотра. Штраф, который выписали не вы, снять (простить), удалить или поменять в нём сумму и причину нельзя — это решение администрации. А принять оплату можно по любому штрафу объекта: жилец заплатил — нажмите «Оплатил», отметка ляжет в журнал под вашей учётной записью; у заблокированного откроется окно с галочкой «Снять блок» — как у администратора. Закрыть чужое нарушение без штрафа тоже можно. Свой штраф вы исправляете сами."},{title:"11. CRM попросила пароль снова",text:"Если ничего не делать в CRM сутки (24 часа), она сама закроет вход — чтобы оставленным на посту компьютером не воспользовался посторонний. На экране входа будет написано «Вы вышли из-за долгого бездействия» — это не поломка, войдите заново. Открытая вкладка вход не держит: считаются только нажатия, клавиатура, касания. На общем или чужом компьютере ставьте при входе галочку «Чужой компьютер» — тогда вход пропадёт, как только закроете браузер."},{title:"12. Календарь: заметки и напоминания",text:"Раздел «Календарь» в меню: кнопка «Заметка», текст, дата, время или «Весь день». В поле «Кому» — себе, сотруднику или всем на объекте. В срок придёт напоминание: колокольчик и карточка в углу экрана. Если вас в этот момент нет в CRM, через 3 минуты придёт письмо: только дата и время, без текста заметки. Куда придёт письмо — внизу экрана, там же адрес можно поменять. Личную заметку видите только вы и адресат. Так удобно передавать дела следующей смене: заметка всем на объекте. «Сделано» нажимает тот, кто сделал; изменить и удалить может автор."}]},{role:"management",label:"Администратор",matches:["admin"],ready:!0,intro:"Полный путь: завести хостел → добавить комнаты → заселить жильца → следить за миграционными сроками.",steps:[{title:"Первый день: с чего начать",text:"Вошли — вы на «Главной». Сверху переключатель объекта: убедитесь, что выбран ваш хостел (администратор объекта видит только свой). Дальше по порядку: 1) «Главная» — полоса «Требует внимания»: пока она пустая, срочного нет. 2) «Жильцы» — кто сейчас живёт; нажмите на любого, откроется его карточка. 3) «Миграционный контроль» → «Сегодня» и «Просрочка» — у кого срок регистрации кончается сегодня или уже прошёл: за это штрафуют хостел. 4) «Календарь» — заметки и напоминания, в том числе от прошлой смены. 5) Найти человека, комнату или раздел можно с любого экрана: Ctrl+K (на Mac ⌘K) или лупа в шапке — введите две буквы фамилии, номер комнаты или название раздела. Объект только запускается и пустой — шаг «2б. Объект пустой — с чего начать». Встретили незнакомое слово (ЭЦП, СКУД, Контур…) — «Помощь» → «Инструкции по разделам» → «Словарь»."},{title:"Главная: что на экране",text:"«Требует внимания» — только то, где есть проблема (нулевые пункты не показываются), у каждого — кнопка перехода туда, где это чинят: «Просрочена регистрация», «Заблокирован проход», «Не получили бельё», «Турникеты не на связи». Сверху справа — «Турникеты на связи» или «Турникеты не на связи». «Заполненность хостела» — «Всего жителей», «В хостеле сейчас», «На улице» и строки про тех, кто «вошёл и не вышел» или без проходов; клик по цифре открывает список этих людей. Ниже — «Динамика по месяцам» (заселения и выселения), мест жилых и служебных, «Проживающие по фирмам» (выделено мест и сколько реально живёт), «Заполняемость по этажам» (карта по этажам; только когда выбран один хостел), «Статусы жителей» (активные, заблокированные, на паузе) и карточка «Постельные принадлежности». Пока объект пуст, наверху вместо этого — список «С чего начать»: хостел, комнаты, первый жилец."},{title:"Обычный день по порядку",text:"Утро: «Главная» → «Требует внимания»; «Календарь» — заметки смены; «Заявки фирм» — кто просит заселить или выселить. Днём: заселение (шаги 3–9), «Миграционный контроль» → «Сегодня» — продлить, подать уведомление, выдать бланк (шаг 12). Если есть штрафы или блокировки — «Заблокированные». Вечером: «Миграционный контроль» → «Просрочка» должна быть пустой; оставляйте заметки следующей смене в «Календаре» («Кому» — всем на объекте). Раз в неделю: «Фирмы» → «Сверка» (шаг 12д) и «Журнал обхода». Остальные шаги ниже — справочник на случай, когда что-то понадобилось: читать подряд их не нужно."},{title:"1. Заводим объект",text:"«Настройки» → «Сеть» → «Объекты» → «Добавить хостел»: название, адрес, статус, Email (общий ящик объекта): сюда придут ответы фирм на ваши счета (письмо фирме уходит с ящика-робота, а «Ответить» ведёт на этот адрес) и тревога «заблокированный прошёл через турникет» (в ней нет ФИО — только СКУД ID и комната; имя смотрите в CRM). Пустой Email — ответы фирм и тревога до вас не дойдут. Дальше доступы к Контур.ФМС — «Настройки» → «Объект» → «Контур.ФМС», а считыватели турникетов — в разделе «СКУД» → «Оборудование и настройка». Без этого СКУД и сверка ЭЦП не заработают."},{title:"2. Комнаты и юр. лицо",text:"Вкладка «Комнаты»: у каждой комнаты — своё юр. лицо (ЭЦП), меняется прямо в строке списка. Если юр. лиц несколько — можно выделить чекбоксами группу комнат и назначить юр. лицо всем разом."},{title:"2а. Оснащение комнаты (мебель)",text:"В списке «Жильцы» у каждой комнаты — кнопка «Оснащение» рядом с фирмой и вместимостью. Открывается окно со списком: вид мебели (тумбочка, табурет, стол, вешалка, вентилятор, шкаф), количество и состояние (новое / старое, в порядке / на замену). Если что-то нужно заменить — кнопка сама подсветится жёлтым и покажет, сколько позиций «на замену». Добавить, изменить количество или состояние можно прямо здесь же, без похода в «Управление комнатой»."},{title:"2б. Объект пустой — с чего начать",text:"Заселить первого человека получится, когда у объекта есть юр. лицо, комнаты и хотя бы одна фирма — без них форма заселения упрётся в «Ничего не найдено». Порядок: «Настройки» → «Сеть» → «Юр. лица» (от чьего имени ставят на миграционный учёт) → «Жильцы» → «+ Комната» (юр. лицо комнатам — в «Юр. лица» → «По комнатам») → меню «Фирмы» (кто размещает людей) → «Жильцы» → «Заселить». Что у объекта ещё не настроено, CRM показывает сама — списком наверху «Настроек объекта», пункт по клику."},{title:"3. Заселяем жильца",text:"«Жильцы» → «Заселить жильца». Быстрее всего — приложить скан документов и нажать «Распознать документы»: система разберёт лист и сама заполнит поля. Скан — фото или PDF со сканера: PDF в несколько страниц CRM сама сложит в один лист (до 4 страниц). Форма идёт тремя блоками: «Кто» (гражданство, ФИО, дата рождения), «Документы» и «Размещение» (фирма, комната, сроки). Гражданство стоит первым не случайно — от него зависит, какие документы попросят ниже."},{title:"3а. Гражданин РФ без паспорта — Цифровой ID (MAX)",text:"Гражданин России вправе заселиться без бумажного паспорта — по QR-коду из приложения MAX. В окне заселения под «Скан документов» нажмите «Цифровой ID (MAX)». Гость открывает в MAX «Цифровой ID» → паспорт → «Предъявить» (не «Подтвердить»). Дальше — чем удобнее: «Телефон» — наведите камеру телефона на QR в окне, откроется страница сканирования; войдите под той же учёткой, что на компьютере, и отсканируйте QR гостя — поля заполнятся на компьютере сами. «2D-сканер» — поднесите QR к сканеру, Enter нажимать не нужно. «Камера компьютера» — если она есть. Гражданство ставится «Россия», ФИО, паспорт и место рождения заполняются сами. Жёлтым отмечено только то, в чём CRM не уверена, — сверьте такие поля с экраном MAX у гостя. Адрес регистрации из QR не переносится: в карточке жильца такого поля нет. Уведомление в МВД — как обычно."},{title:"3б. С телефона и планшета",text:"«Жильцы» на телефоне — по комнатам: нажмите на жильца — откроется его карточка целиком, зажмите — комментарий и блокировка. «Заселить» и «Сверить с фирмой» — над списком. При заселении скан документа стоит сверху, форма — под ним: сверяйте поля, не переключаясь; для скана подойдёт камера самого телефона. «Миграционный контроль», «Заблокированные», «Нарушения» и «Уехавшие» на телефоне — карточками: главное (срок регистрации, статус, причина блокировки) — на карточке, кнопки «Продлить», «Выдать», «Снять блок», «Вернуть» — внизу. Остальное — в карточке жильца. Какой хостел открыт, видно вверху рядом с меню; нажмите — откроется меню с переключателем."},{title:"3в. Лицо без гражданства и неграждане Латвии и Эстонии",text:"В списке гражданств они так и называются: «Лицо без гражданства», «Негражданин Латвии», «Негражданин Эстонии». Не подбирайте похожую страну — в уведомление МВД ушло бы чужое гражданство. Работают они по патенту, как граждане Узбекистана. Под блоком «Кто» появится поле «Страна рождения» — выберите по документу (родился в СССР — нынешняя страна того места: Латвийская ССР → Латвия); без неё не заселить. В файл для Контура таких людей CRM не выгружает: какой код ждёт Контур, он не описал. Уведомление внесите в кабинете Контура вручную или подайте бумагой; во вкладке «Не подать» человек останется с этой причиной — напоминание, что подавать его надо не файлом."},{title:"4. Что означает подсветка полей",text:"Жёлтая полоска слева от поля — распознано неуверенно, сверьте со сканом (у Цифрового ID MAX — с экраном телефона гостя; подсветка гаснет, когда вы поле поправили или задержались в нём хотя бы секунду: просто пройти мимо клавишей Tab — не значит сверить). Красная — поле обязательно и не заполнено либо заполнено неверно: под ним написано, что не так («Номер паспорта РФ — 6 цифр»). В заголовке каждого блока видно, сколько осталось. Если после скана появилось сообщение «распознан в упрощённом режиме» — распознавание сейчас работает хуже обычного: основные поля отмечены жёлтым, но сверить со сканом нужно каждое заполненное, включая «кем выдан», срок паспорта, визу и ВНЖ. Разработчик о сбое уже знает, сообщать не нужно."},{title:"5. Кнопка «Заселить» не гаснет",text:"Если чего-то не хватает, нажмите её — система назовёт, чего именно. Неполную карточку сохранить нельзя: при заселении документы жильца у вас на руках, а уведомление в МВД с пустой обязательной графой считается неподанным — это штраф. Миграционная карта — «всё или ничего»: заполнили одно поле из пяти — нужны все пять. Исключения: сотрудники, правка старой карточки и импорт. Отдельно про строку «латиницей (для Контура)» под ФИО: там допустимы только латинские буквы (апостроф и дефис можно — «O'RINOV», «ABDULLA-ZADE»). Попала цифра или другой знак — поле краснеет и сохранить не даст: Контур возвращает такое уведомление целиком, и узнаёте вы об этом через несколько дней, когда паспорта под рукой уже нет. Посмотрите в паспорт и поправьте букву. Кнопка «Заполнить латиницу» рядом с этой строкой берёт фамилию и имя из машинной зоны распознанного паспорта (две строки внизу страницы), а без неё переводит русское ФИО по правилам МВД — тогда сверьте с паспортом: «Юнусджон» в паспорте бывает YUNUSJON, а перевод даст IUNUSDZHON. У граждан РФ этой строки нет: латиница в их уведомление не идёт, и CRM её не проверяет."},{title:"6. Вкладка «Не подать» — кого МВД не примет",text:"На «Миграционном контроле» есть вкладка «Не подать»: в ней поимённо те, по кому выгрузка в Контур откажет, с комнатой, фирмой и причиной. Чаще всего причина одна — не внесён номер паспорта. У перенесённых из таблицы бывает причина «Пол»: в таблице пола нет, CRM угадывает его по отчеству (-овна, кызы — женский, -ович, угли — мужской), а где отчества нет или оно непонятное, оставляет пол пустым — выберите его по паспорту. Уведомление с пустой обязательной графой в МВД считают неподанным, а это штраф, о котором узнают через недели, поэтому CRM такие карточки в файл не собирает. Порядок работы простой: открыли вкладку, нажали на человека, дозаполнили карточку по документам — он уходит из списка. По умолчанию показаны живущие (у них документы можно спросить сегодня), уехавших добавляет галочка — их ещё снимать с учёта."},{title:"7. Про патент и работу с клавиатуры",text:"Дата выдачи патента печатается на обороте и в скан не попадает — её вводят руками, поле подписано. Срок патента система посчитает сама: год со дня выдачи. У визовых иностранцев (Туркменистан, Китай, Вьетнам, Индия…) патента нет — вместо него разрешение на работу, РНР: поставьте галочку «Есть РНР» и впишите серию-номер, дату выдачи и «действует до» С САМОГО ДОКУМЕНТА — срок РНР система не считает, он у каждого свой. При «Вернуть из уехавших» система сама не переносит патент, который уже истёк, — впишите новую дату, когда жилец оформит патент заново; если старая дата всё же осталась в карточке, а человек въехал по новой миграционной карте позже её конца, карточка покажет не «истёк», а «от прошлого заезда» и подскажет срок подачи на новый (30 дней со дня въезда). По форме удобно идти клавишей Tab — мышь можно не брать. В выпадающем списке начните печатать («узб», «стро…») и нажмите Tab или Enter — выберется подсвеченный вариант; если просто пройти клавишей Tab через уже заполненный список, значение не изменится. Enter в обычном поле переводит к следующему полю, а заселяет только кнопка «Заселить жильца». Патент — в блоке «Документы», под миграционной картой; штамп о продлении у тех, кому его не ставят, свёрнут строкой «+ Есть штамп о продлении»."},{title:"8. Система предупредит о проблеме сама",text:"Совпал паспорт — окно «Этот человек уже есть в CRM»: заводить его заново нельзя, нажмите «Вернуть» (уехал здесь) или «Заселить сюда (переезд)» (уехал на другом объекте); живёт на другом объекте, а переезжает к вам — «Заселить сюда и попросить … оформить выезд», тот объект подтвердит выезд у себя сам. Совпали только ФИО и дата рождения — окно «Похожий человек уже был»: посмотрите на фото и решите, он это или другой человек. В обоих окнах видно нарушения человека за всё время и неоплаченный долг; при долге «Вернуть» и переезд сначала спросят «Заселить всё равно?» — ответ уйдёт в журнал. Про переполненную комнату, чужую фирму и превышение квоты фирмы тоже скажет. Читайте эти подсказки, не закрывайте не глядя."},{title:"9. После сохранения",text:"На объекте с Контуром скачивается файл для Контур.ФМС — загрузите его в кабинет Контура и распечатайте жильцу регистрацию. Не сформировался — кнопка «Скачать CSV для Контура» в строке жильца на «Жильцах». Если для вашего кабинета в деле номер комнаты не пишется, директор или администратор объекта ставит у кабинета галочку «Не писать номер комнаты в CSV» («Настройки» → объект → «Контур.ФМС») — тогда колонка «№ комнаты» в файле пустая, а в черновике, который создаёт робот, поле комнаты не заполняется; это не ошибка. Сотруднику, который живёт в комнате для персонала, файл скачивается так же: уведомление по нему подаётся, как по жильцу. Не подаётся только пропуск сотрудника без комнаты (пришёл на смену и ушёл) — его заводят на «Пропусках сотрудников», в жильцах его нет. На объекте с бумажным учётом вместо файла — бланк в карточке жильца («Документы»), на Госуслугах — кнопка «Отправить в МВД (Госуслуги)» прямо в окне «Заселён» (можно и позже: «Миграционный контроль» → «Госуслуги»). Окно «Заселён» само говорит, что делать с уведомлением на вашем объекте."},{title:"9а. Полоса «Требует внимания» в списке жильцов",text:"Над таблицей показываются плашки с числом людей, у которых жмут сроки: «Паспорт истёк», «Паспорт истекает», «Замена паспорта (20/45)», «Патент истекает», «Патент не оформлен» и «Срок на патент вышел» (нужен по гражданству, а действующего нет — не путать с «истекает», это про тех, у кого он ещё есть), «РНР истекает», «Мигр. карта истекает». Нажмите плашку — в списке останутся только эти жильцы, получится готовый список на сегодня. У строки жильца стоит значок документа: наведите — увидите, что именно не так. В полосе счётчиков есть плитка «Без окна: комнат · мест · живут · свободно» (если на объекте такие комнаты отмечены) — считается по тем же жилым комнатам, что «Свободно мест» (этаж, тип, фирма, «только свободные»; подсобки и комнаты персонала не в счёт). Плитка переключается нажатием: первое — останутся только комнаты без окна, второе — плитка станет «С окном» и останутся только комнаты с окном, третье — снова все комнаты. «Без окна» + «С окном» = «Свободно мест»; пустые комнаты при этом в списке видны. У комнат без окна в строке стоит пометка «без окна». Признак ставится в карточке комнаты галочкой «Есть окно». Выберите в фильтре фирму, у которой в карточке включено «Считать дни проживания», — появятся плитки «Просроченный срок / Действует / Нет даты» по сроку пребывания её людей. Цвета плиток везде одни: красное — опасно (заблокированы, просрочена регистрация), оранжевое — проверить или сделать, зелёное — в порядке, серое — справка и ноль. Плитка «Без согласия: N» — живущие, у кого не отмечено подписанное согласие на обработку ПД (второе число — есть фото для пропуска, а согласия на него нет). Порядок: подписал человек лист (согласие на ПД, правила проживания, пожарный инструктаж) → лист в папку объекта → в CRM отметка. Отметить пачкой: включите плитку, выделите галочками подписавших → «Согласие подписано» — отметка ставится сегодняшним числом. У кого согласие уже подписано, кнопка пропускает: выбраны только такие — кнопки нет, вперемешку — на ней число тех, кому отметка нужна. Одного — в карточке, «Документы» → «Подписано на бумаге», или на «Миграционном контроле» (вкладка «Согласия», в строке кнопки «Печать» — скачать пакет на подпись — и «Подписал»; удобно, когда человек пришёл за продлением). После заселения CSV для Контура скачивается сам, а пакет на подпись — кнопкой в окне «Заселён» (браузер не даёт скачать два файла подряд): распечатайте, дайте подписать, отметьте одним нажатием «Подписано» — без выбора документов, подписан весь пакет. Скан не нужен: оригинал хранится в папке, пока человек живёт, плюс 3 года."},{title:"10. Карточка жильца",text:"Наверху — строка состояния документов: зелёная «в порядке», жёлтая «истекает», красная «просрочено». Под ней — «Не готово: …», если у живущего нет фото на пропуск или подписанного согласия (то же, что плитки «Нет пропуска» и «Без согласия» в списке), и ряд «фото на пропуск · сейчас в хостеле / на улице · Отметить выход». Строка сроков показывает только то, что уже жмёт: паспорт, действующий ещё годы, там не появится. Во вкладке «Документы» у каждого документа в шапке написан срок действия и стоит знак. Миграционная карта тревожит только тогда, когда нет ни патента, ни РНР: пока одно из них действует, право находиться в стране даёт оно. У РНР без «действует до» в карточке стоит «срок не указан» — впишите дату с документа, иначе система не увидит, когда оно кончится. Гражданам Киргизии, Казахстана и Армении (у узбеков и таджиков основание — патент, им блок не показывается) за 14 дней до конца срока пребывания в «Документах» появляется жёлтый блок «Заполнить данные со штампа миграционной карты»: МВД продлевает пребывание штампом на обороте карты — перепишите оттуда «продлено до», дату отметки и основание, и срок дальше считается по штампу. Лицевую дату карты не трогайте."},{title:"10а. Правка карточки — та же форма, что заселение",text:"Карандаш в шапке карточки открывает ту же форму, что при заселении: «Кто» → «Документы» → «Размещение», гражданство первым, подсветка полей — та же. Одно отличие: старую карточку можно сохранить и неполной (нужно поменять телефон или комнату, а паспорт выселенного год назад искать некому) — пустые обязательные поля показаны серым «осталось дозаполнить», а не красным. Не даёт сохранить только неверный формат: с таким номером уведомление в МВД вернут, поле подсвечено красным, под ним написано, что не так. Галочки «Есть виза» и «Есть РНР» стоят по данным карточки: сняли галочку — при сохранении эти поля очистятся. «Распознать документы» и «Дозаполнить из Контура» — кнопки над формой."},{title:"11. История в карточке",text:"Проходов у жильца тысячи, поэтому вверху есть фильтр: «Проходы», «Бельё и оснащение», «Изменения», «Кто что менял». Последний отвечает на вопрос «кто продлил регистрацию» — там видно действие, дату и человека."},{title:"12. Миграционный контроль — вкладки и главные действия",text:"«Сегодня» (регистрация истекает сегодня; там же все, кому дату уже продлили, а «Выдать» ещё не нажали, — с припиской «забрать до …»: висят, пока не нажмёте «Выдать», и не прячутся до конца старого срока), «Просрочка» (срок уже прошёл), «Патент / РНР» (истекает или истёк; у визовых вместо патента — разрешение на работу, срок правится в той же колонке), «Согласия» (пакет на подпись не отмечен подписанным — кнопка «Подписал» в строке). Пачкой: выделите галочками нескольких (можно по одному через поиск: нашли, отметили, нашли следующего — отмеченные раньше не теряются, панель скажет «из них не видно в списке: N»; галочка в шапке добавляет видимых к уже отмеченным) — после «Подписали» и «Продлить на месяц» отметка остаётся, так что следом сразу «Выдать выбранным» (зелёная, как «Выдать» в строке). Внизу появятся «Согласия: напечатать» (скачается один файл, у каждого свой лист, двусторонняя печать; все станут «На подписи») и «Согласия: подписали» (отметить подписанными сегодняшним числом). Людям без юр. лица пакет не печатается — оператор в согласии это юр. лицо, а не хостел; CRM их пропустит и скажет, скольких. В колонке «Патент / РНР» у безвизового без патента — кнопка «Подал на патент»: жилец показал наклейку о приёме заявления — нажмите, и напоминание «оформите патент» погаснет («оформляется»); патент выдают в 10 рабочих дней, через месяц без патента CRM напомнит проверить. Плашка «Подача на патент не отмечена» — 30 дней с въезда прошли, а подачу не отметили: по закону это штраф при подаче, а не запрет, и почти всегда человек уже подался — спросите наклейку. Порядок работы: в день срока — «Продлить» (дата сдвигается на месяц, число то же: 03.10 → 03.11, 30.09 → 30.10; если такого числа в следующем месяце нет — последний день месяца: 31.10 → 30.11, 31.01 → 28.02; нужна другая дата — «Изменить». Поправка даты ничего не «выдаёт»: строка ждёт кнопку «Выдать»), подать уведомление в МВД, напечатать бланк; жилец пришёл с документами и чеком — «Выдать». «Ждёт выдачи» относится к заезду: уехал — отметка гаснет (бланк на столе для уехавшего — не долг, штраф за «не забрал», если был, остаётся в нарушениях); вернулся — начинает с чистого листа, как новичок, и в «Сегодня» появится только когда вы продлите ему регистрацию. Остальные вкладки (их может быть до десяти) и почему у коллеги они другие — в шаге «12п»."},{title:"12а. «Просрочка» — две разные строки",text:"Красная «Не продлено N дн.» — срок прошёл, а новую дату в CRM не поставили. Это ваша задача, и единственная опасная строка: уведомление в МВД не подано, человек живёт с истёкшей регистрацией. Нажмите «Продлить» и подайте уведомление; такие строки утром приходят и в письме-сводке. Жёлтая «Не забрал N дн.» — вы продлили, бланк лежит, а жилец в свой день не пришёл: хостелу ничего не грозит, это повод для штрафа по правилам проживания — кнопка «Оштрафовать» (причина уже подставлена), после оформления в строке остаётся «Оштрафован дд.мм». Когда жилец придёт — «Выдать». У «Не продлено» кнопка штрафа тоже есть, но неяркая: CRM не знает, приходил ли человек, — знаете вы."},{title:"12б. Окно нарушения: сумма, оплата, снятие — одно на всю CRM",text:"Нарушение открывается одним и тем же окном отовсюду: карандаш у строки на «Нарушения → Открытые» и «Нарушения → История», карандаш в карточке жильца, кнопка «Оштрафован дд.мм» на миграционном контроле. Внутри правятся сумма и причина — кнопка «Сохранить» стоит всегда и загорается, как только вы что-то поменяли. Штраф за просрочку регистрации — ОДНА запись, которая растёт: не решил вопрос сегодня — завтра открываете тот же штраф, вписываете новую сумму и жмёте «Сохранить»; второй штраф на ту же просрочку не заводите — он повиснет вторым долгом и дважды уедет в счёт фирме. Если просрочка с оформления выросла, окно само говорит «Сегодня просрочка уже N дн.» и кнопкой «Обновить до N дн.» подставляет свежую причину; сумму за новые дни вписываете вы — сколько стоит день, знает правило объекта, а не CRM. Внизу — «История записи»: кто оформил, кто и на сколько менял, кто закрыл (из журнала действий). Нарушение с суммой — штраф: «Оплатил» (жилец отдал деньги вам, штраф закрыт и в счёт фирме не попадёт) или «Снять» (простили). Нарушение без суммы — «без штрафа» (замечание, «взять на контроль»): у него одна кнопка «Закрыть нарушение» (выполнил или сняли). Впишете сумму — оно тут же станет штрафом. Деньги пишите в поле «Сумма», а не в текст причины: «2к за казан» в причине CRM не считает долгом, и итог «Долг по штрафам» выйдет меньше настоящего. Если в причине похоже на сумму («2к», «5т», «500 р»), а поле «Сумма» пустое, под ним появится жёлтая подсказка — во всех окнах, где записывают нарушение (карточка, обход, миграционный контроль, карандаш). Сохранить она не мешает и сумму сама не подставляет: сколько это в рублях, решаете вы. Уже записанные так нарушения видны в «Нарушения → Открытые»: в строке жёлтое «сумма в тексте?», над таблицей — сколько их; откройте карандашом и впишите сумму. «Удалить» — только для ошибочно созданных (двойное нажатие): ссылка в стороне, а не кнопка. У закрытой — «Вернуть» (отметку поставили по ошибке), у оплаченной ещё «Снять (простили)». Всё пишется в журнал действий с вашим именем: это наличные. Охрана и обходчик снимают, удаляют и правят только штрафы, которые выписали сами; ваш штраф они не простят и не изменят, но оплату по нему отметить могут (жилец заплатил на посту) — отметка ляжет в журнал под их учётной записью, и по ней администратор сверяет кассу. Если окно открыто карандашом на «Нарушения → Открытые», а жилец заблокирован, под полями есть галочка «При «Оплатил» снять блок — турникет пропустит»: она стоит сама, когда это его последнее открытое нарушение и блок поставлен за нарушения. В карточке жильца, на «Жильцах» и на миграционном контроле галочки нет — блок снимают кнопкой «Снять блок» рядом."},{title:"12в. Нарушения: «Открытые» и «История»",text:"«Заблокированные → Нарушения» делится на две части, и обе — одна и та же таблица: строка = одно нарушение, колонки «Дата · Жилец · Причина · Сумма · Кто» на тех же местах. Фильтры на обеих — как на «Заблокированных» (фирма, гражданство, этаж, юр. лицо) плюс «Только штрафы / Только без штрафа». «Открытые» — кто должен сейчас: под датой написано, сколько дней висит, самый давний долг сверху (порядок меняется щелчком по заголовку колонки — «Дата», «Жилец», «Сумма»). Над таблицей — сколько записей и у скольких человек, долг по штрафам и сколько без штрафа. В конце строки: зелёная «Оплатил» у штрафа (жилец отдал наличные вам) или «Закрыть» у нарушения без штрафа (выполнил или сняли), карандаш — изменить сумму или причину, снять, удалить, и значок ⊘ — заблокировать жильца (спросит подтверждение с именем; у заблокированного значка нет, а у имени замок). Несколько человек разом: отметьте кружки слева (кружок у любой строки отмечает человека целиком, кружок в шапке — всех, кто сейчас на экране), внизу появится панель «Выбрано N чел.». В ней: зелёная «Оплатили» — бригада заплатила наличными, все открытые штрафы отмеченных закроются оплатой; «Снять штрафы» — простить их; «Изменить сумму» — поставить всем одну новую сумму (например, решили снизить штраф бригаде с 1000 до 500 ₽): CRM спросит сумму и поменяет её у открытых штрафов отмеченных, нарушения без штрафа, оплаченные и снятые не тронет, блокировку тоже, а в конце скажет «Изменено N из M» и у кого не вышло (ноль вписать нельзя — чтобы простить, «Снять штрафы»; «Отменить» вернёт прежние суммы); «Заблокировать». Перед оплатой и снятием CRM покажет, сколько штрафов, у скольких человек и на какую сумму, и список; после — итог «Оплачено 5 из 5» и кнопку «Отменить» (вернёт в неоплаченные, но блок обратно не поставит). Оплата снимает блок, только если отмечена галочка «Снять блок — турникет пропустит»: в окне оплаты она есть у каждого заблокированного (и у одной кнопки «Оплатил» в строке). Сама она стоит, когда этой оплатой у человека закрывается последнее открытое нарушение и блок поставлен за нарушения. Если нарушения ещё остаются или блок стоит по другой причине (не забрал регистрацию, долг фирмы, граница, ручной блок «за драку»), галочка снята, и под ней написано почему; поставить её можно руками. Блок снимается так же, как кнопкой «Снять блок»: турникет откроется, в журнале будет «снят блок» с вашим именем. Нарушения без штрафа пачкой не закрываются — «Закрыть» в строке, когда человек выполнил. Каждая оплата и снятие пишется в журнал отдельно, с вашим именем. Охрана и обходчик пачкой снимают только свои штрафы (про чужие окно предупредит, они останутся открытыми), а «Оплатили» отмечают по всем. Если кто-то закрыл штраф раньше вас (экран не обновлён), CRM его не тронет и скажет «уже закрыто — обновите список». В окне блокировки — список имён и причина, она попадёт в карточку каждого: если нарушение у всех одно («уборка»), подставится оно, если разные — просто «Нарушения»; поправьте, если нужно. Уже заблокированных блокировка пропускает. Кнопка «Оплатил» в строке закрывает только эту строку, остальные нарушения человека висят. «История» — все нарушения живущих: вместо кнопок колонка «Исход» (Открыт / Оплачен / Выставлен фирме / Снят; без штрафа — Открыто / Закрыто), итоги: наложено / оплачено / фирме / снято / открыто, фильтры по исходу и датам, карандаш открывает то же окно; штраф, включённый в счёт фирме, наличными не принять, пока счёт живой. На обеих вкладках у имени «×N» — сколько нарушений у человека за всё проживание (повторный нарушитель виден сразу), в колонке «Кто» — кто оформил (и в «Истории» — кто закрыл). Кнопки «Excel / Печать / Обновить» вверху страницы действуют на ту вкладку, что открыта. Уехавшие сюда не попадают; вернулся через «Вернуть из уехавших» — его старые нарушения снова видны. Оговорка над «Историей»: различать «оплачен» и «снят» CRM умеет с 17.09.2026, закрытое раньше стоит как «снят»."},{title:"12г. Штраф выставлен фирме — и автоблок за неоплату",text:"Если бухгалтер или вы включили штраф в счёт фирме, у жильца он показан как «выставлен фирме»: наличными его не принять, снять и удалить нельзя — платит фирма по счёту; ошибка исправляется аннулированием счёта в «Счетах фирмам». Отдельно: в «Настройки → Блокировки» есть правило «За неоплату фирмы» (по умолчанию выключено). Включено — через N дней после срока оплаты неоплаченного счёта проход закрывается всем жильцам этой фирмы на объекте, причина в карточке «Фирма «…» не оплатила счёт № …»; оплатили — откроется сам. Правило берёт только счета, выставленные после включения; перед включением CRM показывает, кто попал бы под него сейчас. Разблокировали человека руками — по этому счёту правило его больше не тронет."},{title:"12в2. Фирма платит несколькими юр. лицами",text:"Одна бригада, а платят за неё несколько юр. лиц — каждое за свою долю мест и по своему договору. Не заводите три фирмы и не делите людей: в «Фирмах» у карточки фирмы значок «Плательщики» (банк) — добавьте каждого плательщика с ИНН, договором и числом мест (на выбранном в шапке объекте). После этого счёт по объекту выставляется только плательщику: в форме счёта поле «Плательщик» или «Всем плательщикам» — счёт каждому, кому ещё не выставлено. Люди, сверка «живёт / оплачено» и кабинет фирмы не меняются; оплаченными считаются места по счетам всех плательщиков. Автоблок за неоплату за долг плательщика людей не блокирует (решение владельца): в «Долгах» видно, кто из плательщиков не заплатил, ему уходит письмо о просрочке (если правило на объекте включено), а что делать дальше — решает директор руками. Счёт самой фирме без плательщика блокирует, как раньше."},{title:"12в3. Одна фирма на нескольких объектах — одна карточка",text:"Карточка фирмы одна на всю сеть: название, ИНН, адрес и вход в кабинет фирмы. А цена за место, способ расчёта («за комнату» / «за место»), договор и почта для счетов у каждого объекта свои — они в той же карточке, но для объекта, выбранного в шапке: «Фирмы» → карандаш → блок «Оплата на этом объекте». Чужие условия, места, людей и счета другого объекта вы не видите и не правите. Заводите фирму, а CRM ответила «Такая фирма уже есть в сети» (совпал ИНН или название) — нажмите «Привязать к нашему объекту»: второй карточки не будет, фирма появится в вашем списке с пустыми условиями — задайте цену, договор и квоту вашего объекта. Совпало только название, а фирма другая — «Да, другая — завести отдельно». Если фирма в архиве — попросите директора вернуть её. Общую почту фирмы, которая работает и на других объектах, меняет директор; почту для счетов вашего объекта задайте в поле «Почта для счетов этого объекта». Убрать в архив или удалить фирму, которая работает и на других объектах, может только директор. Директор в режиме «Вся сеть» видит все фирмы и их условия по каждому объекту — только просмотр; править — выбрав объект."},{title:"12д. Сверка «Фирмы → Сверка»: сколько живёт и сколько мест держим",text:"Сверять вручную не нужно — CRM считает это сама каждую ночь по всем фирмам объекта, и отметки «сверено» здесь нет. Вкладка нужна, когда что-то разошлось: красное — «живёт больше, чем оплачено» (это недополученные деньги, разберитесь с фирмой) и «обещали убрать лишних — не убрали»; жёлтое — «пустуют места» и «числятся, но по турникету не живут» (просто к сведению). Красное приходит утром в письме-сводке. «Оплачено» — это места по счёту за текущий месяц, а если счёта нет — квота фирмы; комнаты тут ни при чём, они показаны серой колонкой как справка. Строка «Без фирмы» — люди, за которых счёт не выставляется никому, поэтому итог сходится со списком жильцов. Разобравшись, нажмите «Записать решение» и выберите, о чём договорились: оставляют (с даты поднимаем места — CRM поднимет их сама в этот день), уберут лишних до даты (до неё строка молчит, не убрали — вернётся красной), только доплата (уйдёт в следующий счёт), наша ошибка учёта (люди числятся не за той фирмой или не выселены — строка останется, пока не поправите карточки). Комментарий обязателен: через месяц отвечать фирме будете им. Галочка «Написать фирме» отправит письмо без фамилий жильцов. Деньги не потеряются, даже если вы сюда не заходили: доплата за дни сверх оплаченного посчитана и будет предложена строкой в следующем счёте."},{title:"12е. Список от фирмы",text:"Бригадир прислал файл «вот наши люди» — кнопка «Список от фирмы» на вкладке «Сверка»: выберите фирму, приложите файл как есть (Excel или CSV, переделывать не нужно; если файл в старом формате Excel .xls — CRM скажет, как его пересохранить), CRM сама найдёт колонку с ФИО, а дату рождения и паспорт возьмёт, если они там есть. Дальше четыре группы: «совпали», «у фирмы есть — у нас нет» (с подсказкой, где человек у нас: за другой фирмой, на другом объекте или выселен — людей CRM ищет по всей сети), «у нас есть — у фирмы нет» (за них вы выставляете счёт, а фирма своими не считает — самый частый спор) и «похожи, подтвердите». Последняя группа — это латиница, отсутствующее отчество, перепутанный порядок слов и тёзки: CRM не склеивает людей сама, потому что перепутать двух мигрантов хуже, чем спросить. Сам файл нигде не сохраняется, в истории остаётся только итог; загрузка записывается в журнал действий — это персональные данные, пришедшие со стороны."},{title:"12ж. Сверка со списком фирмы: уволенные, лишние, на выселение",text:"«Жильцы» → «Сверить с фирмой». Окно открывается почти во весь экран; кнопка «—» сворачивает его в плашку справа внизу — можно сходить в «Жильцы» и вернуться, всё прочитанное и отмеченное сохранится. Найдите фирму поиском (в списке только фирмы этого объекта) и выберите, что она прислала. Фирму можно не выбирать — например, на руках фото регистраций уехавших, а чьи они, неизвестно: тогда CRM ищет людей по всем фирмам, «совпал» значит «живёт на этом объекте», группы «Лишние» нет, и в историю такой поиск не записывается. Список можно приложить фото (несколько страниц сразу; фото регистраций — бланков уведомления о прибытии — тоже, по одному человеку с бланка), PDF или Excel — или вставить текстом прямо из сообщения в WhatsApp/Telegram. Дальше CRM показывает, что прочитала, рядом с самим файлом: исправьте опечатки, удалите лишнее. Шапку бланка, подписи, «Резерв» и «бронь» CRM отбрасывает сама — они лежат внизу под «Отброшено строк», и любую можно вернуть кнопкой «Вернуть в список». После «Сверить с CRM» — одна таблица: слева кто в списке фирмы, справа кто у нас (комната, объект, фирма), справа итог. Сверху переключатели: «Совпали», «Похожи», «Нет у нас», «У нас, но не тут», «Лишние», «В списке, но заблокирован / фирма выселила». Нажмите на ФИО справа — откроется карточка жильца. У «похожих» — кнопки «Это он» / «Не он»; у тех, кого CRM не нашла, — «Найти другого» (поиск по всей сети, если в списке опечатка). Внизу по отмеченным галочкам: «Заблокировать», «Отметить «фирма выселила»», «Заблокировать и «фирма выселила»», а для тех, кто уже заблокирован или с этой отметкой, — «Разблокировать» и «Снять «фирма выселила»». Проход по пропуску закрывается и открывается сразу; причина блокировки подставляется сама. «Выселить» — обычное выселение отмеченных: человек уходит в «Уехавшие», пропуск снимается с турникета сам, с миграционного учёта снимаете как обычно из «Уехавших». В задаче «Уехали или на выселение» найденные на объекте отмечены заранее; выселяются только живущие на этом объекте. Крестик закрывает окно; если итог сверки с фирмой ещё не записан в историю, CRM спросит: «Записать и закрыть», «Закрыть без записи» или «Отмена» — сама, без вашего слова, ничего не записывает. Файлы и текст нигде не сохраняются, загрузка и каждое действие пишутся в журнал."},{title:"12з. Кто остаётся, кто уезжает: отметки «Подтверждён» и «Не продлён»",text:"Фирма прислала, кто живёт в следующем месяце. «Сверить с фирмой» → выберите фирму и задачу «Кто живёт в следующем месяце — найти лишних», загрузите список. Совпавшим: отметьте галочками → «Подтверждён на …» (месяц можно поменять в окне). Лишним: «Лишние» → галочка в шапке таблицы → «Не продлён — уезжает до…», дата по умолчанию — последний день месяца. Это отметки, а не блокировка и не выселение: пропуск работает, счёт и сверка мест не меняются, пока человека не выселили. Отметка видна в «Жильцах» и в карточке; в фильтрах появится ряд «План»: «Не продлены», «Пора выселять», «Подтверждены», «Без отметки». В день выезда на «Главной» и в «Жильцах» будет строка «Сегодня по плану уезжают: N чел.» с кнопкой «Выселить всех»: сначала список фамилий, потом подтверждение; нажимаете вы, сама CRM никого не выселяет. Не выселили в срок — человек остаётся в этой строке («Срок выезда прошёл»), пока его не выселят или не снимут отметку. Передумали: в карточке — другая дата или «Снять отметку»; несколько человек сразу — «Снять отметку плана» в панели выбранного в «Жильцах» или «Снять отметку» в окне сверки, кнопка видна, когда выбраны люди с отметкой. Новая отметка заменяет прежнюю: фирма вернула человека в список — поставьте «Подтверждён». Подтверждение действует до конца своего месяца. Перевели человека на другую фирму — отметка перестаёт действовать. Выселение снимает её само. Ставит отметки администрация, только людям выбранной фирмы на своём объекте; каждая отметка пишется в журнал действий."},{title:"12з2. Фильтры: несколько сразу и «все, кроме»",text:"Гражданство, этаж и юр. лицо на «Жильцах», «Миграционном контроле», «Заблокированных», «Нарушениях» и «Уехавших» можно выбрать несколько сразу. В «Гражданстве» отмечайте страны по одной; повторное нажатие снимает галочку. Нужны все, кроме одной страны (например, «без граждан России»), — нажмите «— Выбрать все», затем «Россия»: в поле появится «Все, кроме: Россия», и в списке останутся все остальные — и люди без гражданства («Не указано»), и страны, которых сегодня нет вовсе (заселится первый туркмен — его будет видно). Разные написания одной страны («УЗБ» и «Узбекистан», «РФ» и «Российская Федерация») считаются одной страной. Этажи и юр. лица — кнопками: нажали «2 эт» и «3 эт» — видны оба этажа, повторное нажатие снимает, «Все» — сброс. Фильтр помнится, пока открыта вкладка браузера; на «Миграционном контроле» над списком тогда написано «Показано N из M — остальных скрывает фильтр» с кнопкой «Показать всех» — чтобы не забыть, что часть людей скрыта, и не пропустить им продление регистрации."},{title:"12и. Кнопка скана: «Без патента» и «Скан патента»",text:"Кнопка скана в строке миграционного контроля говорит, что лежит в карточке. «Скан» — скана нет. «Скан есть» (зелёная) — всё на месте. «Без патента» (серая) — скан есть, а действующего патента в карточке нет: так у каждого новичка первые недели, тревоги здесь нет — сроки подачи на патент считает колонка «Патент / РНР». «Скан патента» (жёлтая) — патент внесли в карточку позже последнего скана, значит, на скане его нет. Обычный порядок: жилец пришёл продлевать регистрацию с патентом → «Изменить» → «Патент выдан» → «Сохранить» → кнопка становится «Скан патента» → отсканируйте паспорт, миграционную карту и патент вместе и нажмите её. Новый скан добавляется, прежний остаётся в карточке. Скан и патент в один день — это один визит, какую кнопку нажать первой, неважно. У визовых (Туркменистан, Китай…) вместо патента РНР — «Без РНР» и «Скан РНР». То же видно в карточке жильца: на вкладке «Документы» под «Добавить скан» — «Нужен новый скан: патент внесли позже последнего скана»."},{title:"12к. Выселяете того, кто сейчас внутри: 30 минут на сборы",text:"Окно «Выселить» в карточке само проверяет по турникету, где человек. Если он в здании, окно пишет «Сейчас в здании — вошёл в 17:20», и прямо в этой жёлтой плашке — кнопка «Дать 30 минут собрать вещи»: человек пока остаётся как был, пропуск работает, выйти он может сам, без охраны; в карточке и в списке жильцов у него пометка «Собирает вещи — до 18:45». Через 30 минут у вас в правом нижнем углу любого экрана появится карточка «проверить, вышел ли» — с фото, комнатой и тем, что видит турникет: «Вышел через турникет в 18:42» или «Ещё внутри». Кнопки: «Подтвердить выезд» (жилец уходит в «Уехавшие», пропуск закрывается; дата выезда — время его выхода через турникет), «Ещё 30 минут», «Отменить». «Выселить» — сразу: вход закрывается тут же, а выход (где есть терминал «выход») остаётся открытым на сутки — человек выйдет сам, без охраны и без красной тревоги; первый выход закрывает пропуск на всех терминалах (в журнале проходов — пометка «вышел после выселения», в карточке — «Вышел после выселения в 18:42»), не вышел за сутки — выход закроется сам. Дата выезда, МВД и счёт фирме от этого не зависят: дата выезда — момент выселения. После «Подтвердить выезд» тому, кто ещё внутри, оставляется тот же выход на сутки. Если выселяете через галочки в списке, окно так же показывает, кто из выбранных сейчас в здании, — у каждого своя кнопка «Дать 30 минут» (а если таких несколько — ещё «всем, кто внутри»); кому дали время, тот из выселения уходит, «Выселить» выселит остальных."},{title:"12л. Заблокированный подходил к турникету",text:"Если заблокированный подходил к турникету с момента НЫНЕШНЕЙ блокировки, это видно под фамилией в карточке: «Подходил к турникету с закрытым пропуском: 4 раза с блокировки 5 окт. · последний раз — выход, 11 окт. в 15:40», а в списке «Заблокированные» — пометкой «Подходил ×4». Попытки из прошлых блокировок не показываются: разблокировали — строка пропадает. Главное — попытка на ВЫХОДЕ: красная строка «Подходил к выходу — значит, был внутри» и пометка «Был внутри» в списке. Как он попал в здание — вопрос к охране и к камерам. CRM видит турникет, а не человека: это повод проверить, а не доказательство."},{title:"12м. Вернулся с границы, а турникет закрыт",text:"Уехавший за новой миграционной картой ходит без проходов, и через двое суток CRM закрывает ему турникет — так задумано: закрытый турникет приводит его к вам. В причине блока написано «Уехал на границу — по возвращении нужны новая миграционная карта и новое уведомление в МВД», в карточке рядом с «Заблокирован» — жёлтая метка «С границы: новая мигкарта и уведомление в МВД». Старая регистрация к его возвращению снята, и пока вы не подали новую, человека нет в базе МВД: при проверке это штраф хостелу (ст. 18.9 КоАП). Порядок: примите новую миграционную карту, снимите галочку «Уехал на границу» (форма карты откроется сама), подайте новое уведомление о прибытии — и только потом «Разблокировать». Окно разблокировки напомнит об этом, но не запретит: решаете вы. При массовой разблокировке окно пишет, сколько среди выбранных вернувшихся с границы."},{title:"12н. Уехал с долгом",text:"Выселение штраф не останавливает и ни о чём не спрашивает. Уехавший из «Нарушений» исчезает (там только живущие), зато в «Уехавших» у него бейдж: красный «Нарушение» (несколько — «Нарушение ×2»), если не закрыто, и серый «Нарушения ×N», если всё закрыто. Суммы в списке нет — ни на экране, ни в Excel: сколько и за что, смотрите в карточке. При возврате вы сразу видите, что за человеком что-то числится; закрыть долг — из карточки («Нарушения»), а после «Вернуть из уехавших» он снова появится в «Открытых»."},{title:"12о. Галочка «Не на учёте» в карточке",text:"Серая галочка «Не на учёте» с подписью «Снят с учёта, место держится» — для того, кого вы уже сняли с миграционного учёта, а место за ним держите: например, уехал в командировку. Он не на учёте и не в «Уехавших»; в списке у него серая метка «Не на учёте», фильтр и плитка с тем же названием. После выезда CRM не напоминает снять его с учёта — он уже снят. Сама галочка в МВД ничего не подаёт: снятие подают как обычно, а галочку ставят, когда оно подано. Вернулся и вы снова поставили его на учёт — снимите галочку. Ставят и снимают её только администратор и директор."},{title:"12п. Какие вкладки миграционного контроля у вас и почему",text:"Всегда есть: «Сегодня», «Просрочка», «Патент / РНР» (РНР — разрешение на работу), «Согласия», «Не подать». Остальные появляются от того, как работает объект («Настройки» → «Объект» → «Миграционный учёт»): «Продление» — если в сети есть объекты на Контуре или Госуслугах (шаг 23б); «Сверка учёта» и «Реестр МВД» — на объекте с бумажными уведомлениями или с подачей через Госуслуги (шаги 12р и 12с); «Госуслуги» — только если уведомления подаёт сама CRM (шаг 24); «Сверка с Контуром» — если у сети есть объект на Контуре (шаги 20–23). Нет вкладки, о которой говорит коллега, — это не поломка: ваш объект работает иначе. Режим объекта задаётся в «Настройки» → «Объект» → «Миграционный учёт»."},{title:"12р. Бумажный учёт: «Реестр МВД»",text:"Нужен там, где уведомления печатают на бланках и носят в МВД (и там, где подаёт CRM через Госуслуги): базы МВД у нас нет, поэтому реестр — единственное место, где видно, что поданное дошло. Бланки появляются в реестре сразу, как только вы напечатали их кнопкой «Бланки МВД» на вкладке «Сегодня». Вверху фильтр по состоянию: «Все», «Напечатано», «Отнесено», «Талон вернулся», «Не приняли». Каждая строка — одно уведомление, «Прибытие» или «Убытие», с датами. Ход бумаги отмечается кнопками в строке: «Напечатано» → «Отнесли в МВД» → «Талон вернулся» (можно вписать номер отрывной части) или «Не приняли» (CRM спросит причину, без неё непонятно, что переделывать) → «Переделали». Ошибочное — «Отменить»: запись останется с пометкой «отменено», стирать нельзя. Повторная печать даёт ровно то, что подавали. Главное: только отметка «Талон вернулся» считается подтверждением, что человека поставили на учёт; пока её нет, утренняя сверка держит уведомление в списке «талон не вернулся»."},{title:"12с. Бумажный учёт: «Сверка учёта»",text:"Вкладка сама отвечает на вопрос «кого мы забыли подать или снять». Считает CRM по нашему реестру поданного (не по базе МВД). Наверху — сколько жильцов проверено, срок подачи в рабочих днях и время расчёта, кнопка «Пересчитать». Ниже — группы, красные срочные, жёлтые «стоит посмотреть». Красные: «Заселён, уведомление не подано», «Срок подачи истекает», «Выселен, с учёта не сняли», «Выселен, убытие подать до 12:00 сегодня». Жёлтые: «Выселен, убытие ещё не подано», «Учёт истекает», «Учёт истёк, человек живёт», «На учёте, срок не указан» (впишите «регистрация до» в карточку), «Талон не вернулся» и «На учёте, но по СКУД не живёт» (это повод разобраться, а не вывод). У каждого в группе — причина и срок («подать до …»). Подали уведомление, которого нет в реестре (например, поданное до перехода на CRM), — в группах про подачу и снятие есть «Отметить всех»: нажмите один раз вместо отметок по одному. «Расхождений нет» значит: все, кто живёт, поставлены на учёт, все, кто уехал, сняты, сроки в порядке. На объекте с Контуром вкладка пишет «эта сверка для него не считается» — для него есть «Сверка с Контуром»."},{title:"13. Массово по нескольким людям",text:"Отметьте галочками нужных жильцов (всю комнату — галочкой в шапке комнаты) — внизу появится панель: «Штраф», «Заблокировать», «Переселить», «Фирма выселила», «На границу», «Согласие подписано», а справа за чертой — красная «Выселить». Обратные кнопки появляются сами, когда среди отмеченных есть к кому их применить: «Снять блок», «Снять «Фирма выселила»», «Вернулись с границы». После отметки «Фирма выселила» и «На границу» на месте панели — итог («Отправлено на границу 6 из 6») и кнопка «Отменить»: ошиблись людьми — одно нажатие возвращает как было. Справа в панели — «Снять выделение». «Фирма выселила» — только отметка со слов фирмы: человек остаётся в хостеле, пока вы не нажмёте «Выселить». Галочки не снимаются при поиске и смене фильтра: если отмечен кто-то, кого сейчас не видно, панель так и пишет — «из них скрыто фильтром: N», — а окно выселения показывает поимённо, кого выселяем. Убрать скрытых — ссылкой в панели. «Штраф» записывает КАЖДОМУ своё нарушение с одной причиной и суммой — оплачивается, снимается и выставляется фирме у каждого отдельно; сумма 0 — нарушение без штрафа. «Заметка» ДОПИСЫВАЕТ текст к заметке каждого отмеченного новой строкой с сегодняшней датой («24.10.2026: уехал в командировку»); то, что было написано раньше, остаётся. В том же окне можно выбрать «Заменить» (прежняя заметка у всех отмеченных стирается, ставится новый текст, без даты) или «Удалить» (заметки очищаются): окно спросит, у скольких человек заметка пропадёт, а прежний текст останется в журнале действий. Ошиблись одной строкой — режим «Убрать строку»: впишите кусок её текста, регистр не важен; уберутся только строки с ним, остальное в заметке останется. Окно покажет, у скольких человек и какие строки совпали: проверьте, нет ли там лишнего. Оплатить или снять штрафы пачкой — на «Заблокированные → Нарушения → Открытые». После «Штрафа» и «Заблокировать» галочки остаются: за непорядок в комнате — оба действия подряд, в любом порядке, причина во втором окне подставится сама. После остальных действий галочки снимаются. «Excel» и «Печать» в шапке спрашивают, что выгрузить: «Все места, со свободными» (пустые койки — отдельными строками) или «Только занятые»; выделенных выгружают и печатают без пустых мест. «Продлить срок пребывания на 90 дней» (администрация): «Регистрация до» у выбранных = около 90 дней от сегодняшнего дня (30.10 → 27.01), а у патентных — последнее «число патента минус день» в этих пределах (патент выдан 04.02 → 3-е число: 03.01), и не дальше срока документов (патент считается за день до срока); сначала покажем «было → станет» и кого пропустим (заблокирован, срок уже вышел — дату ставьте вручную, нет срока, гражданин РФ), потом спросим."},{title:"13а. «Постельные принадлежности» → «Заявки» пачкой",text:"«Постельные принадлежности» → «Заявки»: у каждой позиции (матрас, подушка, КПБ) слева кружок, в шапке карточки жильца — кружок «все его заявки», над списком — «Отметить все (N)». Отмеченные — из любых карточек сразу. Внизу панель: зелёная «Выдать выбранные» (CRM переспросит; со склада спишется столько же), «Нет на складе», «Отказать» (одна причина на всех, сохранится у каждой заявки) и за чертой красная «Удалить» — только для мусора: дубль, случайное нажатие. После действия на месте панели итог: «Выдано 12 из 13», по кому не вышло — имя и причина (например, бельё ему менять ещё рано). Ошиблись — «Отменить выдачу» в итоге вернёт всё на склад, как кнопка на вкладке «Выданные». «Выдать» по одной позиции и «Выдать всё (N)» в карточке жильца остались как были."},{title:"13б. Прачечная отказала жильцу — где посмотреть почему",text:"Карточка жильца → «История» → «Бельё и оснащение»: рядом с выдачами — «Отказ в выдаче» (оранжевым; причина: рано — с датой и временем прошлой выдачи и кто выдал, или выселен) и «Повторный скан — не записано» (серым), со временем и тем, кто сканировал. Все такие события — и по номерам, которых нет ни у кого, — в «Журнале действий»: «Бельё: отказ в выдаче», «Бельё: повторный скан — второй раз не записано». Отказ «рано» через минуту после выдачи — повторно прочитанная наклейка, бельё человек получил."},{title:"14. Журнал обхода",text:"Здесь видно, что реально делал обходчик: кто на месте, где не убрано, кого отправили в администрацию (не забудьте отмечать «Пришёл», когда человек дойдёт). В блоке «Что сломано и что просят» сделанное можно закрыть сразу пачкой: отметьте записи кружками (или «Выбрать все»; сверху можно оставить только поломки, просьбы или заметки) и нажмите зелёную «Сделано» в панели внизу — CRM переспросит, сколько записей закрывает. Вернуть закрытую запись в список нельзя, поэтому отмечайте только то, что действительно сделано. В открытом задании можно отметить исход сразу нескольким — кружки у жильцов и панель внизу, или «Отметить всех оставшихся». Задания обходчику создаются во вкладке «Задания» → «Новое задание»: среди шаблонов есть «Кто внутри по СКУД» — список тех, кого турникет считает внутри прямо сейчас (цифра показана до создания, та же, что на «Главной»); обходчик проверяет, что они на месте. Любое задание можно сразу распечатать — кнопка «Создать и напечатать» (или «Печать» внутри задания): на бумаге список с пустыми клетками «на месте / нет», на случай, когда планшета нет. Подробно — в гайде обходчика на этой же странице."},{title:"15. Экран «Сотрудники»",text:"Один человек — одна карточка: если у человека несколько записей (администратор на двух объектах — это два входа, у входа одна роль и один объект; старый логин; пропуск), директор объединяет их — в панели человека «Объединить с…», отметить его другие записи. Подсказывает вкладка «Похожие»: «Леха» и «Слизкий Алексей», одна фамилия и имя — решаете вы («Объединить в одну карточку» или «Это разные люди»). Объединение не меняет ни ролей, ни объектов, ни паролей: в строке появляется «+N записи», в карточке — список записей с кнопкой «Открыть»; лишний вход откройте и нажмите «Отключить доступ» (история останется). Ошиблись — откройте запись и «Отделить от карточки». Администратор объекта видит в карточке только записи своего объекта. Раздел один: отдельного экрана «Пропуски сотрудников» больше нет — всё, что там делалось (завести пропуск, сфотографировать, изменить объекты, уволить, открыть карточку пропуска), — в панели человека здесь. Охрана по этому же пункту меню видит только пропуска, без логинов и ролей. Одна строка — один человек, а не одна запись. Колонка «Доступ» говорит, что у него есть: «CRM» — заходит в программу, «Пропуск» — проходит через турникет, «Без фото» — пропуск заведён, но фотографии нет и турникет по нему не откроется. Бывает и то и другое, бывает что-то одно: под общей учётной записью вроде «Охрана м18» работают разные люди, и пропуска у неё нет, а у кого-то наоборот — есть пропуск на турникет, а логина в программу нет: по работе не нужен. Нажмите на строку — справа откроется всё про человека: доступ, пропуск и его последние действия. Вкладка «Требуют внимания» собирает два случая: учётные записи, которыми давно или ни разу не входили (их стоит отключить — чужой доступ, о котором забыли, это дыра), и пропуска без фотографии. Ничего из этого система не выключает сама — решаете вы. Сверху слева выбирается, чьих сотрудников показывать: свой объект или все сразу. Сотрудника, который у нас только работает (пропуск без комнаты), в списке «Жильцы» нет — он виден здесь и на «Пропусках сотрудников». Сотрудник, который живёт в комнате для персонала, — жилец: он есть и в «Жильцах»."},{title:"16. Как завести сотрудника или пропуск",text:"Кнопка «Добавить» сначала спрашивает «Кого заводим?»: логин в CRM или только пропуск на турникет — для тех, кому программа не нужна (техник, директор без рабочего компьютера, охрана другой смены). Выбрали «Сотрудник — вход в CRM»: ФИО, логин (это не обязательно почта — можно просто «ivanov_admin»), роль и объект. Под ролью написано, что она даёт: не помните разницу между охраной и обходчиком — прочитайте там же. У директора сети под каждой ролью в том же списке стоят её шаблоны доступа («Администратор» → «— Ночной администратор»): выберите шаблон — человек заведётся этой ролью и сразу будет видеть только то, что оставлено в шаблоне. ОБЪЕКТ ОБЯЗАТЕЛЕН всем, кроме директора и бухгалтера: администратор, охрана, прачечная и обходчик работают на одном объекте, и без него такой сотрудник войдёт в программу, но экраны будут отвечать ошибкой. Система подставит объект, выбранный у вас сверху, и не даст сохранить пустой. Пароль придумывается сам и показан открыто (другой — кнопка «Предложить надёжный») — его надо прочитать и передать человеку; после сохранения он показывается последний раз, дальше его можно только задать заново. Этот пароль временный: при первом входе система сама попросит сотрудника задать свой — вам ничего заново объяснять не нужно, это займёт у него минуту. То же самое произойдёт, если вы сами меняете пароль сотруднику (например, он забыл свой): следующий вход он начнёт с той же формы. Выбрали «Только пропуск на турникет»: только ФИО и объекты, куда человек проходит — ни логина, ни пароля нет и не будет. Фото добавляется сразу после сохранения, из панели человека (кнопка «Сделать фото»): без фото турникет не откроется, и такой пропуск попадёт в «Требуют внимания». Доступ сотрудника не удаляют, а отключают — тогда он не войдёт, но останется в списке вместе со всей историей своих действий; в любой момент можно вернуть."},{title:"16а. Вход и пропуск одному человеку, увольнение",text:"Администратору, который сам ходит через турникет, нужны обе вещи: логин в CRM и пропуск. Это две записи, но заводить их по отдельности и потом искать, как связать, не нужно — всё делается из панели человека. У человека есть только пропуск: откройте его строку, в блоке «Доступ в CRM» нажмите «Создать вход в CRM» — ФИО и объект уже подставлены, выберите роль, придумайте логин и передайте временный пароль; вход сразу привязан к пропуску. Если логин у этого человека уже есть — «Привязать существующий логин» и выберите его из списка (общие учётки вроде «Охрана м18» не привязывайте: под ними работают разные люди). У человека есть только логин: в блоке «Пропуск на турникет» нажмите «Завести пропуск» — ФИО подставлено, отметьте объекты, сохраните и сделайте фото; готовый пропуск — «Привязать пропуск». В любом случае в списке остаётся одна строка с метками «CRM» и «Пропуск». Сотрудник, который ЖИВЁТ в хостеле, заселяется как жилец («Жильцы» → «Заселить» в комнату «для персонала») — с паспортом и учётом в МВД, как все; к логину его привязывают так же. Человек уволился — откройте его строку и нажмите «Уволить» в блоке пропуска: снимется пропуск со всех турникетов и отключится вход в CRM, история его действий останется. Кнопка «Отключить доступ» закрывает ТОЛЬКО программу — пропуск остаётся, и человек продолжит проходить. Администратор объекта работает только со своим объектом: заводит пропуска на свой турникет и связывает логины своего объекта, а в пропуске, который действует на нескольких объектах, может убрать или добавить только свой. Пропуск на другие объекты и галочку «Все объекты сети — и новые тоже» (с ней пропуск сам начнёт действовать в каждом новом хостеле), а также роль «Бухгалтер» выдаёт директор. Свою роль не меняет никто."},{title:"17. Пароли сотрудников и выход из системы",text:"Свой пароль каждый меняет сам: нажмите на своё имя внизу меню слева — откроется «Мой профиль» («Сменить пароль», тема). Пароль — не короче 8 знаков, с буквой и цифрой, не из самых частых («qwerty123», «Password1») и не повторяет логин или имя; такой система не примет и скажет почему. На форме «Придумайте свой пароль» есть кнопка «Предложить надёжный пароль»: он сразу виден, рядом «Копировать» — сохраните его в менеджере паролей или запишите. Меняете пароль СОТРУДНИКУ из экрана «Сотрудники» — все его открытые вкладки закрываются сразу, и следующий вход он начнёт с формы «Придумайте свой пароль» (то же самое, что при заведении). Меняете пароль себе тем же способом — тоже выкинет, входите заново. А если пароль меняет сам человек на этой форме «Придумайте свой пароль» — его не выкидывает: программа сама подставляет новый вход, и он продолжает работать без повторного входа. Уволенный сотрудник (галочка «активен» снята) теряет доступ на следующем же нажатии."},{title:"17а. Один человек — несколько записей в «Сотрудниках»",text:"Если у человека два входа, старый логин и отдельный пропуск, в списке они стоят разными строками. В карточке человека — «Объединить с…»: отметьте его другие записи (сверху CRM подсказывает похожие по имени, но решаете вы) и нажмите «Объединить». Роль, объект и пароль каждой записи остаются своими, доступы не меняются; передумали — «Отделить». Фото сотрудника для пропуска снимается в его карточке-пропуске (камера браузера); после сохранения CRM сама отправляет фото на терминалы. «Уволить» убирает пропуск со всех терминалов."},{title:"18. Что система уничтожает сама",text:"Фотография уехавшего — через 90 дней после выселения, сканы документов — через год (сроки в политике обработки данных). Карточка, реестр уведомлений МВД, согласия и журнал действий остаются навсегда. Каждую ночь приходит письмо, что удалено и по каким объектам. Вернулся человек — пропуск оформляется заново, одно нажатие в карточке."},{title:"18а. Снимок постороннего у турникета",text:"Терминал присылает снимок человека, которого не знает. CRM хранит его, только если он стал уликой в «СКУД → Проверить по камере» (жилец тут же открыл турникет второй раз), — 30 дней, потом стирает сама; остальные стираются в ту же ночь. Каждый просмотр снимка записывается в журнал действий. Это изображение постороннего человека: в политике обработки данных вашего объекта должна быть строка о нём (заготовка — п. 3.4 и 6.7, утверждает юрист)."},{title:"18б. Сигнал «Проверить по камере» у администрации",text:"Красные карточки «Возможно, провёл постороннего» (жилец открыл турникет, рядом был человек без пропуска, и открыл снова) и «Незнакомый выходил изнутри» звучат у администрации сразу, как у охраны: посторонний в здании, реагировать нужно в моменте. Звук стихает у всех, когда кто-то нажмёт «Иду проверять». Оранжевые «Открыл турникет 3+ раза подряд» — работа охраны: в углу экрана администрации их нет, они видны в «СКУД» → «Проверить по камере». Если охрана не взяла красный случай за 3 минуты, на карточке так и написано, и сигнал повторяется. Колокольчик в шапке и число на пункте «СКУД» показывают, сколько случаев ждут решения. Не разобранные за неделю случаи и жильцы с двумя и больше подтверждёнными случаями за месяц попадают в утреннее письмо (по номеру комнаты, без имени). Карточку «Заблокированный у турникета» (заблокированный пробует пройти) видит только охрана. На объекте, где охраны у турникета нет, директор включает её и для администрации: «Настройки» → «Уведомления» (раздел объекта) → «Заблокированный у турникета — показывать администрации»."},{title:"18в. «СКУД» → «Турникеты»: сверка терминала с CRM",text:"Вкладка есть на объектах с Hikvision (на ZKTeco её заменяют экраны «Здоровья СКУД»). Сверху — карточка каждого терминала: «На связи», «Давно молчит» (не выходил на связь больше 15 минут) или «Ошибка» с текстом, сторона — вход или выход. Ниже — «Расхождений: N» или «Расхождений нет» и кнопка «Сверить сейчас»: CRM спрашивает терминалы и сравнивает с карточками жильцов. Четыре списка: «Недостаёт на терминале» (человек живёт, а на терминале его нет — не пройдёт), «Лишние на терминале» (там тот, кого быть не должно, например выселенный), «Неверный статус доступа» (в CRM и на терминале по-разному: заблокирован или нет) и «Полная сверка» (все строки; можно оставить только расхождения). В строке — «Исправить» (отправить человека на терминал заново) или «Убрать с терминала». «Отправить всех на терминал» — при запуске объекта или замене терминала; по умолчанию вместе с допущенными сотрудниками. Команды доезжают не мгновенно: подождите и нажмите «Сверить сейчас» ещё раз. Не помогло — «Здоровье СКУД»."},{title:"18г. «Здоровье СКУД» и «Все инструменты разбора»",text:"Вкладка «Здоровье СКУД» отвечает одной строкой: «Турникеты в порядке» или «Проблем: N» (подробно — статья «Здоровье СКУД» в разделе «Проходы и СКУД»). Внизу кнопка «Все инструменты разбора» открывает экраны для случаев, когда что-то не так; в обычный день заходить туда не нужно. «Очередь Hikvision» (или «Очередь ZKTeco») — жильца завели, а турникет не пускает: видно, какая команда терминалу не прошла и почему. «Отчёт сверки ZKTeco» — поимённо, кого на устройстве быть не должно и кого не хватает; что исправить, отмечаете вы. «Дубли СКУД» — один человек заведён на турникете дважды, например после повторного заселения. «Логи терминалов» — тонкий разбор, что ответило устройство; видит разработчик. Вкладки «Здоровье СКУД» и «Оборудование и настройка» есть у администратора и директора, у охраны их нет."},{title:"19. Бумажный учёт: вернувшийся — это новый заезд",text:"На объекте с бумажными уведомлениями учёт считается по текущему заезду. Уехал и вернулся — нужна новая бумажка, старая ничего не покрывает; сверка покажет «не подано». Отметка «подано» вернувшемуся заводит новую запись, старая с отметкой МВД не трогается. Отметка без даты «на учёте до» попадёт в жёлтую группу «срок не указан» — впишите дату в карточку."},{title:"20. Сверка с Контуром: карточка по клику и опечатки",text:"«Сверка с Контуром» — вкладка «Миграционного контроля» (рядом со «Сегодня», «Просрочкой» и остальными; прежний пункт меню и старые ссылки ведут туда же). В списках «есть в CRM, нет в Контуре» и «есть в Контуре, нет в CRM» ФИО подчёркнуто — нажмите, откроется карточка жильца (заблокировать, поправить, посмотреть документы). Если в двух списках почти одно и то же имя (разница в букву — «Рахматулла» и «Рахматулло»), система пишет под строкой «похоже на карточку: …» и показывает кнопку «Переписать как в Контуре». В Контуре лежит то, что подано в МВД, поэтому CRM подтягивается к нему, а не наоборот; заглавные буквы Контура приводятся к обычным. Кнопка есть у директора и администратора, действие пишется в журнал, обе строки помечаются обработанными — расхождение уйдёт при следующей ночной сверке. Совсем разные имена система парой не считает и кнопку не показывает: это разные люди."},{title:"20а. «Нашёлся ли в Контуре» — прямо в карточке",text:"Ночная сверка с Контуром каждую ночь проверяет, есть ли каждый живущий иностранец в кабинете Контура. Итог по человеку виден в его карточке: во «Документах» — строка «Ночная сверка с Контуром» («найден при сверке 24.10», «не найден», «тёзки», «не сравнивала», «сверки ещё не было»), а на «Основном» красным — только если его в Контуре нет. «Не найден» значит: уведомление, скорее всего, не загружено — загрузите файл «CSV» из строки жильца в кабинет Контура. Тёзки — в CRM двое с одним ФИО, а в Контуре меньше: по ФИО не понять, кого нет, проверьте в кабинете. Граждан РФ ночная сверка не проверяет: у них в той же строке — итог последней проверки кнопкой «Проверить граждан РФ» на вкладке «Сверка с Контуром» (совпал ли срок в Контуре со сроком в CRM, нашлось ли дело). Отчёт проверки граждан РФ на вкладке «Граждане РФ» хранится, пока проверку не нажмут снова, и у каждой строки сказано, что делать: «Дела нет» — скачайте «Файл для Контура» и подайте уведомление; «Уехал, а в Контуре на учёте» — «Файл на снятие»; «Продлите» — срок в Контуре кончается или раньше, чем в CRM; «Впишите срок» — кнопка запишет в карточку срок из Контура (с историей и журналом; бухгалтеру кнопка не видна). Проверка заодно читает в Контуре список проживающих граждан РФ: уехавшего, который там всё ещё числится, отчёт покажет «снимите с учёта», а тех, кого в CRM нет вовсе, — списком «сверьте в кабинете». Фильтр «Требуют действия» оставляет только тех, с кем надо что-то сделать. Если в отчёте проверки у человека «не проверен» — робот не смог открыть кабинет Контура или дождаться поиска; это не «дела нет», и в карточку такой итог не пишется (там остаётся прошлый) — повторите проверку; если под отчётом написано, что робот не смог войти в кабинет, проверьте его логин и пароль в настройках объекта. Если в строке «ночная сверка не проходила с …» — сверка не работает, сообщите разработчику. Проверка читает список проживающих в кабинетах Контура за один заход, поэтому идёт минуты; отдельно робот ищет только тех, кого в списке нет. Если список в кабинете не открылся, робот ищет там людей по одному, и проверка идёт дольше, бывает около часа; под отчётом написано, в каком кабинете так вышло. Под кнопкой написано, сколько проживает в Контуре и сколько в CRM, и названы расхождения: кого нет в CRM, кто живёт на другом объекте или без гражданства РФ в карточке, тёзки."},{title:"21. Тёзки в Контуре",text:"Двух Ахмедовых Ахмедов Контур различить не умеет. Робот пакетного снятия с учёта тёзок не трогает — они возвращаются с пометкой «снимите вручную», иначе с учёта мог бы сняться не тот, в том числе живущий. Сверка ЭЦП показывает «тёзки: в CRM 2, в Контуре 1» — значит, один из двоих на учёт не поставлен."},{title:"22. «Вошли и не вышли» — два разных случая",text:"На «Главной» и над журналом СКУД: последний проход — вход, и он старше 36 часов. По клику список делится на две группы. «Выход потерян» (до недели): человек ушёл за кем-то следом или охрана открыла рукой — спросите смену, гляньте комнату на обходе; следующий проход через турникет закроет вопрос сам. «Давно нет проходов» (неделя и дольше): скорее всего, уехал, а карточку не закрыли. Пока она открыта, он числится на миграционном учёте по адресу, где не живёт, занимает койку в счёте фирме, и сроки уничтожения его документов не идут — откройте карточку и нажмите «Выселить» (или «На границе», если он на въезде-выезде — с этой галочкой человек считается «на улице»). Сотрудник уехал в отпуск, жилец точно вернётся, а турникет выход не записал — «Отметить выход» в строке списка или в карточке рядом с «Сейчас в хостеле»: укажите причину, в журнал проходов запишется выход текущим временем с вашим именем и пометкой «отметка», в журнал действий — кто и почему. Когда человек ушёл на самом деле, CRM не знает, поэтому задним числом не пишем; в расчёт проживания отметка не идёт. Следующий вход через турникет закроет всё как обычно. Проходы считаются по всей сети: прошёл турникет другого объекта — здесь его уже не считаем. Сотрудники без комнаты (пропуск) в полосу не входят."},{title:"23. Сверка с Контуром: проверить одного человека",text:"Если «Дозаполнить всех», сверка граждан РФ или перенос на другое юр. лицо ведут себя странно, проверьте одного человека — это быстрее, чем гонять всех. «Проверить на одном жильце» (вкладка «Заполнить из Контура») показывает по каждому полю, что лежит в Контуре, что сейчас в CRM и что будет: в пустое поле значение подтянется, заполненное другим значением не трогается. Сама проверка ничего не сохраняет. «Проверить одного» (вкладка «Граждане РФ») — до какого числа человек на учёте и по каким уведомлениям. «Проверить поиск дела» (вкладка «Перенос») — по шагам: вошёл ли робот в кабинет, какие списки видит, нашёл ли дело. Ответ кажется неправильным — нажмите «Скопировать отчёт для поддержки» и пришлите текст нам: там технические подробности без ФИО и номеров документов. Каждая проверка пишется в журнал действий."},{title:"23а. Перенос жильцов на другое юр. лицо (в другой кабинет Контура)",text:"Когда часть объекта переходит к другому юр. лицу, делите по комнатам. 1) Директор отдаёт комнаты новому юр. лицу: «Настройки» → «Комнаты и юр. лица» (объект выбран в шапке), галочками и разом. Новые заселения в эти комнаты сразу идут на новое юр. лицо — и в Контур, и в согласия. 2) «Миграционный контроль» → «Сверка с Контуром» → «Перенос на другое юрлицо»: в очереди — кто живёт в этих комнатах, а числится за прежним. Отметьте людей и нажмите «Собрать партию» — список закрепится. 3) Сверху партии — проверка: красный пункт (нет кабинета Контура нового юр. лица) не даст начать, оранжевые — предупреждения. Порядок: СНАЧАЛА снять у прежнего, ПОТОМ поставить у нового, в один день — между этим человек без учёта. 4) Снимите людей в кабинете прежнего юр. лица, отметьте их в списке — «Сняты». Неполную карточку снять не даст: у нового её не поставить. 5) «Скачать файл для Контура» — загрузите его в кабинет нового юр. лица; «Приложить сканы роботом» — робот прицепит сканы к делам. 6) Отправьте уведомления в кабинете и отметьте — «Поставлены»: юр. лицо в карточке сменится. 7) «Проверить кабинеты роботом» подскажет, кого уже нет у прежнего и кто уже есть у нового; тёзок и граждан РФ он не проверяет. Снят и не поставлен дольше суток — строка красная и попадает в утреннее письмо директору. Отметили по ошибке — «Отменить отметку». Когда все поставлены — «Закрыть партию». Подписанные раньше согласия остаются на прежнее юр. лицо: CRM их не переписывает."},{title:"23б. Вкладка «Продление» — кому продлевать проживание",text:"На «Миграционном контроле» есть вкладка «Продление»: в ней те, у кого срок регистрации кончается в выбранные дни («Сегодня», «Завтра», «7 дней», «90 дней» — все, кого можно продлить, — или свои даты, до 90 дней). Для каждого CRM показывает кабинет Контура, текущий срок и новую дату окончания: это ровно 90 дней включительно (28.10 → 25.01), но не позже самого раннего срока документов (если дату ограничил документ, под ней написано «патент до дд.мм.гггг» — срок самого документа; патент в продлении считается за день до срока в карточке; в Excel для всех строк есть колонка «Право пребывания до»): патента, разрешения на работу, вида на жительство или штампа МВД (миграционная карта права пребывания сама не даёт), а также визы и паспорта. Если права пребывания по документам нет, человек уходит в «ручной разбор». Если новый период получился короче 7 дней (например, патент кончается через 5 дней), строка оранжевая: «решить вручную: патент … — продление вышло бы на N дн. Новый патент или выезд» — в пачку для робота такой человек не попадает. Если документ вышел или не позволяет продлить дальше нынешней регистрации, человек в списке с причиной словами (оранжевым) — его надо разбирать руками. Если у кабинета не задано «Ответственное лицо для продления» (директор вносит его в «Настройки → объект → Контур.ФМС»), продление для кабинета не запускается. Вкладка только считает: в Контуре она ничего не делает. Основной путь продления — файл: отметьте галочками тех, кого продлеваем (или «Выбрать всех «продлеваем»»), нажмите «Файл для Контура» — CRM покажет, сколько людей в каком кабинете и кого она отложила (с причиной: не продлеваем, карточка не готова), потом «Скачать файл». В архиве по папке на каждый кабинет: загрузите общий файл `vse_odnim_faylom.csv` в Контуре («Загрузка гостей из файла») в тот же кабинет. Затем «Приложить сканы роботом» — робот сам приложит сканы к новым (неотправленным) делам; в отправленные дела он не заходит, тех, у кого два неотправленных дела или тёзка, пропускает — им сканы прикладывают руками из папки `skany`. Потом снимите старые дела (дата убытия — сегодня), подпишите и отправьте — подпись и «Отправить» всегда ваши. Когда дела отправлены, нажмите «Продлено в Контуре»: в карточках станет новая дата окончания регистрации. Тех, кого файл не осилил, продлевайте руками: «⋯ → Продлить проживание гостя» в кабинете. Список можно скачать в Excel. Если объект подаёт иностранцев через Госуслуги, в колонке «Кабинет» у таких людей написано «Госуслуги», и продлевают их не файлом, а кнопкой «Продлить через Госуслуги»: отметьте людей (дату окончания можно поставить раньше посчитанной прямо в колонке «Новое окончание», позже — нельзя), нажмите кнопку — откроется окно «Отправить в МВД»: снятие прежней постановки и новая постановка (с сегодня по новой дате) уходят по порядку, снятие первым, одной подписью. Новая дата появится в карточке, когда МВД примет. Пока подача идёт, в строке написано «Госуслуги — постановка: …», галочки нет. Кого ставили через Контур, у того под «продлеваем» подсказка «прежнюю снимите в Контуре»: снимите его в Контуре, через Госуслуги уйдёт только новая постановка. Если прежнюю сняли, а новая не прошла, на «Госуслугах» красная строка «человек без учёта» — исправьте карточку и подайте постановку сразу."},{title:"24. Подача в МВД через Госуслуги",text:"Объект можно перевести на прямую подачу через Госуслуги — отдельно для граждан РФ и для иностранцев: «Настройки» → объект → «Миграционный учёт» → «Подача через Госуслуги» (переключает директор). Пока портал не подключён (идёт подключение), переключатель неактивен — подаём как раньше. Директор заранее вносит ключи сотрудников: сотрудник CRM, ФИО как на Госуслугах, API-Key из кабинета partners.gosuslugi.ru и дата его выпуска (ключ живёт около полугода; за 30 дней до конца CRM предупреждает на экране и в утреннем письме). Ключ после сохранения целиком не показывается — только 4 последних знака. Для уведомлений на иностранцев МВД требует ещё данные самого сотрудника (дата рождения, паспорт, адрес регистрации кадастровым номером или кодом ФИАС, телефон, почта): кнопка «Данные для МВД» в строке ключа, вносит директор один раз и только с письменного согласия сотрудника (форма — от юриста). Данные хранятся зашифрованными и на экран не возвращаются. CRM запоминает, кто и когда отметил согласие; в журнал действий пишется только, какие поля изменены, без самих значений. К уведомлению на иностранца CRM прикладывает последний скан паспорта из карточки (jpg, png, tiff или pdf): без скана — «не подаётся», загрузите его в карточке → «Документы». Скан уходит только в заявление, приложение пишется в журнал. Ключ сотрудника годится только для жильцов своего объекта и своего юр. лица. Как работает: нажали «Заселить» или «Выселить» — уведомление встаёт в очередь от имени того, кто нажал. Каждое заявление МВД подписывается вашей электронной подписью (так требуют Госуслуги), и делается это сразу: в окне «Заселён» — кнопка «Отправить в МВД (Госуслуги)», после выселения окно отправки открывается само. В окне видно, что уйдёт («1 уведомление о прибытии») и каким сертификатом; CRM запоминает ваш сертификат на этом компьютере. «Отправить» — вход на Госуслуги (если нужен), подпись и отправка одним нажатием, подписываются все ваши ждущие заявления разом. Не успели — то же окно на «Миграционный контроль» → «Госуслуги» → «Подписать и отправить (N)». Нужен КриптоПро ЭЦП Browser plug-in, тот же, что для Контура; закрытый ключ подписи остаётся на вашем компьютере. Ответ МВД виден там же и в карточке жильца: «принято» или «отказ» с причиной. После «принято» в карточке жильца («Документы» → «Госуслуги: прибытие») появляется кнопка «Распечатать отрывную часть» (иностранцу) или «Распечатать анкету» (гражданину РФ) — Госуслуги своего листка жильцу не выдают, отдайте ему этот. Печатать на обе стороны листа; на обороте отрывной части — печать хостела. Красное («отказ», «не подаётся») — исправьте карточку и нажмите «Подать снова»: неполную карточку CRM не подаёт. Госуслуги принимают от одного сотрудника не больше 20 заявлений за 10 минут: заселили сразу много людей — первые 20 уходят сразу, остальные ждут и уходят сами (синяя строка «ждут очереди портала — последнее в 14:20»). Это не отказ, делать ничего не нужно."},{title:"25. Заявки фирм на выселение и заселение",text:"Фирмы подают заявки из своего кабинета, а не в мессенджер. Новые видны сразу: число у пункта «Заявки фирм» в меню, строка в колокольчике и на «Главной». Заявка на выселение — у человека в «Жильцах» и в его карточке пометка «Фирма просит выселить с …». Заявка никого не выселяет и пропуск не закрывает: выселяете вы обычной кнопкой «Выселить» в карточке (имя в заявке её открывает). Заявка на заселение — объект, дата, сколько человек и, если фирма написала, ФИО. Ответьте фирме: «Принято» или «Отклонить» / «Мест нет» с комментарием — она увидит ответ в кабинете; ответ можно поменять, пока фирма заявку не отменила. Выселили человека, не ответив, — заявка из «Ждут ответа» уходит сама. Почта на объект не приходит — смотрите экран. Видят и отвечают управленцы своего объекта; подача, ответ и отмена пишутся в журнал действий."},{title:"25а. «Фирмы» → «Заявки от фирм»: кто хочет у нас селиться",text:"Не путайте с разделом «Заявки фирм»: там просьбы фирм, которые уже у вас живут (выселить, заселить — шаг 25). Здесь — ваш список тех, кто только собирается заключить договор: заявки с Авито, от агрегаторов, звонки, рекомендации. Заявки лежат колонками-стадиями: «Новые», «В работе», «Заселили», «Отказ». Сверху — «Всего заявок», «Новые», «В работе» и «Заселили за месяц». «Новая заявка» — название фирмы (обязательно), откуда пришла, контакт, телефон, почта, сколько мест нужно, объект, желаемая дата заезда, заметка. Сдвинули дело вперёд — «Изменить» заявку и поменяйте стадию; ненужную — «Удалить» (спросит подтверждение). Это ваша записная книжка продаж: ни места, ни счета она сама не создаёт."},{title:"25б. «Продажи мест»",text:"Раздел показывает, сколько мест продано фирмам и сколько занято на деле. Четыре цифры сверху: «Продано / всего мест» (по режиму фирмы: «за комнату» — вместимость закреплённых комнат, «за место» — фактически занятые), «Занято по факту», «Выручка, ₽/мес» (и в сутки) и «Фирм на биллинге». Если выбрана вся сеть — полоса по каждому объекту (красная, когда продано 90 % мест и больше), ниже таблица фирм; сортировка — нажатием на заголовок колонки. «Продано» — не «пришло денег», а места, за которые фирма должна платить; сами деньги — в «Счета фирмам». Режим оплаты и цену задаёте в карточке фирмы. История по дням записывается автоматически в 00:05; кнопка «Снимок сейчас» нужна только если ночью снимок не записался: она дописывает снимок за прошедшие сутки и уже записанное не меняет."},{title:"26. Автовыход при простое и «был в сети»",text:"Без действий 12 часов (охрана, прачечная, обходчик — 24 часа) CRM сама просит пароль снова — даже если вкладка открыта: опросы экрана работой не считаются, только мышь, клавиатура, касание. Человек видит «Вы вышли из-за долгого бездействия (12 ч)». Директор задаёт предел по каждой роли: «Настройки» → «Сеть» → «Вход и сеансы» (от 1 до 168 часов, выключить нельзя; изменение пишется в журнал действий). Каждый может поставить себе срок короче в «Мой профиль», но не дольше предела роли. В «Сотрудниках» колонка «Был в сети» — когда человек последний раз работал в CRM (точность ±15 минут), а последний ввод пароля — в подсказке и в карточке человека. С чужого компьютера входите с галочкой «Чужой компьютер»: вход пропадёт с закрытием браузера."},{title:"27. Общий компьютер объекта и «Выйти на всех устройствах»",text:"За общим компьютером объекта (стойка администратора, пост) каждый работает под СВОЕЙ учёткой: всё, что сделано в CRM, пишется в журнал действий на того, под чьим именем вход. Работать под чужой учёткой нельзя, даже если она осталась открытой, — нажмите кнопку выхода (дверь со стрелкой внизу меню слева) и войдите своим логином. На общем компьютере входите с галочкой «Чужой компьютер»: вход пропадёт, как только закроете браузер. Уходя со смены — та же кнопка выхода. Забыли выйти где-то (общий ПК, чужой телефон) — нажмите на своё имя внизу меню слева → «Мой профиль» → «Выйти на всех устройствах»: CRM сразу попросит пароль везде, кроме того места, где вы нажали; пароль остаётся прежним. Если пароль мог узнать кто-то другой — смените пароль там же, это тоже закрывает все входы. Директор может закрыть все входы сотрудника без смены пароля: «Сотрудники» → человек → «Закрыть все входы». Оба действия пишутся в журнал действий."},{title:"28. Календарь: заметки и напоминания",text:"Раздел «Календарь» в меню: кнопка «Заметка», текст, дата, время или «Весь день». В поле «Кому» — себе, сотруднику или всем на объекте. В срок придёт напоминание: колокольчик и карточка в углу экрана. Если вас в этот момент нет в CRM, через 3 минуты придёт письмо: только дата и время, без текста заметки. Куда придёт письмо — внизу экрана, там же адрес можно поменять. Личную заметку видите только вы и адресат. Директор ставит задачу администратору, смена передаёт дела следующей смене. «Сделано» нажимает любой, кто видит заметку. Изменить и удалить может автор, заметку на объект — ещё и администрация; адресата у чужой заметки поменять нельзя. Директору и бухгалтеру напоминания «всем на объекте» не приходят, эти заметки они видят, выбрав объект. В журнал действий пишутся дата, время и кому, но не текст."}]},{role:"director",label:"Директор",matches:["director","developer"],ready:!0,intro:"Директор видит всю сеть: объекты, деньги, настройки. Повседневная работа с жильцами описана в гайде «Администратор» — здесь то, что решает и проверяет именно директор.",steps:[{title:"1. Первый день директора",text:"Сверху переключатель объекта: вся сеть или один хостел. По порядку: 1) «Главная» — что требует внимания и как заполнены хостелы. 2) «Настройки» → «Сеть» → «Объекты» и «Юр. лица»: хостелы сети и организации, от имени которых подаются уведомления. 3) «Настройки» → «Сеть» → «Персональные данные»: политика и реквизиты вашей организации как оператора (отдельный шаг ниже) — заполните до начала работы. 4) «Сотрудники», «Кто что видит» и «Шаблоны доступа» — у кого какой вход и что ему открыто. 5) «Подписка» — до какого числа оплачено. Найти человека, комнату или раздел можно с любого экрана: Ctrl+K (на Mac ⌘K) или лупа в шапке. Незнакомое слово (ЭЦП, СКУД, Контур) — «Инструкции по разделам» → «Словарь»."},{hideInDemo:!0,title:"2. Что в вашем меню",text:"Главная, Жильцы, Миграционный контроль, Заблокированные, Уехавшие, СКУД, Пропускной пункт, Фирмы, Продажи мест, Счета фирмам, Заявки фирм, Календарь, Настройки, Сотрудники, Журнал действий. «Постельные принадлежности» и «Журнал обхода» — рабочие разделы администратора, из вашего меню они убраны; нужны — найдите через поиск Ctrl+K. Раздела «Аналитика» больше нет: цифры — на «Главной» и в «Продажах мест»."},{title:"3. Раз в неделю: что посмотреть",text:"«Главная» по каждому объекту: «Требует внимания» должно быть пустым или объяснимым. «Миграционный контроль» → «Просрочка» — каждый человек тут риск штрафа хостелу. «Заблокированные» → «Нарушения» → «Открытые» — неоплаченные штрафы. «Фирмы» → «Сверка» — сходится ли число мест у фирм (шаг 12д гайда «Администратор»). «Счета фирмам» → «Долги». «Журнал действий» — кто что менял, если что-то непонятно. «Продажи мест» — занятость и выручка."},{title:"4. «Продажи мест»",text:"Раздел показывает, сколько мест продано фирмам и сколько занято на деле. Четыре цифры сверху: «Продано / всего мест» (по режиму фирмы: «за комнату» — вместимость закреплённых комнат, «за место» — фактически занятые), «Занято по факту», «Выручка, ₽/мес» (и в сутки), «Фирм на биллинге». Вся сеть — полоса по каждому объекту (красная от 90 % проданных) и таблица фирм, сортировка по заголовкам. «Продано» — не «пришло денег», а места, за которые фирма должна платить. Режим оплаты и цена — в карточке фирмы. История по дням пишется сама в 00:05; «Снимок сейчас» дописывает снимок за прошедшие сутки, только если ночью он не записался, и уже записанное не меняет."},{title:"5. «Настройки» → «Сеть»",text:"«Объекты» и «Юр. лица» — хостелы и организации. «Кто что видит» — таблица: какой роли что открыто; у директора ещё «По сотрудникам». «Шаблоны доступа» — спрятать человеку лишнее из положенного его роли (шаблон только сужает права). «Оформление» — акцентный цвет, название сети, ссылки на сайт и Телеграм, ссылка на публичную форму заявки; «Применить оформление» меняет вид CRM у всех сотрудников. «Персональные данные», «Подписка» и «Резервные копии» — отдельные шаги ниже. «Сводка и сроки хранения» — куда приходит утреннее письмо директору и через сколько дней стираются фото и сканы уехавших. «Вход и сеансы» — через сколько часов без действий CRM просит пароль, по ролям."},{title:"6. «Персональные данные»: политика и реквизиты оператора",text:"Закон требует, чтобы политика обработки персональных данных была опубликована для любого посетителя; она лежит по адресу /privacy вашей CRM, на неё ссылаются все формы заявок. «Настройки» → «Сеть» → «Персональные данные»: внизу текст политики, вверху — реквизиты оператора: наименование организации, адрес, почта и телефон для обращений и ответственный за обработку данных. Пока вы не сохранили свой текст, опубликована заготовка blaqit — экран прямо об этом пишет; заготовку покажите юристу, утверждает текст ваш юрист, не мы. Незаполненные места вида {{OPERATOR_INN}} видны посетителям: заполните реквизиты и сохраните. «Сохранить и опубликовать» заводит новую редакцию политики — заявки запоминают, с какой именно редакцией согласился человек. «Посмотреть, как видит посетитель» открывает публичную страницу."},{hideInDemo:!0,title:"7. «Подписка» и «Подписка объекта»",text:"«Настройки» → «Сеть» → «Подписка» — сводка по всем объектам: «Объектов», «Подключено», «Бесплатно», «Скоро продление», «Просрочено», «Приостановлено», «Плата в месяц» и таблица «Подписки по объектам». Один объект — «Настройки» → «Объект» → «Подписка объекта»: тариф, стоимость, вместимость, «Оплачено по» и история оплат. Состояния: «Активна»; «Скоро продление» — период кончается, пора платить; «Просрочена» — срок оплаты прошёл, работа не останавливается; «Приостановлена» — сотрудники не могут сохранять изменения, при этом турникеты работают и данные на месте; «Не подключён». Подключение, оплату и приостановку выполняет поставщик blaqit.CRM, у вас на экране состояние и история. У сотрудников при просрочке или приостановке сверху появляется цветная плашка с объяснением — так «CRM не сохраняет» не выглядит поломкой."},{hideInDemo:!0,title:"8. «Резервные копии»",text:"«Настройки» → «Сеть» → «Резервные копии». Копии базы делаются каждую ночь сами; «Создать копию сейчас» — когда нужна свежая перед важной работой. Самостоятельно восстановить базу отсюда не надо: восстановление идёт через поддержку blaqit, потому что оно возвращает карточки жильцов к моменту копии и отменяет всё, что администраторы сделали после. Памятка на самом экране объясняет, что восстановление меняет только карточки жильцов (комнаты, фирмы, настройки и фотографии не трогает), а проходы, нарушения и выдачи белья не возвращает. Если данные пропали или испорчены — пишите нам, не пытайтесь чинить сами."},{title:"9. «Настройки» → «Объект»",text:"Выберите объект в шапке. «Профиль» — адрес, телефон, почта объекта; «Комнаты и юр. лица»; «Миграционный учёт» — режим объекта (Контур, бумага, Госуслуги), от него зависят вкладки «Миграционного контроля»; «Контур.ФМС» — логины кабинетов; «Документы на подпись» — тексты согласия на данные, согласия на проход по пропуску, правил проживания и пожарного инструктажа: замените заготовку своим текстом, документ можно выключить — уже подписанные листы не меняются; «Турникеты» и «Проживание» — те же экраны, что в «СКУД»; «Бельё и прачечная» — этикетка белья и цена стирки; «Блокировки» — правила автоблокировок; «Уведомления» — таблица «кому приходит тревога у турникета» (незнакомый, выселенный, заблокированный у турникета, открыл турникет 3 раза и больше): отметьте, каким ролям — охране, администратору, директору — приходят сигналы; «Места фирм» — переключатель «плавающие места» (статья «Режим плавающие места»). На профиле сверху — полоска «Готовность объекта»: CRM сама проверяет, что профиль, комнаты, юр. лицо, турникеты и миграционный учёт настроены."},{title:"10. Журнал действий",text:"Меню «Журнал действий» у директора и администратора: кто, когда, что создал, изменил, удалил, кто открывал паспорта и сканы и что выгружал. Записи не удаляются и не правятся никем. По одному человеку — карточка жильца → «История» → «Кто что менял». Подробности — в «Частых вопросах»."},{title:"11. Календарь: заметки и напоминания",text:"Раздел «Календарь»: кнопка «Заметка», текст, дата, время или «Весь день». В поле «Кому» — себе, сотруднику или всем на объекте. В срок придёт напоминание: колокольчик и карточка в углу экрана; если вас нет в CRM, через 3 минуты придёт письмо — только дата и время, без текста. Личную заметку видите вы и адресат. «Сделано» нажимает тот, кто сделал; изменить и удалить может автор."}]},{role:"laundry",label:"Прачечная",matches:["laundry","прачечная"],ready:!0,intro:"У прачечной один экран — сканер выдачи. Склад, заявки и стирка — экраны администратора.",steps:[{title:"1. Выдача белья",text:"Экран открывается сразу на нужном месте: большое поле для штрихкода. Считайте штрихкод сканером или нажмите «Скан через камеру» (подойдёт и телефон) — бельё выдастся автоматически, на экране появится ФИО, прозвучит сигнал (на Android телефон ещё и вибрирует). Комплект списывается со склада сам. Под сканером — «Последние выдачи на этом телефоне»: время, ФИО и комната последних выдач. Покажите эту строку жильцу или администратору, если спорят, выдано ли. Список живёт, пока открыта вкладка: закрыли — пропал (ФИО на телефоне не хранятся)."},{title:"1а. Что значит цвет круга",text:"ЗЕЛЁНЫЙ с высоким «дзинь» — выдано, комплект отдавайте. Зелёная строка «Уже выдано только что (19:23), второй раз не записано» — тот же номер прочитался ещё раз (камера снова увидела наклейку, сканер нажали дважды): бельё уже выдано этим сканом, всё в порядке, ничего делать не нужно. ОРАНЖЕВЫЙ с двумя ровными «ту-ту» — «Бельё меняли недавно»: проверьте строку — там написано, когда и кто выдал прошлый раз (см. пункт 3). КРАСНЫЙ с низким долгим «бз-з» — ошибка: номер не найден, человек выселен или пропала связь. Цвет держится 8 секунд или до следующего скана. Камера тот же номер минуту не отправляет — пишет «уже выдано — уберите наклейку из кадра»."},{title:"2. Если штрихкода нет под рукой",text:"Впишите номер вручную в то же поле — работает так же. Номер — это карточка жильца: один номер = один человек, у вернувшегося после выселения номер переезжает на новую карточку."},{title:"3. «Бельё меняли недавно»",text:"Оранжевым, не красным: это не ошибка сканера. Между сменами действует минимальный срок (по умолчанию неделя, настраивает администратор). В строке написано, когда (дата и время) и кто выдал прошлый комплект и с какого дня можно менять. Если там время несколько минут назад — человек только что получил бельё, ничего делать не нужно. Иначе объясните жильцу; если менять надо сейчас (порвал, залил, болезнь) — досрочную выдачу проводит администратор или директор, с причиной. После нового заселения срок не действует. Каждый такой отказ виден администратору в карточке жильца."},{title:"4. «Штрихкод не найден»",text:"Красным, с прочитанным номером: «Прочитано: 20…». Сверьте его с цифрами под штрихкодом на наклейке. Цифры другие — камера прочитала наклейку неверно (бледная, мятая, блик): наведите ещё раз ровно или впишите цифры вручную и нажмите Enter. Цифры те же — наклейка старая или чужая: новую печатает администратор в карточке жильца. Человек выселен — тоже красным, к администратору. Красное «нет связи» после скана: выдача могла успеть записаться — отсканируйте ещё раз, CRM покажет «уже выдано» и второй раз не запишет."},{title:"5. Сканер вообще не реагирует на наклейку",text:"Это другая история, чем «Штрихкод не найден»: сканер молчит или пищит по-другому, поле для номера остаётся пустым. Причина — брак печати: штрих-код на наклейке напечатан не тем форматом и его не может прочитать ни один сканер, настроенный на обычные магазинные коды. Впишите номер вручную (см. пункт 2) один раз, а администратору скажите перепечатать этому жильцу наклейку заново — новая наклейка будет читаться сканером."},{title:"6. Чего на этом экране нет",text:"Закупка белья, списание, кто давно без белья, расчёты с прачечной (сколько кг отдали и сколько приехало, привоз по отгрузке, которой нет в CRM) — всё это на экране «Постельные принадлежности» у администратора объекта. Заявки на матрасы, подушки и комплекты прачечная не видит и не разбирает: их ведут обходчик и администратор (CRM откажет, даже если открыть адрес вручную). Если по работе нужны эти вкладки — вопрос к директору, роль назначается в «Сотрудниках»."},{title:"7. CRM попросила пароль снова",text:"Если ничего не делать в CRM сутки (24 часа), она сама закроет вход — на случай, если устройство осталось без присмотра. На экране входа будет «Вы вышли из-за долгого бездействия» — это не поломка, войдите заново. Срок можно сделать короче в «Мой профиль»."},{title:"8. Календарь: заметки и напоминания",text:"Раздел «Календарь» в меню: кнопка «Заметка», текст, дата, время или «Весь день». В поле «Кому» — себе, сотруднику или всем на объекте. В срок придёт напоминание: колокольчик и карточка в углу экрана. Если вас в этот момент нет в CRM, через 3 минуты придёт письмо: только дата и время, без текста заметки. Куда придёт письмо — внизу экрана, там же адрес можно поменять. Личную заметку видите только вы и адресат. «Сделано» может нажать любой, кто видит заметку; изменить и удалить — автор."}]},{role:"firm",label:"Фирма-заказчик",matches:["firm"],ready:!0,intro:"Личный кабинет: кто из ваших людей где живёт, сколько у вас свободных мест, и заявки на выселение и заселение. Менять карточки людей и загружать файлы здесь нельзя. Документы, сроки регистрации, счета и чужие фирмы сюда не показываются.",steps:[{title:"1. Первый вход",text:"Логин и временный пароль вам присылает хостел (на почту или лично). При первом входе система попросит придумать свой пароль — это разовый шаг, временный пароль после него перестаёт работать. Проще всего нажать «Предложить надёжный пароль» и сохранить его в менеджере паролей. Свой пароль никому не передавайте: каждая выгрузка списка записывается в журнал на ваш логин."},{title:"2. Что видно на главном экране",text:"Три цифры: сколько ваших людей проживает, сколько заблокировано и сколько мест у вас свободно. Если квота за вашей фирмой ещё не закреплена, вместо числа так и написано — «не задана»: это к администратору объекта. Слева вверху — переключатель: «Все объекты» показывает всех ваших людей сразу, выбранный объект — только его."},{title:"3. Список людей",text:"Люди разложены так же, как у администратора: объект → этаж → комната, у каждого человека — ФИО и статус «Проживает» или «Заблокирован» (турникет закрыт — спросите администратора объекта, он скажет причину). В шапке комнаты — номер, этаж и сколько там ваших людей («Комната 312 · 3 этаж · ваших 9»). Соседей из других фирм вы не видите ни по именам, ни числом — как и они ваших. Объект, этаж и комнату можно свернуть нажатием на шапку; «Свернуть все» оставляет короткий список комнат, «Развернуть все» — показывает всех. Люди приходят по сотне: если в комнате написано «Ещё 4», нажмите «Показать ещё» внизу списка. «Этаж не указан» — у комнаты в CRM не заполнен этаж; «Без комнаты» — человек числится за вами, но комната ему не назначена (вопрос к администратору). По умолчанию показаны живущие и заблокированные; выехавшие — под фильтром «Выехали». Паспортных данных, гражданства, сроков регистрации и причин блокировки в кабинете нет намеренно: за них отвечает хостел."},{title:"4. Найти человека и скачать список",text:"Поиск работает и по фамилии, и по номеру комнаты («кто у нас в 312-й»). Рядом фильтр по статусу. Кнопка «Excel» сохраняет весь список под выбранным отбором в файл — четыре колонки: ФИО, объект, комната, статус — его можно переслать себе или в бухгалтерию; в имени файла видно объект и фильтр («Наши-люди_Все-объекты_2026-10-11.xlsx»); «Печать» выводит на бумагу весь список с той же раскладкой по комнатам. Выгрузка отмечается в журнале действий CRM — это персональные данные ваших людей."},{title:"5. Сколько у нас свободных мест",text:"Вкладка «Места»: по каждому объекту ваша квота, занято и свободно. Занятыми считаются и заблокированные — место за ними сохраняется. Нужно больше мест, чем в квоте, — это к администратору объекта."},{title:"6. Если нужно заселить или выселить человека",text:"Заявку подаёте здесь, в кабинете, — не в мессенджере: так её видят все администраторы объекта и она не потеряется. Выселить: во вкладке «Наши люди» отметьте галочками своих живущих людей (одного или нескольких) — внизу появится «Попросить выселить»; укажите, с какого дня, и при желании комментарий. Заселить: вкладка «Заявки» → «Заявка на заселение»: объект, дата, сколько человек, ФИО — по желанию, списком, и комментарий. Документы в заявку не прикладываются — человек приносит их на заселение сам. Заявка — просьба: выселяет и заселяет администратор объекта сам. Его ответ виден во вкладке «Заявки»: «принято», «отклонено» или «мест нет» с комментарием; у человека, на которого подана заявка, в списке написано «Просите выселить с …». Передумали — «Отменить» у заявки, пока она открыта. Повторно на того же человека заявку не подать, пока первая открыта. Не больше 30 заявок в час с одного логина. ФИО из заявки на заселение хранятся 90 дней после её даты, потом стираются."},{title:"7. Счета и оплата",text:"Счета и акты фирма получает от хостела (PDF на почту или на руки), в кабинете они не показываются. Вопросы по сумме и оплате — администратору или бухгалтеру хостела. Если на объекте включено правило «за неоплату», при просроченном счёте в кабинете появится предупреждение: номер счёта, остаток и дата, с которой проход ваших людей будет приостановлен; после оплаты проход откроется автоматически. Если оплата уже проведена — пришлите платёжное поручение администратору."},{title:"8. Кабинет попросил пароль снова",text:"Если ничего не делать в кабинете 12 часов, он сам закроет вход — на случай, если компьютер или телефон остался без присмотра. На экране входа будет «Вы вышли из-за долгого бездействия» — это не поломка, войдите тем же логином и паролем. С чужого компьютера входите с галочкой «Чужой компьютер»: вход пропадёт, как только закроете браузер."}]},{role:"accountant",label:"Бухгалтер",matches:["accountant"],ready:!0,intro:"Сетевая роль без права заселять и блокировать: счета фирмам, платежи, долги, отчёты и миграционный контроль по всей сети сразу.",steps:[{title:"1. Главный экран: блок «Финансы»",text:"Первое на «Главной» — четыре цифры: ждут оплаты, просрочено, выставлено и оплачено за месяц. Ниже — что требует действия: фирмы без счёта на следующий месяц (появляются в последние 5 дней месяца), фирмы, у которых скоро закроется проход за неоплату, и те, у кого он уже закрыт. Каждая цифра — ссылка в «Счета фирмам». Объект выбирается в шапке слева; «Вся сеть» — по всем объектам."},{title:"2. Выставить счёт",text:"Кнопка «Выставить счёт» на экране «Счета фирмам» (выберите объект в шапке — счёт всегда по объекту) или значок счёта в карточке фирмы в «Фирмах». Форма уже заполнена: период (следующий месяц), мест и цена из прошлого счёта, юр. лицо, НДС, договор. Проверьте, поправьте, нажмите. Срок оплаты по умолчанию — первый день периода: он печатается в счёте, от него считается просрочка. Галочка «сразу отправить фирме на почту» — по желанию. НДС: режим и ставка подставляются из юр. лица; ставка по умолчанию — 22 % (с 01.01.2026). У юр. лица, заведённого раньше, могла остаться 20 % — её меняет директор: «Настройки» → «Сеть» → «Юр. лица» → «Редактировать» → «Ставка НДС». Уже выставленные счета при этом не меняются."},{title:"2б. Цена и договор — у каждого объекта свои",text:"Одна фирма может селить людей на несколько объектов сети, и с каждым объектом у неё своя цена и свой договор. Поэтому цена за место, способ расчёта, номер и дата договора и почта для счетов хранятся по объекту: счёт, сверка, «Продажи мест» и письма берут условия того объекта, по которому выставляется счёт. Посмотреть условия всех объектов сразу — «Фирмы» в режиме «Вся сеть»: у каждой фирмы строка на объект. Почта для счетов объекта пустая — счёт уйдёт на общую почту фирмы. Если две карточки одной фирмы когда-то завели по отдельности, их объединяет директор кнопкой «Скорая помощь»; счета старой карточки остаются на ней (это документы), второй счёт за уже оплаченный ею период CRM не даст выставить, а её долг виден в «Долгах» под прежним названием."},{title:"2а. Одна бригада — несколько плательщиков",text:"Бывает, что фирма держит на объекте одну бригаду, а платит за неё несколькими юр. лицами — у каждого свой договор и отдельный счёт на свою долю мест (например, 100, 67 и 3 места). Заводить три фирмы не нужно: люди общие, делится только оплата. В «Фирмах» у карточки фирмы значок «Плательщики» (банк) или кнопка «Плательщики…» в форме счёта: название, ИНН (обязателен — без него счёт юр. лицу не выставить), КПП (у ИП нет), адрес, договор, сколько мест оплачивает, почта для счетов (пусто — почта фирмы). Если сумма мест плательщиков не совпадает с местами фирмы, CRM скажет об этом оранжевой строкой, но выставить не помешает. Когда плательщики есть, в форме счёта появляется поле «Плательщик»: выберите одного — места и договор подставятся его, или «Всем плательщикам» — CRM выставит счёт за проживание каждому, кому за этот период ещё не выставлено, номера пойдут подряд. Штрафы, перерасчёт и доплату выставьте одному плательщику — выберите его в списке. За период — один счёт на плательщика; в счёте и акте заказчиком стоит плательщик. В «Сверке» оплаченными считаются места по счетам всех плательщиков вместе. Плательщика со счетами удалить нельзя."},{title:"3. Штрафы жильцов в счёте",text:"Штрафы за прошлый месяц в форме не отмечены. Отметите — штраф попадёт в счёт отдельной строкой с причиной и закроется у жильца как «выставлен фирме»: наличными его больше не принять. Не отметите — штраф остаётся открытым и ждёт наличных на стойке. Один штраф платит один плательщик. Аннулировали счёт — штраф снова откроется."},{title:"4. Внести оплату",text:"Значок кошелька в строке счёта: дата С ПЛАТЁЖКИ (не сегодняшняя — так история бьётся с выпиской), сумма (по умолчанию остаток), номер платёжки. Платежей на счёт может быть несколько: пока не пришла вся сумма, счёт «частично оплачен» с остатком. Переплата допускается — уйдёт корректировкой в следующий счёт, деньгами не возвращается. Раскройте строку стрелкой — увидите позиции и платежи. Ошибочный платёж удаляет директор, с причиной."},{title:"5. Долги",text:"Вкладка «Долги»: кто, сколько и сколько дней должен, по объектам и юр. лицам. У фирмы, которая платит несколькими юр. лицами, — строка на каждого плательщика: видно, кто именно не заплатил; акт сверки из такой строки — только по счетам этого плательщика. Долг плательщика проход людям не закрывает — в колонке «Автоблок» так и написано; решение — у директора. «Просрочен N дн.» — срок оплаты прошёл. В колонке «Автоблок» видно, включено ли на объекте правило «за неоплату фирмы», когда закроется проход жильцам должника и сколько уже заблокировано; правило включает директор в настройках объекта. Отсюда же — платёж по конкретному счёту и акт сверки взаиморасчётов с фирмой за период."},{title:"6. Отчёты",text:"Вкладка «Отчёты»: выручка по месяцам × юр. лицо × объект (выставлено — по дате счёта, оплачено — по дате платежа) с итогом за год и подсказкой о пороге освобождения от НДС на УСН; реестр счетов, реестр платежей и касса штрафов за период — всё в Excel. В кассе штрафов бухгалтеру видны только итоги: сколько принято наличными и сколько выставлено фирмам в счета, без подробностей по жильцам. Каждая выгрузка попадает в журнал действий. Экран «Отчёты» из старого меню (жильцы, блокировки, проходы) бухгалтеру закрыт — там всё только управленцам."},{title:"6а. Перед счётом посмотрите «Фирмы → Сверка»",text:"CRM каждую ночь сама сверяет по каждой фирме: сколько человек живёт и сколько мест под неё оплачено. Вам эта вкладка доступна на просмотр — заглядывайте перед выставлением счетов. Красное «живёт больше, чем оплачено» означает, что фирма второй месяц живёт сверх и это ещё не выставлено; «числятся, но по турникету не живут» — что счёт уходит за людей, которых на объекте нет. В самой форме счёта об этом же скажет строчка над полем «мест» («по сверке: живёт 34 при 30 оплаченных») и готовая позиция «Доплата за места сверх оплаченных» — она считается по дням, а не «людей × месяц», и галочка у неё СНЯТА: включаете вы, потому что счёт — это договорённость с фирмой, а не расчёт из базы. Фирмам «за фактически занятые» такая строка не предлагается: у них разница уже считается корректировкой по месячной сверке, иначе получился бы счёт дважды за одних людей."},{title:"7. Документы: счёт, акт, акт сверки, почта",text:"В строке счёта: зелёная «Оплата» — внести оплату (у неоплаченных), значок «скачать PDF», значок конверта — отправить фирме на почту (адрес — из карточки фирмы, отправка пишется в журнал), а в меню «…» — акт об оказанных услугах (всегда на сумму счёта; расшифровка по людям — по просьбе) и «Аннулировать» (спросит причину). Акт сверки взаиморасчётов — из «Долгов». Сверка с фирмой по дням проживания — вкладка «Сверка с фирмой», месяц выбирается."},{title:"7а. «Продажи мест»",text:"Раздел «Продажи мест» в меню — для сверки, сколько мест продано каждой фирме и какая выручка: «Продано / всего мест», «Занято по факту», «Выручка, ₽/мес», «Фирм на биллинге» и таблица по фирмам (сортировка — по заголовкам колонок). «Продано» считается по режиму фирмы и не означает «деньги пришли» — деньги смотрите в «Счета фирмам». Режим и цену задаёт карточка фирмы («Фирмы»). Кнопки «Снимок сейчас» у бухгалтера нет: ночной снимок система делает сама."},{title:"8. Миграционный контроль и фирмы",text:"Миграционный контроль видно по всей сети, но кнопки «Продлить», «Выдать», «Оштрафовать» — у администратора объекта. «Фирмы» в меню — карточки для просмотра и выставления счёта; заводить и править фирмы, цену и режим оплаты — администратор или директор. По прямой ссылке открываются /ecp (сверка с Контуром) и /audit (журнал действий)."},{title:"9. Чего в этой роли нет",text:"Заселение, выселение, блокировка, редактирование комнат, фирм и хостелов, «Снимок сейчас» на «Продажах» — не сюда. Отметки «Подписано» и «Отозвал согласие» в документах жильца на подпись — тоже: их ставит администрация объекта, ведь от этой отметки зависит, вправе ли объект обрабатывать данные человека. Для этого нужен администратор объекта или директор."},{title:"10. CRM попросила пароль снова",text:"Если ничего не делать в CRM 12 часов, она сама закроет вход — на случай, если ноутбук остался без присмотра. На экране входа будет «Вы вышли из-за долгого бездействия (12 ч)» — войдите заново. Срок можно сделать короче в «Мой профиль», но не дольше предела, который задаёт директор."},{title:"11. Календарь: заметки и напоминания",text:"Раздел «Календарь» в меню: кнопка «Заметка», текст, дата, время или «Весь день». В поле «Кому» — себе, сотруднику или всем на объекте. В срок придёт напоминание: колокольчик и карточка в углу экрана. Если вас в этот момент нет в CRM, через 3 минуты придёт письмо: только дата и время, без текста заметки. Куда придёт письмо — внизу экрана, там же адрес можно поменять. Личную заметку видите только вы и адресат. «Сделано» может нажать любой, кто видит заметку; изменить и удалить — автор."}]}],s=i.map(e=>({...e,steps:e.steps.filter(t=>!t.hideInDemo).map((t,l)=>({...t,title:t.title.replace(/^\d+\./,`${l+1}.`)}))})),n=e=>s.find(t=>t.matches.includes(e||""))||s[0],a={access:"Вход и права",residents:"Жильцы и заселение",rounds:"Обход",linen:"Постельные принадлежности",skud:"СКУД и турникеты",tech:"Технические сбои"},o=[{category:"access",question:"Не приходит письмо-напоминание из календаря",answer:"Письмо приходит, только если в срок вас не было в CRM: открытая вкладка на виду и недавняя работа в CRM считаются присутствием. Проверьте адрес внизу экрана «Календарь»: если логин — не настоящая почта, адрес надо указать, кнопка «Указать». В письме только дата и время, без текста заметки: откройте CRM, чтобы его прочитать."},{category:"access",question:"Кто видит мою заметку в календаре",answer:"Заметку «себе» — только вы. Заметку сотруднику — вы и он, директор её не видит. Заметку всем на объекте — сотрудники этого объекта, директор и бухгалтер."},{category:"access",question:"Как сменить свой пароль",answer:"Нажмите на своё имя внизу меню слева (на компьютере — ещё и шестерёнка в шапке): откроется «Мой профиль». Там «Сменить пароль»: текущий пароль, новый и повтор. Новый — не короче 8 знаков, с буквой и цифрой, не из самых частых («qwerty123», «Password1») и не повторяет логин или имя. При первом входе на форме «Придумайте свой пароль» есть кнопка «Предложить надёжный пароль» — пароль сразу виден, повтор не нужен, рядом «Копировать». После смены другие открытые вкладки и устройства попросят войти заново. Забыли текущий — новый задаст директор или администратор в «Сотрудниках»."},{category:"access",question:"Пишет «Вход закончился — войдите снова»",answer:"Вам сменили пароль, или вход не открывали больше недели. Войдите заново тем же логином и паролем: всё, что было сохранено, на месте."},{category:"access",question:"Почему меня выбросило: «Вы вышли из-за долгого бездействия»",answer:"Вы долго ничего не делали в CRM, и она сама закрыла вход — чтобы оставленным телефоном или ноутбуком не воспользовался чужой. Это не поломка: войдите тем же логином и паролем. Срок — 12 часов без действий (охране, прачечной и обходчику — 24 часа); точный предел для каждой роли задаёт директор в «Настройки» → «Сеть» → «Вход и сеансы». Открытая вкладка вход не держит: считаются только ваши действия — мышь, клавиатура, касание, прокрутка. Хотите строже — поставьте себе срок короче в «Мой профиль» → «Автовыход при простое». Сеть пропала или CRM перезапускается — это другое: вход сохранится, на экране будет «Нет связи с сервером CRM»."},{category:"access",question:"Забыл выйти из CRM на другом компьютере или телефоне",answer:"Откройте нажмите на своё имя внизу меню слева → «Мой профиль» → «Выйти на всех устройствах». CRM сразу попросит пароль на всех других компьютерах и телефонах, где открыт ваш вход, — в том числе на общем компьютере объекта. Там, где нажали, вы останетесь в CRM; пароль не меняется. Если пароль мог узнать кто-то другой — смените пароль там же: это тоже закрывает все входы. Под вашей учёткой работает коллега, а вам не дотянуться до CRM — попросите директора: «Сотрудники» → вы → «Закрыть все входы»."},{category:"access",question:"Пишет «Вход закрыт: сменили пароль или нажали «Выйти на всех устройствах»»",answer:"Хозяин учётки закрыл все её входы (или ему сменили пароль). Это не поломка. Если учётка ваша — войдите своим паролем. Если чужая — войдите под своей: за общим компьютером объекта каждый работает под своим логином, иначе в журнале действий его работа запишется на другого человека."},{category:"access",question:"Что значит галочка «Чужой компьютер» на входе",answer:"Вход не запоминается: он пропадёт, как только вы закроете вкладку или браузер, и следующий человек за этим компьютером в CRM не попадёт. В новой вкладке придётся войти заново. Ставьте её на общем планшете, чужом ноутбуке, компьютере в гостях."},{category:"access",question:"Пишет «Нет связи с сервером CRM»",answer:"Вход при этом сохранён — пароль вводить заново не нужно: CRM подключится сама, как только связь появится. Если дольше минуты: включён VPN — выключите его или добавьте адрес CRM в исключения VPN (пункт «российские сайты без VPN»); на мобильном интернете попробуйте Wi-Fi объекта, на Wi-Fi — мобильный интернет. Не помогло — сфотографируйте экран и напишите администратору: время, Wi-Fi или мобильный интернет (какой оператор) и включён ли VPN."},{category:"access",question:"CRM не открывается вовсе: «Не удаётся открыть страницу» или вечная заставка",answer:"Чаще всего виноват VPN: с зарубежного адреса CRM не открывается. Проверка: откройте сайт 2ip.ru — если страна не Россия, телефон ходит через VPN, даже если кажется, что он выключен. Выключите VPN или добавьте адрес CRM в его исключения. Открывайте CRM в браузере (Safari, Chrome) с иконки на экране «Домой», а не внутри Телеграма: Телеграм без VPN работает через раз, а с VPN не пускает CRM. Если заставка через 20 секунд показала мелкий текст — сфотографируйте его и отправьте администратору."},{category:"access",question:"Пишет «Слишком много неудачных попыток входа»",answer:"Под этим логином несколько раз подряд ввели неверный пароль, и вход для него закрыт на несколько минут — сколько ждать, написано в сообщении. Коллег на том же Wi-Fi это не касается. Забыли пароль — администратор задаст временный, при входе CRM попросит придумать свой."},{category:"access",question:"Не вижу в меню какой-то раздел, который видит коллега",answer:"Меню зависит от роли: обходчику показывается только «Обход», охране — свой набор разделов и т.д. Если раздел нужен по работе — обратитесь к директору/администратору, роль назначается в «Сотрудниках»."},{category:"access",question:"При действии пишет «Недостаточно прав»",answer:"Значит это действие закреплено за другой ролью (например, выселение — только за администратором и директором). Сообщение подскажет, кто именно может это сделать."},{category:"access",question:"У жильца штраф «выставлен фирме», и наличные принять нельзя",answer:"Штраф включили в счёт фирме — платит фирма по счёту, и второй раз с жильца его не берут. Если это ошибка (жилец платит сам), бухгалтер или директор аннулирует счёт в «Счетах фирмам» — штраф снова станет открытым, и его можно принять наличными. Штрафы попадают в счёт только по явной галочке при выставлении."},{category:"access",question:"У жильцов целой фирмы вдруг закрыт проход — «Фирма … не оплатила счёт № …»",answer:"На объекте включено правило «за неоплату фирмы»: счёт фирме просрочен дольше порога, и CRM закрыла проход всем её живущим. Откроется само, как только бухгалтер внесёт оплату (или счёт аннулируют). Одного человека можно разблокировать руками — по этому счёту правило его больше не тронет. Выключить правило — «Настройки → Блокировки»."},{category:"access",question:"Как закрепить свободное место за фирмой, если в комнате живут разные фирмы",answer:"На объекте с «плавающими местами» (настройка объекта «Места фирм») комнаты фирмам не принадлежат: в одной комнате могут жить люди разных фирм. Место под фирму держат закреплением: «Жильцы» → выберите фирму или найдите комнату → у строки «Свободно» дважды нажмите на ячейку фирмы и выберите фирму. Квота фирмы — это договорённость с ней, от неё считаются счета и сверка. В карточке фирмы под квотой видно: сколько её людей живёт, сколько свободных мест за ней закреплено и сколько мест ещё не распределено. Закрепили место, а квота уже занята целиком, — CRM предложит одной кнопкой поднять квоту; сняли закрепление у фирмы, которая была заполнена ровно, — предложит снизить. Отказались — место закреплено, квота прежняя. Заехал человек этой фирмы в комнату — закреплённое за ней место он и занимает. Списка комнат в карточке фирмы на таком объекте нет: комнаты там никому не принадлежат. На объекте, где комнаты закреплены за фирмами, сохранение карточки фирмы переводит всех живущих в её комнатах к этой фирме — если там живут люди другой фирмы, CRM сначала спросит."},{category:"access",question:"Как сделать, чтобы один администратор видел не всё, что другой",answer:"Через шаблоны доступа — это решает директор сети. «Настройки» → «Сеть» → «Шаблоны доступа» → «Новый шаблон»: назовите его («Ночной администратор»), выберите роль и снимите галочки с того, что этим людям не нужно, — разделы, вкладки внутри разделов (например, «Миграционный контроль» → «Сверка с Контуром» или «Постельные принадлежности» → «Мониторинг») и всплывающие уведомления («Проверить по камере» и другие). Назначить шаблон можно тремя способами: сразу нескольким — кнопкой «Назначить сотрудникам» у шаблона (отметьте людей галочками, снятая галочка снимает шаблон; там же видно, кому он назначен); новому человеку — при заведении, в поле «Роль» под ролью стоят её шаблоны («Администратор» → «— Ночной администратор»); одному — в его карточке («Сотрудники» → человек → «Доступ в CRM» → «Шаблон доступа»). Сменили человеку роль — шаблон прежней роли снимается сам, новый назначьте заново. Отключённому входу шаблон не назначается (снять можно). Проверить, что человеку открыто сейчас, — «Настройки» → «Сеть» → «Кто что видит» → «По сотрудникам»: выберите человека — видны его разделы, вкладки и уведомления с учётом шаблона. Изменения видны у сотрудника при следующем открытии CRM. Шаблон только убирает лишнее: дать охране то, что видит администратор, им нельзя. Без шаблона человек видит всё, что положено его роли. Пометка «только на экране» у пункта значит: он пропадает из меню, но его данные нужны и соседним разделам (например, карточке жильца), поэтому совсем закрыть их нельзя. Удалить шаблон можно, только когда он никому не назначен. Все изменения записываются в журнал действий."},{category:"access",question:"Как поменять почту утреннего письма и включить уничтожение данных уехавших",answer:"Это решает директор сети: «Настройки» → «Сеть» → «Сводка и сроки хранения». Утреннее письмо приходит в 9:40 — только то, где грозит штраф МВД или теряются деньги, и строка «Данные наружу за вчера». Впишите свою почту (можно до пяти адресов через запятую) и нажмите «Сохранить»; пусто — письмо уходит на адрес, заданный при подключении CRM. Ниже — уничтожение данных по срокам: каждую ночь CRM стирает у уехавших фотографию для пропуска через 90 дней после выезда и сканы документов через 365 дней. Карточка, реестр уведомлений МВД, согласия и журнал остаются навсегда. Перед включением нажмите «Что попадёт под удаление» — увидите, сколько фото и сканов по каждому объекту сотрётся ближайшей ночью; вернуть их можно только из резервной копии. Сроки обещаны жильцам в вашей политике и согласиях, поэтому выключать уничтожение стоит только на время. Включение и выключение записываются в журнал действий с вашим именем."},{category:"access",question:"Кто видит журнал действий, что в нём есть и можно ли из него удалять",answer:"Журнал действий — меню «Журнал действий» (у директора и администратора объекта; у бухгалтера доступ к журналу есть, но пункта в его меню нет; охране, прачечной, обходчику и фирме он закрыт). Директор видит всю сеть или один объект — по переключателю в шапке; администратор — только свой объект, чужой не откроется даже по адресу. По одному человеку — карточка жильца → «История» → «Кто что менял». Записывается всё, что создаёт, меняет или удаляет данные (заселение, правка карточки, штрафы, счета, сотрудники и их права, настройки), каждое открытие карточки с паспортом и каждое открытие скана (файл при этом уходит на ваш компьютер — в журнале так и написано), каждая выгрузка наружу — Excel, печать, файл для миграционного учёта. У записи есть кто, когда, с какого адреса, над кем и «что было → что стало» — по-русски: «Паспорт: номер», «Статус: проживает», «Комната: 214», «Фирма: Стройсервис», даты вида 30.09.2026 и суммы в рублях — а не служебные английские слова и внутренние номера записей. Если комнату или фирму потом удалили, в старой записи так и написано: «запись удалена»; переименовали — стоит нынешнее название. Обычные просмотры списков и фото не пишутся — иначе журнал утонул бы в шуме. Удалить или поправить запись нельзя никому: кнопки нет, а на самой базе стоит запрет, который действует и на разработчиков; срок хранения — навсегда. Пароли в журнал не попадают. Паспортные данные внутри «было → стало» зашифрованы тем же ключом, что и карточка. Каждое утро в письме-сводке есть строка «Данные наружу за вчера»: что выгрузили и кто, сколько сканов документов открыли, менялись ли доступы, заходили ли разработчики blaqit — тихий день так и выглядит: «ничего не выгружалось и не печаталось»."},{category:"residents",question:"Не могу заселить жильца — «Нет свободных мест»",answer:"В выбранной комнате закончились свободные койки. Выберите другую комнату или сначала освободите место (выселите/переселите текущего жильца)."},{category:"residents",question:"Жилец, которого выселили, всё ещё виден в списке",answer:"Обновите страницу (Ctrl/Cmd+Shift+R). Если и после обновления виден — сообщите разработчику: это может быть сбоем конкретного экрана."},{category:"skud",question:"Турникет не пускает жильца, хотя он заселён",answer:"Чаще всего дело в пропуске: он не оформлен или устарел. Откройте карточку жильца → сделайте фото веб-камерой → сохраните. Дальше система сама доводит пропуск до турникета за несколько минут."},{category:"skud",question:"Сфотографировали жильца, а на турникете он так и не появился",answer:"Синхронизация занимает время (обычно до нескольких минут). Если прошло дольше и жильца всё ещё нет — администратор смотрит «СКУД → Здоровье СКУД»: там одной строкой видно, кто не заведён на турникете и почему, и есть кнопка «Повторить». Если объект переведён на ручной пропуск по списку, пропуска на терминал не уезжают намеренно."},{category:"skud",question:"Не вижу кнопку «Выселить» в карточке жильца",answer:"Выселение — действие только для директора и администратора объекта. Охрана и обходчик могут блокировать и разблокировать, но не выселять — так и должно быть."},{category:"rounds",question:"Случайно отметил не того жильца на обходе",answer:"Нажмите на ту же кнопку ещё раз — отметка снимается. Дальше можно отметить правильно."},{category:"rounds",question:"При замечании просит фото и не даёт сохранить без него",answer:"Это осознанное ограничение для серьёзных нарушений (пожарная безопасность, курение, посторонний в комнате): без фото такое замечание невозможно доказать фирме-заказчику. Сделайте снимок камерой телефона прямо в этом окне — можно приложить сразу несколько кадров."},{category:"residents",question:"Скан не загружается: «формат HEIC» или «не удалось прочитать PDF»",answer:"HEIC — так снимает iPhone, компьютер этот формат не читает. Проще всего открыть CRM на самом iPhone и выбрать фото оттуда — телефон сам отдаст JPG. Или переключите камеру iPhone: Настройки → Камера → Форматы → «Наиболее совместимый», и новые снимки будут в JPG. PDF со сканера CRM переводит в картинку сама, прямо в браузере; если файл всё же не прочитался (повреждён или защищён паролем) — сохраните скан в программе сканера как JPG и загрузите его. В «Документы» карточки PDF ложится по страницам — до 10 страниц из одного файла."},{category:"rounds",question:"Не открывается камера при сканировании штрихкода или фото",answer:"Браузер должен получить разрешение на камеру — проверьте в настройках браузера/телефона, что разрешение выдано именно этому сайту. Если открываете CRM внутри Telegram — иногда помогает открыть тот же адрес в обычном браузере."},{category:"linen",question:"Сканер пишет «Бельё меняли недавно» и не выдаёт",answer:"Между сменами действует минимальный срок (по умолчанию неделя, настройка объекта); строка называет дату и время прошлой выдачи, кто выдал и дату следующей смены. Если менять надо раньше — досрочную выдачу проводит администратор или директор с указанием причины, она сохраняется в журнале белья. После нового заселения срок не действует."},{category:"linen",question:"Прачечная отправила жильца ко мне — «загорелось красным», а у него выдача записана",answer:"Откройте карточку жильца → «История» → «Бельё и оснащение». Там рядом с выдачами видны отказы сканера («Отказ в выдаче» — оранжевым, с причиной: рано и когда была прошлая выдача, выселен) и повторные сканы («Повторный скан — не записано» — серым): когда, что ответила CRM и кто сканировал. Отказ «рано» через минуту после выдачи — это повторно прочитанная наклейка: бельё человек получил. С 01.11.2026 повтор в течение 5 минут CRM сама показывает прачечной зелёным «уже выдано», а не отказом. Отказы по номерам, которых нет ни у кого, — в «Журнале действий», действие «Бельё: отказ в выдаче»: номер там целиком и подсказка «проверьте печать наклейки» — по нему можно найти и перепечатать наклейку."},{category:"skud",question:"В журнале проходов у записи стоит «Неизвестно» вместо входа или выхода",answer:"CRM не опознала терминал, приславший проход (по нему не нажали «Проверить связь» или у него сменился адрес). Проход записан, но без направления; в расчёт ночёвок он не входит. Администратор: «СКУД → Оборудование и настройка» → «Проверить связь» на каждом терминале."},{category:"skud",question:"В карточке у даты «находился 6 ч», а виден только выход — откуда часы?",answer:"Вход был накануне вечером: например, вошёл 13-го в 21:49, вышел 14-го в 06:45. У даты стоит факт — сколько часов человек был внутри именно в это число (14-го — с полуночи до 06:45), а сам вход лежит под 13-м. Ночь при этом не делится: между двумя датами стоит строка «ночь 13→14 · внутри 8 ч 56 мин» — это и есть оценка, по ней считается «по норме N из M ночей». Если у даты «выход не зафиксирован» — человек вошёл и больше суток не выходил через турникет: скорее всего, прошёл за кем-то в спину; спросите охрану."},{category:"skud",question:"Последняя ночь в карточке написана курсивом — почему?",answer:"Ночь считается окном с 16:00 до 16:00 следующего дня: вечерний приход, сама ночь и утро — одним куском; так засчитывается и тот, кто работает ночью и отсыпается днём. Курсив — окно ещё не кончилось: часы у этой ночи ещё могут добавиться, если человек вернётся до 16:00. Утром красная строка у последней ночи — не приговор: к четырём часам дня она может стать зелёной. Где человек сейчас, показывает строка «Сейчас в хостеле / на улице» над лентой — она не зависит от ночи."},{category:"skud",question:"Сотрудник уехал в отпуск и висит в «Вошли и не вышли» — как убрать?",answer:"Кнопкой «Отметить выход» — в строке списка «Вошли и не вышли» или в карточке рядом с «Сейчас в хостеле». Укажите причину («уехал в отпуск», «ушёл за кем-то в спину»): в журнал проходов запишется выход текущим временем с вашим именем и пометкой «отметка», в журнал действий — кто и почему, и человек уйдёт в «на улице». Задним числом выход не пишется: когда он ушёл на самом деле, CRM не знает. В расчёт проживания отметка не идёт — она отвечает только на «где он сейчас». Вернётся — первый же вход через турникет закроет вопрос как обычно. Может администратор или охрана."},{category:"skud",question:"В журнале проходов у выхода стоит «отметка · Иванова М.: уехал в отпуск» — это что?",answer:"Это не проход через турникет: выход отметил сотрудник кнопкой «Отметить выход», потому что турникет его не записал. Строка нарочно отличается от настоящего прохода — при проверке журнал сверяют с терминалом, и «выход» без терминала должен объяснять сам себя. Кто и когда отметил — в журнале действий."},{category:"skud",question:"Между датами написано «ночи 3→10 · не заходил (7 ночей)» — одной строкой?",answer:"Да: ночи подряд без единого прохода между ними сворачиваются в одну строку, чтобы неделю отсутствия не читать по семь одинаковых строк. Раскрыть их по одной нельзя, но каждая есть на шкале в «СКУД → Фактическое проживание» — наведите на клетку."},{category:"linen",question:"Вернули жильца из «Уехавших», а у него в прачечной «Ожидает» — почему?",answer:"Если человека не было 15 дней или дольше, комплект он при отъезде сдал: счёт белья начинается заново, как у новосёла, и есть 3 дня на получение нового. В журнале белья стоит отметка «Возврат после отсутствия — бельё сдано» с числом дней. Если перерыв был короче — счёт не обнуляется: комплект всё это время был у человека на руках."},{category:"linen",question:"В карточке жильца строка «Бельё: 16 дней с последней выдачи · пора менять» — что за цвета?",answer:"Это возраст комплекта, считается от последней выдачи в журнале белья. Зелёная — до 14 дней, жёлтая «пора менять» — с 14-го дня до порога автоблокировки объекта (обычно 20), красная «просрочка» — с самого дня порога: в этот же день срабатывает автоблокировка (если она включена) и краснеет строка в мониторинге прачечной. Если выдач не было: первые 3 дня после заселения серая «ещё не выдавалось», потом красная. Отсутствие 15 дней и дольше счёт обнуляет — как в мониторинге прачечной. Красная строка сама по себе не блокирует: автоблокировка за бельё — отдельная настройка объекта."},{category:"linen",question:"На нашем объекте бельё не выдают через CRM, а экран пишет «без белья» почти у всех. Что делать?",answer:"Попросите директора выключить учёт белья для объекта: «Настройки → Бельё и прачечная → Бельё ведётся в CRM». После этого счётчик «без белья», мониторинг прачечной, напоминания и задания обхода «Не получал бельё» на объекте пропадут, строки про бельё в карточке жильца не будет, а автоблокировка по белью перестанет срабатывать совсем, даже если включена. Начнёте выдавать бельё через CRM — директор включит учёт обратно там же."},{category:"linen",question:"Создал заявку на постельное на нескольких жильцов сразу — это правильно?",answer:"Да. Даже если вы отмечали сразу несколько человек одной кнопкой, система создаёт отдельную заявку на каждого — так и должно одобряться и учитываться по отдельности."},{category:"residents",question:"Сверка с Контуром показывает человека, которого «нет в Контуре»",answer:"Значит его не поставили на миграционный учёт (или сняли с учёта раньше, чем убрали из CRM). Это не ошибка сверки — это и есть та проблема, которую она обязана находить. Разберитесь с конкретным случаем и отметьте строку «обработано». Другое дело, если вверху вкладки жёлтая плашка «Кабинет не прочитан»: робот не смог взять список, и людей этого кабинета сверка не сравнивала. Они стоят в отдельном списке «Не сверялись», искать их дела не нужно."},{category:"residents",question:"Как скачать список в Excel и почему у охраны нет такой кнопки",answer:"На каждом списке (жильцы, заблокированные, уехавшие, миграционный контроль, нарушения, история белья, журнал проходов, журнал действий, отчёты бухгалтера) есть кнопка «Excel». В файл уходит ровно то, что отобрано на экране (фильтры и галочки), а имя файла говорит, что внутри: «Жильцы_Северная_Стройсервис_Узбекистан_2026-09-19.xlsx» — что, объект, отбор, дата. Даты в файле — настоящие даты, суммы — числа, на шапке стоит автофильтр. Журнал проходов выгружается за период не длиннее года; период не выбран — за последний месяц (имя файла называет даты). Каждая выгрузка записывается в журнал действий: список с датами рождения и гражданством — это персональные данные, и на вопрос «кто и что выгрузил» CRM обязана отвечать. Охране, прачечной и обходчику кнопки «Excel» нет намеренно — их работа у турникета, сканера и на этаже; печать у них остаётся."},{category:"residents",question:"Фирма-заказчик просит заселить или выселить своего сотрудника — где она это делает?",answer:"В своём кабинете: отмечает живущих людей → «Попросить выселить» с датой или «Заявка на заселение» (объект, дата, сколько человек, ФИО текстом). Файлы не прикладываются. Заявка появляется в «Заявках фирм» — число в меню, колокольчике и на «Главной». Сама заявка ничего не делает: заселяет и выселяет администратор обычными кнопками и отвечает фирме «Принято» или «Отклонить» / «Мест нет»."},{category:"linen",question:"Как понять, обманывает нас прачечная или нет",answer:"Главное — взвешивать чистое на своих весах при каждом привозе и вписывать итог в клетку «наши весы» рядом с весом по накладной. CRM считает недовес: накладная минус наши весы. Это одно и то же сухое бельё в один день, поэтому видно сразу, по одной поездке. Прачечная берёт деньги за вес накладной, и недовес — прямая переплата: впишите цену за кг в поле «Цена стирки» над таблицей, и CRM покажет её в рублях. Итог за всё время — крупно над таблицей, по каждому дню — в строке таблицы, за месяц — в строке «Итого». Больше 2 % — красным: это уже не погрешность весов. Колонка «Чистое − грязное» — другое: грязное весит больше чистого, поэтому там минус нормален."},{category:"linen",question:"Отдали 600 кг, а возят частями — как не потерять остаток",answer:"Ничего закрывать не надо. Прачечная здесь — расчётный счёт, а не партии: в строке каждого дня — сколько отдали и сколько привезли за этот день, а разница показана сверху («У прачечной сейчас N кг ≈ M комплектов»). Можно спокойно отдать новую машину, пока старую возвращают частями: цифра сама сложится. Рядом написано, сколько дней самому старому невозвращённому — дольше недели цифра краснеет, это и есть повод звонить."},{category:"linen",question:"Прачечная привезла чистое по отгрузке, которой нет в CRM — как записать?",answer:"Так бывает в первые дни учёта (бельё уехало в стирку до CRM) или когда отгрузку забыли вписать. Впишите привоз в строку дня, за который он, — накладную, наш вес и штуки, как обычно: штуки сразу придут на склад. В последней колонке строки появится оранжевое «нет отгрузки?». Если вес той отгрузки известен — впишите его в «Отдали грязного». Если не взвешивали — нажмите «нет отгрузки?»: привоз останется на складе, а в «Чистое − грязное» за месяц не пойдёт (вычитать его не из чего) и будет виден в «Итого» отдельно: «+N кг вне счёта». Снять отметку — «вне счёта ×». Отметка и её снятие пишутся в журнал действий. Вес задним числом не придумывайте: на него ссылаются в разговоре с прачечной."},{category:"linen",question:"Как понять, что должно приехать с прачечной завтра",answer:"Вкладка «Прачечная», таблица месяца: в строке дня, за который чистое ещё не привезли, стоит «ждём». Сумма таких дней — цифра «У прачечной сейчас» над таблицей, рядом — сколько дней самому старому невозвращённому; дольше недели цифра краснеет — это повод звонить."},{category:"linen",question:"Приехало чистое — надо ещё оприходовать через «Закупку»?",answer:"Нет, и это важно: приход на склад делается сам, когда вы вписываете штуки из накладной (простыни, пододеяльники, наволочки) в строку дня в таблице на вкладке «Прачечная». Кнопка «Закупка» — только для купленного нового. Раньше приход с прачечной вводили дважды (там и там), и через месяц это были две разные цифры."},{category:"linen",question:"Не вижу вкладку «Прачечная» (цикл стирки) на странице «Постельные принадлежности»",answer:"Вкладки склада и стирки видят администрация и охрана. У роли «Прачечная» экран нарочно один — сканер выдачи, бухгалтеру бельё не показывается вовсе. Если вкладки нужны по работе — обратитесь к директору, роль настраивается в «Сотрудниках»."},{category:"tech",question:"После обновления CRM что-то выглядит и работает не так",answer:"Обновите страницу с очисткой кэша: Ctrl+Shift+R (Windows) или Cmd+Shift+R (Mac). Если открываете внутри Telegram — закройте мини-приложение и откройте заново."},{category:"tech",question:"Ошибка «Сервер не ответил — повторите»",answer:"Кратковременный сбой связи или перезапуск сервера — не ваша ошибка. Отметка не потерялась молча: повторите то же действие ещё раз через несколько секунд."},{category:"tech",question:"С включённым VPN CRM не открывается, а другие сайты работают",answer:"Это не сбой CRM. С лета 2026 года подключения со многих VPN-серверов к сайтам на российских хостингах не пропускаются — так же через VPN не открываются и многие другие российские сайты. Выключите VPN или добавьте адрес CRM в исключения VPN (пункт обычно называется «напрямую», «без VPN» или «раздельное туннелирование»). С исключением CRM работает и с включённым VPN — и в России, и за границей. Если в вашем VPN исключений нет — сообщите директору или в поддержку: обход настраивается на самом компьютере за минуту."}],r=[{key:"start",label:"Начало работы",articles:[{key:"roles",title:"Вход и роли",lead:"Кто что видит и может в системе. Права зависят от роли — у каждого свой набор разделов.",blocks:[{t:"h",s:"Как войти"},{t:"p",s:"Откройте адрес CRM, введите логин и пароль. Для сетевых ролей сверху выбирается объект."},{t:"h",s:"Роли"},{t:"li",s:"Директор — вся сеть: объекты и настройки, фирмы, продажи мест, финансы."},{t:"li",s:"Администратор — свой объект: жильцы, заселение, ФМС, комнаты."},{t:"li",s:"Охрана — пропуска, фото для пропуска, проходы, блокировки (заселяет администрация)."},{t:"li",s:"Бухгалтер — счета фирмам, долги, отчёты; жильцов не заселяет."},{t:"li",s:"Обходчик — обход с телефона: кто живёт в комнате, порядок, заметки."},{t:"li",s:"Прачечная — учёт постельного белья."},{t:"li",s:"Фирма — только свои жильцы и свободные места по квоте."},{t:"note",s:"Каждый видит только то, что положено его роли и объекту. Данные объектов изолированы."},{t:"tip",s:"Директору: «Настройки» → «Сеть» → «Кто что видит» — таблица, что открыто каждой роли, и вкладка «По сотрудникам» (что открыто конкретному человеку). Лишнее у человека прячут «Шаблоны доступа» (там же): шаблон только сужает права роли, расширить не может."}]},{key:"object",title:"Выбор объекта",lead:"В сети несколько хостелов. Переключатель объекта сверху определяет, с каким вы сейчас работаете.",blocks:[{t:"step",s:"Нажмите название объекта в верхней панели и выберите нужный."},{t:"p",s:"Списки жильцов, комнат, фирм и настроек сразу переключатся на выбранный объект."},{t:"tip",s:"Сетевые роли видят все объекты; администратор и охрана — только свой."}]},{key:"search",title:"Поиск по CRM: Ctrl+K",lead:"Самый быстрый способ найти человека, комнату или раздел — с любого экрана.",blocks:[{t:"step",s:"Нажмите Ctrl+K (на Mac — ⌘K) или значок лупы в шапке. Повторное нажатие закрывает окно, Esc — тоже."},{t:"step",s:"Введите хотя бы две буквы: часть фамилии, номер комнаты или название раздела («Жильцы», «Календарь»)."},{t:"step",s:"Стрелки вверх и вниз выбирают строку, Enter открывает её. Мышью можно нажать на строку."},{t:"note",s:"Сначала в списке идут люди (с пометкой «живёт», «заблокирован» или «уехал» и номером комнаты), потом комнаты, потом разделы. Люди ищутся на объекте, выбранном в шапке. Телефонов и номеров документов в результатах нет — они в карточке."},{t:"tip",s:"Раздел, которого нет в боковом меню (например, у директора «Постельные принадлежности»), тоже находится поиском, если он вам доступен."},{t:"note",s:"Представителю фирмы поиск не показывается."}]},{key:"overview",title:"Обзор интерфейса",lead:"Слева — разделы, сверху — объект и поиск, в центре — рабочая область.",blocks:[{t:"img",src:"/help/overview.png",caption:"Так выглядит CRM сразу после входа (экран директора).",pins:[{n:1,x:10.7,y:8.9,label:"Переключатель объекта. Нажмите — выберете, с каким хостелом работаете. Списки жильцов и комнат сразу переключатся."},{n:2,x:10.1,y:19.9,label:"Меню разделов. Набор пунктов зависит от роли — лишнее не показывается."},{n:3,x:16.9,y:25.1,label:"Цифра у раздела — сколько дел требует внимания. Здесь (учебные данные): 21 человек с проблемой по срокам."},{n:4,x:44.3,y:13.9,label:"Рабочая область. Всё, что делаете, происходит здесь: на «Главной» — финансы, что требует внимания и заполненность хостела."}]},{t:"h",s:"Основные разделы"},{t:"li",s:"Жильцы — список проживающих, заселение, карточки."},{t:"li",s:"Миграционный контроль — статусы ФМС, просрочки, сверка с Контуром."},{t:"li",s:"СКУД / Проходы — журнал проходов, кто внутри."},{t:"li",s:"Уехавшие — история заездов и выселений."},{t:"li",s:"Фирмы — контрагенты и квоты."},{t:"li",s:"Заблокированные — у кого закрыт пропуск; рядом вкладка «Нарушения» (штрафы и нарушения режима)."},{t:"li",s:"Пропускной пункт — лента проходов крупно; в ручном режиме здесь охрана решает, пускать ли."},{t:"li",s:"Продажи мест, Счета фирмам, Заявки фирм — деньги и общение с фирмами. Во «Фирмах» вкладка «Заявки от фирм» — ваш список тех, кто только собирается селиться."},{t:"li",s:"Календарь — заметки и напоминания себе, коллеге или всем на объекте."},{t:"li",s:"Поиск по CRM — лупа в шапке или Ctrl+K (на Mac ⌘K): человек, комната или раздел."},{t:"li",s:"Постельные принадлежности, Журнал обхода — бельё и обход."},{t:"li",s:"Сотрудники — логины и пропуска персонала; Журнал действий — кто что менял."},{t:"li",s:"«Настройки» — дерево слева: «Сеть» (объекты, юр. лица, «Кто что видит» — карта разделов и действий по ролям, у директора ещё и «По сотрудникам»: что открыто конкретному человеку с учётом его шаблона; «Шаблоны доступа», «Вход и сеансы» — через сколько часов без действий CRM просит пароль, по каждой роли, оформление), «Объект» (профиль, миграционный учёт, Контур, бельё, блокировки, уведомления) и «Я» (свой пароль, свой срок автовыхода, тема); турникеты и агент — в разделе «СКУД»."},{t:"note",s:"Набор разделов зависит от роли — лишнее не показывается."}]}]},{key:"residents",label:"Жильцы и заселение",articles:[{key:"zaselenie",title:"Заселение жильца",lead:"Завести нового жильца за минуту: сфотографировать паспорт, проверить данные, выбрать комнату и фирму, сделать фото — и пропуск сам уедет на турникет.",blocks:[{t:"note",s:"Зачем: отсюда данные уходят в миграционный учёт (Контур.ФМС) и на турникеты (СКУД). Чем аккуратнее заведён жилец, тем меньше рисков штрафов и проблем с проходом."},{t:"h",s:"1. Открыть форму"},{t:"step",s:"Раздел «Жильцы» → кнопка «Заселить» вверху слева (первая в ряду кнопок)."},{t:"img",src:"/help/residents.png",caption:"Раздел «Жильцы» с открытой панелью «Фильтры»: поиск, фильтры и кнопки над списком.",pins:[{n:1,x:74.4,y:13.2,label:"Кнопки над списком: «Заселить» (первая слева) откроет форму заселения, «Комната» — новую комнату, «Excel» скачает список файлом (в имени — объект и включённый отбор), «Печать» подготовит список на бумагу."},{n:2,x:48.5,y:20,label:"Быстрый поиск. Ищет сразу по ФИО, номеру комнаты, штрих-коду и фирме — вводите что помните."},{n:3,x:46.2,y:44.8,label:"Фильтр по этажу. Нажали «2 эт» — остались только его комнаты; можно отметить несколько этажей, повторное нажатие снимает."},{n:4,x:46.1,y:56.8,label:"Фильтры по типу комнат и занятости. «Только пустые места» — когда ищете, куда заселить."},{n:5,x:92.5,y:20,label:"Кнопка «Фильтры» открывает и закрывает панель: фирма, гражданство, даты, этаж, юр. лицо, статус и метки («На границе», «Нет пропуска», «Просрочена регистрация» и другие)."}]},{t:"note",s:"В строке каждой комнаты серым написано, кто в ней живёт: «Узбекистан 3 · Таджикистан 1». Это подсказка при подселении — к землякам обычно спокойнее. Считается по ВСЕМ жильцам комнаты, поэтому при фильтре по фирме число в подписи может быть больше, чем строк на экране: остальные — люди других фирм, они никуда не делись."},{t:"img",src:"/help/checkin-empty.png",caption:"Форма заселения сразу после открытия.",pins:[{n:1,x:42.9,y:22.1,label:"«Распознать документы» — сфотографируйте паспорт, миграционную карту и патент. Можно одним листом: система разберётся, где что."},{n:2,x:64.3,y:22.1,label:"«Загрузить без распознавания» — если снимок плохой и заполнять будете руками."},{n:3,x:63.8,y:26.7,label:"«Цифровой ID (MAX)» — для гражданина РФ без бумажного паспорта: считайте QR из приложения MAX, данные подставятся сами."},{n:4,x:50.5,y:43.3,label:"Гражданство — ПЕРВОЕ поле, с него всё начинается."},{n:5,x:50,y:74,label:"Блок документов пока пустой и подписан «Сначала выберите гражданство»: у россиянина и у иностранца нужны разные документы, поэтому раньше времени поля не показываются."},{n:6,x:33.3,y:90.4,label:"Счётчик «Осталось заполнить» — сколько обязательных полей ещё пустые."},{n:7,x:65.4,y:90.5,label:"Кнопка не гаснет никогда. Нажмите — она назовёт, чего не хватает. Неполную карточку сохранить нельзя: документы жильца при заселении на руках."}]},{t:"img",src:"/help/checkin-documents.png",caption:"То же окно после выбора гражданства — появились нужные документы.",pins:[{n:1,x:50.5,y:21.7,label:"Выбрали гражданство — здесь Узбекистан."},{n:2,x:50,y:54.4,label:"Блок документов сразу раскрылся под это гражданство: иностранный паспорт, дальше миграционная карта и патент. Для гражданина РФ поля были бы другие."},{n:3,x:32.2,y:51.7,label:"Галочки «Есть ВНЖ» и «Есть виза» меняют набор полей ниже — ставьте, если такие документы у человека есть."}]},{t:"h",s:"2. Сфотографировать паспорт"},{t:"step",s:"Нажмите «Распознать документы» и сфотографируйте паспорт — ФИО, латиница, серия/номер, даты, место рождения заполнятся сами."},{t:"step",s:"Проверьте распознанные поля (подсвечены) — особенно номер паспорта, даты и латиницу ФИО."},{t:"tip",s:"Снимайте документ на ровном фоне при хорошем свете. Поддерживаются даже редкие гражданства (Индия, КНДР)."},{t:"mock",id:"zaselenie-form",pins:[{n:1,label:"«Распознать документ» — сфотографировать паспорт, поля заполнятся сами."},{n:2,label:"Поля данных подсвечены — их заполнило распознавание, проверьте."},{n:3,label:"«Заселить жильца» — заводит жильца; пропуск на турникет уйдёт сам, когда в карточке появится фото."}]},{t:"h",s:"3. Проверка на дубли"},{t:"p",s:"Пока вводите паспорт (или ФИО с датой рождения), система ищет этого человека по всей сети — на всех объектах, не только на вашем."},{t:"step",s:"Совпал паспорт → окно «Этот человек уже есть в CRM». Это тот же человек, вторую карточку ему заводить нельзя: уехал здесь — «Вернуть», уехал на другом объекте — «Заселить сюда (переезд)» (документы подставятся из прежней карточки, фото переедет само и сразу уйдёт на турникеты этого объекта; сканы — заново, согласия распечатать и подписать заново — здесь другой объект), живёт здесь — найдите его в списке. Живёт на другом объекте, а переезжает к вам — «Заселить сюда и попросить … оформить выезд»: заселяете сразу, а тот объект увидит запрос над своим списком жильцов и сам подтвердит выезд (выселить у себя его можете не вы). Ошиблись в номере — «Номер паспорта введён с ошибкой» вернёт вас в форму."},{t:"step",s:"Над списком жильцов жёлтая плашка «Переехали на другой объект — подтвердите выезд» — вашего жильца заселили на другом объекте сети. Если он правда уехал — «Подтвердить выезд»: CRM выселит его у вас днём заселения там, дальше снимите с учёта в «Уехавших». Если он живёт у вас — «Он живёт у нас» и коротко почему: ответ увидит объект, который заселял. Пока вы не ответили, человек числится в двух местах, а утром о нём напомнит письмо директору."},{t:"step",s:"Совпали только ФИО и дата рождения → окно «Похожий человек уже был». В нём фото (если есть), фирма, где и когда проживал, паспорт прежней карточки рядом с тем, что вы ввели; если в старой карточке паспорта нет — окно так и скажет: «не записан — сравнить не с чем» (это чаще всего он же, карточку не дозаполнили). Это он с новым паспортом — «Вернуть» (уехал здесь) или «Заселить сюда (переезд)» (уехал на другом объекте); другой человек — «Другой человек — заселить нового». Ваш выбор записывается в журнал."},{t:"tip",s:"Ответили в окне один раз — про этого человека оно больше не спросит, даже если дальше вы исправляете паспорт или ФИО: выбор виден строкой над формой, передумали — «Изменить». Снова окно появится, только если найдётся другая карточка или паспорт совпадёт с тем, кого вы назвали «другим человеком». Пока вы набираете в поле, проверки нет — она идёт, когда вы переходите к следующему полю."},{t:"warn",s:"Сервер сам не даст завести второго человека с тем же паспортом, даже если закрыть окно. Единственный обход — «Ещё → Всё равно завести нового» с причиной (например, в старой карточке опечатка в номере); причина попадает в журнал действий, и старую карточку нужно будет исправить."},{t:"tip",s:"В окне видно долг человека по штрафам. «Вернуть» возвращает долг в «Открытые»; вторая карточка спрятала бы его в «Уехавших» — так люди уходили от долга."},{t:"step",s:"Если за человеком есть незакрытое нарушение (со штрафом или без штрафа) — красная плашка «Нарушение» (несколько — «Нарушение ×2»), без суммы. Ниже строка «Нарушения за всё время: N» — нажмите, раскроется список со всех объектов сети: дата, объект, причина, сумма и что с ним стало (не оплачен, оплачен, снят, выставлен фирме). Нарушений не было — строки нет."},{t:"warn",s:"Есть долг — «Вернуть» и «Заселить сюда (переезд)» сначала спросят: «У жильца долг … Заселить всё равно?». «Заселить всё равно» — ваше решение, оно попадает в журнал действий: кто, кого, сколько долга, на каком объекте. «Отмена» — ничего не происходит. Без долга вопроса нет. Вернуть должника пачкой из «Уехавших» нельзя — только по одному, с этим вопросом."},{t:"h",s:"4. Фирма, комната, юр.лицо"},{t:"step",s:"Выберите фирму и комнату. Юр.лицо (ЭЦП для ФМС) обычно подтягивается из комнаты."},{t:"mock",id:"zaselenie-room",pins:[{n:1,label:"Комната с «★» — там уже живёт эта фирма, удобно доселить к своим."},{n:2,label:"Если квота фирмы на объекте превышена — появится предупреждение."}]},{t:"warn",s:"Нельзя селить в одну комнату сотрудников и обычных жильцов вместе — система предупредит."},{t:"h",s:"5. Срок регистрации"},{t:"step",s:"Укажите дату окончания регистрации — по ней система следит за просрочкой (нельзя дату в прошлом)."},{t:"h",s:"6. Штрих-код и фото"},{t:"step",s:"Штрих-код создаётся автоматически (можно распечатать). Камеры в форме заселения нет: фото для пропуска делается уже после заселения — в карточке жильца, кнопка «Сделать фото» (обычно это делает охрана)."},{t:"warn",s:"Без фото жилец заселится, но пропуск не оформится — проходить он не сможет."},{t:"h",s:"7. Заселить"},{t:"step",s:"Нажмите «Заселить жильца». Как только в карточке появится фото, система сама заведёт жильца на турникет и оформит ему пропуск."},{t:"tip",s:"Возврат уехавшего: не заводите заново — найдите его в «Уехавших» и нажмите «Вернуть». Штрих-код, история и данные сохранятся."},{t:"img",src:"/help/evicted.png",caption:"Раздел «Уехавшие»: архив выселенных (таблица прокручена вправо — там кнопки).",pins:[{n:1,x:89.5,y:50,label:"Найдите человека и нажмите «Вернуть» — заведётся не дубль, а тот же жилец со всей историей. Рядом — «Отметить снятым» (снятие с миграционного учёта) и значок корзины (удалить навсегда — только в крайнем случае)."}]}]},{key:"passport",title:"Распознавание документов",lead:"Что система заполняет сама, что вводится руками и как понять, где она не уверена.",blocks:[{t:"img",src:"/help/resident-documents.png",caption:"Вкладка «Документы» в карточке жильца.",pins:[{n:1,x:80.5,y:6.6,label:"Вкладки карточки: «Основное» — кто и где живёт, «Документы» — паспорт, сканы, сверка с Контуром, документы на подпись, «История» — заезды, проходы, бельё."}]},{t:"h",s:"Заполняется автоматически"},{t:"li",s:"ФИО (кириллицей) и его латиница из машинной зоны паспорта."},{t:"li",s:"Гражданство, дата рождения, пол."},{t:"li",s:"Серия/номер паспорта, кем и когда выдан, срок действия."},{t:"li",s:"Данные миграционной карты: серия, номер, дата въезда, КПП. Если КПП со штампа не нашёлся в справочнике, поле покажет прочитанный текст красным — выберите пункт из списка, иначе уведомление в МВД уйдёт с пустой графой."},{t:"li",s:"Вид на жительство, если он есть на скане — галочка ставится сама."},{t:"h",s:"Откуда берётся ФИО"},{t:"p",s:"Сначала с патента, потом с миграционной карты — там оно уже написано по-русски и в том виде, в каком его признаёт МВД. Из паспорта берётся в последнюю очередь, с переводом на русский: такой перевод всегда риск разночтения, поэтому поле помечается как неуверенное."},{t:"h",s:"Вводится руками"},{t:"li",s:"Дата выдачи патента — она на обороте и в скан не попадает. Срок патента система дальше считает сама: год со дня выдачи."},{t:"li",s:"Дата окончания регистрации, фирма и комната."},{t:"h",s:"Место рождения"},{t:"p",s:"У гражданина РФ переписывается из паспорта дословно, со всеми сокращениями («Орловской обл.», а не «Орловская область»). У иностранца местом рождения в уведомлении служит страна гражданства — город и область не спрашиваются и в файл не идут."},{t:"h",s:"Проверить глазами"},{t:"p",s:"Распознавание экономит время в разы, но ответственность на операторе. Поля с жёлтой полоской система заполнила неуверенно — сверьте их со сканом (он открыт рядом, вкладки сверху переключают между документами листа)."},{t:"note",s:"Красная полоска — другое: поле обязательно и не заполнено либо заполнено неверно; под ним написано, что не так."},{t:"note",s:"Сообщение «распознан в упрощённом режиме» значит, что распознавание сейчас работает хуже обычного: основные поля отмечены жёлтым, а сверить со сканом надо каждое заполненное. Разработчику о сбое уже сообщено автоматически."}]},{key:"barcode",title:"Штрих-код и пропуск",lead:"Два элемента карточки, о которых часто спрашивают.",blocks:[{t:"h",s:"Штрих-код"},{t:"p",s:"Создаётся автоматически при заведении жильца, уникален. «Печать по Bluetooth» или «Распечатать» в карточке и при заселении печатает готовую наклейку на комплект белья: штрих-код, фамилия и имя (так жильцы не путают комплекты), правила смены и часы прачечной вашего объекта; мелко внизу по центру — «Дата выдачи: …» (это дата заселения). Окно перед печатью показывает наклейку ровно в том виде, в каком она выйдет из принтера."},{t:"li",s:"Тексты, размер наклейки и что крупнее (имя, правила или часы) — «Настройки → Бельё и прачечная → Этикетка белья»; там же живой предпросмотр. Чем короче строка, тем крупнее она напечатается — длинную фразу разбейте на две строки. Место, которое не занял текст, уходит штрих-коду: мельче текст — выше полоски и тем легче сканеру."},{t:"li",s:"«Печать по Bluetooth» — прямо на принтер этикеток с любого компьютера рядом, без драйвера и кабеля, в Google Chrome или Microsoft Edge. В первый раз Chrome спросит, какой принтер: выберите CT221B и нажмите «Подключить». На телефоне с приложением принтера Bluetooth должен быть выключен — иначе принтер занят. После печати компьютер держит связь с принтером 5 минут — следующие наклейки выходят быстрее, но телефон и другие компьютеры принтер в это время не видят. Нужно напечатать с другого компьютера — на первом в окне штрих-кода нажмите «Отпустить принтер» или подождите 5 минут."},{t:"li",s:"«Распечатать» — через окно печати, для принтера на кабеле с драйвером производителя: в окне выбрать «Этикетки CT221B», размер 40 × 60, масштаб 100, поля «Нет». CRM запоминает, как печатали на этом компьютере: значок принтера у номера в карточке печатает тем же способом."},{t:"li",s:"Нет ни Bluetooth в браузере, ни кабеля — как раньше: отсканировать код с экрана приложением принтера на телефоне."},{t:"li",s:"С iPhone и iPad печати по Bluetooth нет — Safari её не умеет; окно само пишет об этом вместо кнопки. Печатайте с компьютера или телефона на Android, либо откройте наклейку в приложении принтера."},{t:"h",s:"Принтер этикеток: настройка (один раз на компьютер)"},{t:"p",s:"На самом компьютере для печати по Bluetooth ничего ставить и настраивать не нужно: ни драйвера, ни связывания принтера в настройках Bluetooth — принтер находит Chrome по кнопке в CRM. Подходит любой компьютер или ноутбук с Windows или Mac — в Google Chrome или Microsoft Edge, с включённым Bluetooth (у настольного компьютера без Bluetooth — USB-адаптер Bluetooth); Android-телефон или планшет с Chrome тоже должен подойти. Не подходят iPhone и iPad: там Bluetooth браузерам недоступен, и Safari и Firefox на компьютере — в них этой кнопки нет."},{t:"warn",s:"Не связывайте принтер в настройках Bluetooth компьютера («Добавить устройство» в Windows, «Подключить» в настройках Mac): компьютер начинает держать его как обычное устройство и не пускает к нему Chrome. Уже связан — удалите его там («Удалить устройство» / «Забыть это устройство»), выключите и включите принтер."},{t:"step",s:"На телефоне, где стоит приложение принтера, выключите Bluetooth: пока принтер занят телефоном, компьютер до него не достучится."},{t:"step",s:"Включите принтер и подождите 10 секунд, пока он «примеряется» к рулону. Наклейка, отправленная сразу после включения, выходит пустой."},{t:"step",s:"Измерьте стикер линейкой и поставьте его размер в «Настройки → Бельё и прачечная → Этикетка белья» (ширина × высота). У рулона принтера CT221B — 40 × 58, а не 40 × 60: при 40 × 60 справа обрезаются конец текста и конец штрих-кода."},{t:"step",s:"Откройте CRM в Google Chrome или Microsoft Edge → нажмите на номер штрих-кода жильца → «Печать по Bluetooth» → в окошке Chrome выберите принтер CT221B-… → «Подключить». На Mac в первый раз ещё спросят, разрешить ли Chrome доступ к Bluetooth, — «Разрешить». Дальше окошко не появляется, а значок принтера у номера в карточке печатает сразу."},{t:"step",s:"Отсканируйте свежую наклейку сканером прачечной — должен найтись этот жилец."},{t:"tip",s:"Узкая бледная полоса точек у одного края наклейки — особенность этого принтера: на текст и штрих-код она не влияет, сканер наклейку читает."},{t:"tip",s:"В окне печати есть выбор «Печать по Bluetooth»: «Как раньше (картинкой)» (стоит сам) или «Быстрый (проба)». Если при «Быстром» на наклейке нет штрих-кода — верните «Как раньше (картинкой)»: на принтере CT221B быстрый способ штрих-код не печатает. Наклейка выходит не целиком — выберите «Как раньше (картинкой)» и рядом «Темп: средний», не помогло — «ровный»: принтер не успевает за быстрой передачей. Если на наклейке проступила прошлая — способ «Как раньше»."},{t:"warn",s:"Напечаталась только левая часть наклейки, справа пусто — это не размер в настройках (лишние 2 мм срезают 2 мм): принтер сбился с края рулона. Выключите принтер, проверьте, что рулон стоит ровно, включите и подождите 10 секунд, напечатайте снова. Повторяется — сообщите нам, где после печати остановилась бумага."},{t:"warn",s:"«Распечатать» не печатает, хотя раньше печатало, — очистите очередь печати Windows (Параметры → Bluetooth и устройства → Принтеры и сканеры → «Этикетки CT221B» → «Открыть очередь печати» → «Отменить все»), выключите и включите принтер, подождите 10 секунд и нажмите ещё раз. Вышла чужая или пустая наклейка — выключите и включите принтер, подождите 10 секунд и напечатайте снова. «Принтер не отвечает» — проверьте телефон и не печатает ли в эту секунду другой компьютер: принтер слушает одного, второй печатает через несколько секунд."},{t:"note",s:"На этикетке только фамилия и имя: без отчества и без паспортных данных. Она лежит на комплекте в общей комнате, и большего для того, чтобы различить соседей, не нужно."},{t:"warn",s:"Кнопка ⟳ у человека, у которого номер уже есть, меняет его наклейку: старая перестанет работать в прачечной. CRM спросит «Сменить номер и распечатать новую?» и сразу откроет печать — наклейте новую на бельё. В правке карточки номер сменится, когда нажмёте «Сохранить». Без нужды номер не меняйте: наклейка потерялась — просто распечатайте её заново, номер тот же."},{t:"warn",s:"Штрих-код лучше не вписывать вручную. Форма проверяет формат (13 цифр с верной контрольной суммой), но если очень нужно ввести свой номер — используйте кнопку ⟳ рядом с полем и убедитесь, что подсказка под полем не красная. Неверный код на печати выглядит обычной наклейкой, но сканер прачечной его не прочитает."},{t:"h",s:"Пропуск на турникет"},{t:"p",s:"Фотография — часть пропуска: без неё пропуск не оформить."},{t:"warn",s:"Нет фото — пропуск не оформится, и турникет человека не пропустит."}]},{key:"quota",title:"Квоты мест: два режима",lead:"Места фирмы можно вести двумя способами. Режим выбирается на объекте — под то, как реально живёт хостел.",blocks:[{t:"note",s:"«Квота» — сколько мест выделено фирме. Разница между режимами — как считаются свободные места."},{t:"h",s:"Режим «плавающие места»"},{t:"li",s:"Пустое место — ничьё, не закреплено за фирмой."},{t:"li",s:"Свободно у фирмы = квота объекта − факт (52 − 44 = 8)."},{t:"li",s:"Комнаты сборные — разные фирмы вместе; при заселении подсказка «доселить к своим» (★)."},{t:"h",s:"Режим «закреплённые комнаты»"},{t:"li",s:"Комнаты закреплены за фирмой; свободные места видны как слоты в этих комнатах."},{t:"li",s:"Каждая фирма живёт своим блоком — порядок и предсказуемость."},{t:"h",s:"Выбор и превышение"},{t:"p",s:"Режим включается на объекте (по умолчанию — закреплённые комнаты). При заселении сверх квоты система предупредит: «Превышена квота фирмы X: проживает N из M»."},{t:"tip",s:"Квота задаётся в карточке фирмы отдельно на каждый объект — изменение на одном не влияет на другой."}]},{key:"evict",title:"Выселить и вернуть",lead:"Человек уехал — его убирают из комнаты, место освобождается. Если вернулся, заводить заново НЕ нужно.",blocks:[{t:"h",s:"Выселить одного"},{t:"step",s:"Откройте карточку жильца и нажмите «Выселить» внизу справа."},{t:"step",s:"Укажите дату отъезда. Место в комнате освободится сразу."},{t:"h",s:"Выселить нескольких"},{t:"step",s:"Галочки в списке → внизу появится полоса «Выбрано N чел.» → «Выселить»."},{t:"h",s:"Если человек вернулся"},{t:"step",s:"Раздел «Уехавшие» → найдите его → «Вернуть»."},{t:"step",s:"Форма откроется с данными человека — проверьте документы, впишите «Регистрация до» и сохраните. Дальше всё как после заселения: скачается файл для Контура, а если подписанного согласия у человека нет — откроется окно «Заселён» с пакетом на подпись: распечатайте, дайте подписать, отметьте «Подписал(а) сразу». Отметка «Подал на патент» переносится из карточки, только если подача была после въезда по его нынешней миграционной карте; старую не переносим — на патент подают заново после каждого въезда."},{t:"img",src:"/help/evicted.png",caption:"Раздел «Уехавшие»: архив выселенных (таблица прокручена вправо — там кнопки).",pins:[{n:1,x:89.5,y:50,label:"Здесь лежат все, кто уезжал. В строке справа — «Вернуть». Выше, отдельной полосой, — «На границе»: те, кто уехал за новой миграционной картой и ещё вернётся («Вернулся»)."}]},{t:"warn",s:"Не заводите вернувшегося заново — получится дубль: долг останется на старой карточке, согласия и фото придётся делать снова, история проходов разорвётся. С 18.09.2026 система сама это не даст: при совпавшем паспорте форма заселения предложит «Вернуть», а второй карточки не заведёт."},{t:"tip",s:"При возврате сохраняются штрих-код, история проходов, история белья и все документы — человек продолжает с того же места. Номер штрих-кода остаётся прежним при любом возврате — из «Уехавших» и через окно «Этот человек уже есть» → «Вернуть»: у человека на руках его старая наклейка, и прачечная узнаёт его по ней. Новый номер CRM выдаёт сама, только если прежний за это время достался другому жильцу, — тогда в истории карточки будет «распечатайте наклейку»."},{t:"note",s:"Выселение снимает человека с миграционного учёта не само по себе. Снятие с учёта — отдельное действие, см. раздел «Миграционный учёт и ФМС»."}]}]},{key:"rooms",label:"Комнаты и места",articles:[{key:"room-create",title:"Создать комнату",lead:"Комнату заводят один раз — дальше в неё заселяют людей. Ошибка здесь тянется дальше: от количества мест зависит, пустит ли система следующего жильца.",blocks:[{t:"step",s:"Раздел «Жильцы» → кнопка «Комната» вверху справа."},{t:"img",src:"/help/room-create.png",caption:"Форма новой комнаты.",pins:[{n:1,x:35.2,y:24.4,label:"Номер комнаты — как он написан на двери. По нему её будут искать."},{n:2,x:64.7,y:24.4,label:"Этаж. По нему работает фильтр этажей в списке и обход по этажам."},{n:3,x:35.2,y:32.3,label:"Количество мест — сколько человек помещается. Когда мест не останется, система предупредит при заселении."},{n:4,x:64.7,y:32.3,label:"Юр.лицо (ЭЦП) — от чьего имени этих жильцов ставят на миграционный учёт. Одна комната = одно юр.лицо."},{n:5,x:50,y:40.1,label:"Закреплена за фирмой — если места в комнате оплачивает конкретная фирма."},{n:6,x:73,y:82.3,label:"«Сохранить» — комната появится в списке сразу, заселять можно тут же."}]},{t:"warn",s:"Юр.лицо выбирайте внимательно: именно от него уходит уведомление в Контур.ФМС. Поставите не то — уведомление уйдёт не от того лица, а это уже разбирательство с проверяющими."},{t:"tip",s:"У комнаты есть «Назначение»: жилая, для персонала, подсобка. Комнату персонала фирмам не продают и обходчик в неё не заходит, но в тариф подписки её места входят; подсобка — без людей вовсе."},{t:"tip",s:"Жилец оказался сотрудником и живёт в комнате один (или с такими же сотрудниками)? Откройте комнату, поставьте назначение «Для персонала» и сохраните — CRM спросит «перевести живущих в сотрудники?». После подтверждения они станут сотрудниками вместе с комнатой, номер пропуска поменяется сам. Если там живут и обычные жильцы — сначала переселите их."},{t:"note",s:"Количество мест можно поменять позже — откройте комнату и измените. Люди, которые уже живут, никуда не денутся."}]},{key:"relocate",title:"Переселить жильца",lead:"Переезд из комнаты в комнату. Двумя способами: одного человека — через его карточку, сразу нескольких — галочками в списке.",blocks:[{t:"h",s:"Одного человека"},{t:"step",s:"Откройте карточку жильца — нажмите на его ФИО в списке."},{t:"step",s:"Под комнатой и этажом найдите блок «Переселение жильца»: выберите новую комнату и нажмите галочку справа."},{t:"img",src:"/help/resident-card.png",caption:"Карточка жильца. Все действия над человеком — отсюда.",pins:[{n:1,x:91.6,y:21.9,label:"Светофор регистрации: «В порядке» зелёным, жёлтым — скоро истекает, красным — просрочено."},{n:2,x:72.2,y:32.2,label:"Комната и этаж."},{n:3,x:72.2,y:48.3,label:"«Переселение жильца» — выберите новую комнату и нажмите галочку: человек переедет. Охране этого блока нет."},{n:4,x:80.2,y:77.4,label:"«Переотправить на турникет» — если человек не проходит, а по документам всё в порядке."},{n:5,x:71.2,y:96.7,label:"«Заблокировать» — закрывает пропуск. Человек остаётся жильцом, но турникет его не пустит."},{n:6,x:89.9,y:96.7,label:"«Выселить» — человек уезжает совсем и попадает в раздел «Уехавшие»."}]},{t:"note",s:"Карандаш в шапке карточки открывает окно «Редактирование» — там правятся данные жильца (документы, фирма, комната и др.), для переезда по комнатам удобнее блок «Переселение»."},{t:"h",s:"Сразу нескольких"},{t:"step",s:"В списке жильцов поставьте галочки слева у нужных строк."},{t:"step",s:"Внизу экрана появится полоса «Выбрано N чел.» с кнопками «Штраф», «Заблокировать», «Переселить» и другими; красная «Выселить» — справа, за чертой; «Снять блок» — когда среди отмеченных есть заблокированные."},{t:"step",s:"Нажмите «Переселить» и выберите комнату — переедут все отмеченные."},{t:"tip",s:"Так удобно переселять бригаду целиком: отметили комнату, переселили одним действием."},{t:"warn",s:"Если в новой комнате не хватает мест, система спросит подтверждение — но переселить всё равно даст. Это осознанно: ночью человека надо разместить, а разбираться с перегрузом можно утром."},{t:"note",s:"Переезд между комнатами с РАЗНЫМИ юр.лицами меняет, от кого человек стоит на учёте. Система предупредит: такой переезд обычно требует нового уведомления в Контур."}]}]},{key:"fms",label:"Миграционный учёт и ФМС",articles:[{key:"kontur-send",title:"Отправка в Контур.ФМС",lead:"Постановка иностранца на миграционный учёт: заполнили карточку — сформировали уведомление — отправили под нужным юр.лицом.",blocks:[{t:"img",src:"/help/migration.png",caption:"Миграционный контроль: у кого и когда кончается регистрация.",pins:[{n:1,x:16.6,y:25.1,label:"Сюда заходить каждый день. Цифра у пункта меню — столько людей уже требуют действия."},{n:2,x:28.3,y:13.4,label:"Вкладки сверху — каждая про своё: «Сегодня» (срок истекает сегодня), «Просрочка», «Патент / РНР», «Согласия», «Не подать» (кого МВД не примет), «Сверка с Контуром» и другие."}]},{t:"step",s:"Проверьте паспорт, миграционную карту и срок регистрации."},{t:"step",s:"Сформируйте уведомление (CSV) и отправьте в Контур под нужным юр.лицом (ЭЦП)."},{t:"step",s:"Статус учёта отобразится в «Миграционном контроле»."},{t:"note",s:"Юр.лицо обычно берётся из комнаты жильца. За просрочкой система следит по дате окончания регистрации."},{t:"tip",s:"Чтобы убедиться, что человек реально встал на учёт — используйте автосверку ЭЦП."}]},{key:"ecp",title:"Автосверка ЭЦП с Контуром",lead:"Система сама постоянно сверяется с Контур.ФМС и показывает, кто реально на учёте, а где расхождение. Это защита от штрафов.",blocks:[{t:"note",s:"Ошибка в учёте иностранца — штраф до 500 000 ₽ за человека (ст. 322.3 УК, ст. 18.9 КоАП). Ручная сверка ненадёжна."},{t:"h",s:"Как работает"},{t:"li",s:"Регулярная сверка: CRM сравнивает, кто отправлен на учёт, а кто нет."},{t:"li",s:"Расхождения подсвечиваются: заведён в CRM, но не в ФМС — или наоборот."},{t:"li",s:"Всегда виден актуальный статус — есть чем подтвердить, что человек оформлен."},{t:"mock",id:"ecp",pins:[{n:1,label:"Строка расхождения: заведён в CRM, но не найден в Контуре."},{n:2,label:"Отметьте «обработано», когда разобрались со случаем."}]},{t:"h",s:"При расхождении"},{t:"step",s:"Откройте карточку с пометкой расхождения."},{t:"step",s:"Отправьте/переотправьте уведомление в Контур либо снимите с учёта."}]},{key:"backfill",title:"Дозаполнение из Контура",lead:"Если у жильцов не хватает данных — их можно подтянуть из уже отправленных уведомлений Контура.",blocks:[{t:"step",s:"В миграционном контроле нажмите «Дозаполнить из Контура»."},{t:"step",s:"Система найдёт людей в отправленных уведомлениях и заполнит пустые поля, приложит сканы."},{t:"note",s:"Заполняются только пустые поля — введённое вами не перезаписывается, даты регистрации не меняются."},{t:"warn",s:"Дозаполнить можно только тех, кто реально есть в отправленных уведомлениях привязанных кабинетов."}]},{key:"epgu",title:"Подача через Госуслуги",lead:"CRM сама подаёт уведомление о прибытии и убытии в МВД через Госуслуги — без Контура. Включается директором по шагам: сначала граждане РФ, потом иностранцы.",blocks:[{t:"note",s:"Пока портал не подключён (ждём описаний услуг от Минцифры), всё работает как раньше. Ключи сотрудников можно внести заранее."},{t:"step",s:"Директор: «Настройки» → объект → «Миграционный учёт» → «Подача через Госуслуги» → «Добавить ключ сотрудника» (сотрудник, юр. лицо, ФИО как на Госуслугах, API-Key, дата выпуска)."},{t:"step",s:"Для иностранцев — там же «Данные для МВД»: дата рождения, паспорт, адрес регистрации (кадастровый номер или код ФИАС), телефон и почта сотрудника. Только с его письменного согласия: галочка «согласие получено» и где лежит бумага; CRM запоминает, кто и когда это отметил. Хранятся зашифрованными, на экран не возвращаются — при правке вносятся заново; в журнал действий попадает только, какие поля изменены, без значений. «Стереть данные» — сотрудник отозвал согласие или уволился."},{t:"step",s:"«Заселить» и «Выселить» как обычно: уведомление встаёт в очередь и через минуту собирается. К уведомлению на иностранца прикладывается последний скан паспорта из карточки (jpg, png, tiff или pdf) — без скана оно «не подаётся»: загрузите скан в карточке жильца → «Документы». Скан уходит только в заявление, и это пишется в журнал действий."},{t:"step",s:"Каждое заявление подписывает тот, кто заселял, — сразу: окно «Заселён» → «Отправить в МВД (Госуслуги)» → проверьте сертификат → «Отправить». После выселения окно открывается само. Подписываются все ваши ждущие заявления разом, этим же нажатием — вход на Госуслуги. Позже — «Миграционный контроль» → «Госуслуги» → «Подписать и отправить (N)», то же окно."},{t:"step",s:"Ответ МВД — в карточке жильца и на вкладке «Госуслуги»: «принято» или «отказ» с причиной."},{t:"step",s:"После «принято» отдайте жильцу его документ: карточка → «Документы» → блок «Госуслуги: прибытие» → «Распечатать отрывную часть» (иностранцу) или «Распечатать анкету» (гражданину РФ). Госуслуги своего листка не выдают, а при проверке жильцу нужно что-то показать. До «принято» кнопка серая и под ней сказано почему."},{t:"note",s:"Отрывную часть иностранцу и анкету печатать на обе стороны листа; на обороте отрывной части — печать хостела."},{t:"note",s:"Листок печатается по данным на момент первой печати: правка карточки после этого его не меняет. Номер, владелец и срок сертификата на отрывной части берутся из вашей подписи заявления. Место жительства в анкете CRM не хранит — впишите от руки. Каждая печать записывается в журнал действий."},{t:"note",s:"От одного сотрудника Госуслуги принимают не больше 20 заявлений за 10 минут. Остальные ждут и уходят сами — на вкладке видно, во сколько. Это не отказ."},{t:"warn",s:"«Отказ» или «не подаётся» — красным: уведомление не подано, это штраф по ст. 18.9 КоАП. Исправьте карточку и нажмите «Подать снова»."},{t:"note",s:"Закрытый ключ подписи с вашего компьютера не уходит: CRM получает только подписанный им API-Key. Ключ Госуслуг целиком на экране не показывается — только 4 последних знака."}]},{key:"deregister",title:"Снятие с учёта",lead:"Когда человек съезжает — его нужно снять с миграционного учёта. CRM сама уведомление никуда не подаёт: она напоминает, помогает подготовить и записывает.",blocks:[{t:"step",s:"Выселите жильца из карточки. Он попадает в «Уехавшие», и там у него появляется надпись «Не снят с учёта · подать до 12:00 завтра». У гостиницы срок убытия — до 12:00 дня, следующего за выездом, и выходные его не сдвигают: выехал в пятницу — снять до субботы 12:00. Утром последнего дня надпись красная «подать до 12:00 сегодня», после полудня — «срок вышел»."},{t:"warn",s:"Снимайте в день выезда, не дожидаясь утра: в выходные срок тот же, а опоздание — штраф по ст. 18.9 КоАП. Если объект настроен как обычная принимающая сторона (срок подачи 7 дней), убытие считается рабочими днями, как прибытие."},{t:"step",s:"Иностранца снимите в своей программе подачи. В Контуре: поиск → галочка → «Отправить уведомления» → подписант → «Продолжить». Затем в «Уехавших» нажмите «Отметить снятым» и укажите дату. На бумажном объекте — «Бланк убытия», отнесли → «Подано в МВД», отметка вернулась → «Снят с учёта»."},{t:"step",s:"Гражданина РФ Контур снять как иностранца не даёт — регистрация сокращается до завтра: «Файл для Контура» готовит уведомление о постановке со сроком до завтрашнего дня (выбрали нескольких — один файл на всех). Загрузите его в Контур сегодня. В CRM сразу стоит «подано», завтра само станет «снят», окончание регистрации в карточке — завтрашним числом."},{t:"warn",s:"Снятие не формируется — окно покажет, чего не хватает. Если в карточке гражданина РФ чего-то нет (чаще всего «Кем выдан паспорт»: нужен код подразделения или орган выдачи — достаточно одного из двух), окно «Снятие с учёта» не закрывается и списком по каждому человеку пишет «Не хватает для Контура: …», а кнопка «Скачать файл и отметить» неактивна. Нажмите «Открыть карточку», впишите недостающее (код подразделения — в паспорте на развороте с фото), закройте карточку — окно проверит заново само, без перезагрузки. Пока не хватает хотя бы одного поля, файл не скачивается и «подано» не ставится."},{t:"note",s:"Выселение одновременно освобождает место, закрывает эпизод проживания и снимает доступ на турникете."},{t:"note",s:"Кого снимать: всех иностранцев, включая граждан Беларуси, — и на бумажном объекте тоже тех, чьё прибытие в CRM не отмечено (например, ставили на учёт до CRM): утреннее письмо и «Уехавшие» напоминают одинаково. Не напоминаем только о тех, у кого в карточке отмечено «Не на учёте» (серая галочка, подпись «Снят с учёта, место держится») — это человек, которого вы уже сняли с учёта, а место за ним держите (уехал в командировку): он не на учёте и не в «Уехавших». Галочку ставят, когда снятие уже подано; сама она в МВД ничего не подаёт. Снятие уехавших отмечают здесь, в «Уехавших». Полоса «Не сняты с учёта — N чел.» над списком собирает тех, по кому убытие ещё не подано; каждая отметка — с датой, вашим именем и записью в журнале действий. Снятый виден зелёной плашкой «Снят» в колонке действий (у гражданина РФ до завтра — синяя «Подано»); нажатие на плашку отменяет отметку (только если поставлена ошибочно) — запись остаётся в истории."},{t:"note",s:"Срок учёта вышел сам, а убытие не подавали — строка серая: «Срок учёта вышел · уведомление не подавалось». Подавать уже нечего, но факт не прячется. Вернулся и уехал снова — нужна новая отметка: старая относится к прошлому заезду."}]}]},{key:"skud",label:"Проходы и СКУД",articles:[{key:"skud-face",title:"Как жилец попадает на турникет",lead:"Пропуск на турникет заводится автоматически из CRM. На самом терминале вручную никто ничего не заводит.",blocks:[{t:"p",s:"Основа пропуска — фотография жильца в карточке. Её делают после заселения: карточка жильца → «Сделать фото на пропуск» (обычно это охрана, где охраны нет — администратор). Как только фото сохранено, CRM сама отправляет пропуск на все терминалы объекта — обычно он доезжает за минуту."},{t:"warn",s:"Нет фото — нет прохода: без фотографии пропуск не оформить."},{t:"note",s:"Блокировка не стирает пропуск, а закрывает его: фото остаётся на терминале. Поэтому разблокировка срабатывает сразу, и переснимать человека не нужно."},{t:"tip",s:"Человек не проходит, а по документам всё в порядке — в карточке жильца «Переотправить на турникет». Не помогло — «СКУД → Здоровье СКУД»: там видно, какая команда терминалу не прошла и почему."},{t:"tip",s:"Объект только запускается или терминал заменили — «СКУД → Оборудование и настройка» → «Загрузить всех жильцов»: CRM отправит на терминалы всех, кто должен там быть."},{t:"note",s:"Так работают терминалы Hikvision — они стоят на новых объектах. Если у объекта турникеты ZKTeco, пропуск передаёт программа ZKBio на компьютере охраны, а массовая загрузка называется «Загрузить всех жильцов в ZKBio»."}]},{key:"skud-health",title:"Здоровье СКУД — с чего начать, если турникет ведёт себя не так",lead:"Экран «СКУД → Здоровье СКУД» отвечает одной строкой: «Турникеты в порядке» или «Проблем: N». Открывают его первым, до звонка в поддержку.",blocks:[{t:"li",s:"Ниже — проверки: связь с терминалами, очередь команд, кто заведён на турникете, кто не пройдёт, повторяющиеся СКУД ID, ошибки за сутки."},{t:"li",s:"У каждой строки сказано, чем это грозит. Нажмите на строку — откроются порядок действий, список людей и кнопка, которая чинит."},{t:"note",s:"Объект без турникетов (терминалы ещё не смонтировали) экран так и называет: «Терминалы ещё не заведены». Это не поломка: пока терминалов нет, автоблокировка по неактивности людей не трогает. Завели первый терминал — проверки включатся сами."},{t:"li",s:"Внизу кнопка «Все инструменты разбора»: «Очередь Hikvision» (или «Очередь ZKTeco») — какая команда терминалу не прошла и почему; «Отчёт сверки ZKTeco» — поимённо, кого на устройстве быть не должно и кого не хватает; «Дубли СКУД» — один человек заведён на турникете дважды; «Логи терминалов» — тонкий разбор, видит разработчик. В обычный день сюда заходить не нужно."},{t:"note",s:"Вкладку видят администратор и директор."}]},{key:"skud-terminals",title:"Вкладка «Турникеты»: связь и сверка терминалов",lead:"Есть на объектах с Hikvision. Показывает, на связи ли терминалы, и сравнивает их с карточками жильцов.",blocks:[{t:"li",s:"Карточка терминала: «На связи», «Давно молчит» (больше 15 минут без связи) или «Ошибка» с текстом; сторона — вход или выход."},{t:"li",s:"«Сверить сейчас» — CRM спрашивает терминалы и сравнивает с карточками. Результат: «Расхождений: N» или «Расхождений нет»."},{t:"li",s:"«Недостаёт на терминале» — человек живёт, а на терминале его нет: не пройдёт. Кнопка в строке «Исправить» отправит его заново."},{t:"li",s:"«Лишние на терминале» — на терминале есть тот, кого там быть не должно (например, выселен). Кнопка «Убрать с терминала»."},{t:"li",s:"«Неверный статус доступа» — в CRM и на терминале по-разному: заблокирован или нет."},{t:"li",s:"«Полная сверка» — все строки; можно оставить только расхождения."},{t:"li",s:"«Отправить всех на терминал» — при запуске объекта или замене терминала. По умолчанию вместе с допущенными сотрудниками."},{t:"note",s:"Команды доезжают не мгновенно: подождите и нажмите «Сверить сейчас» ещё раз. Не помогло — «СКУД → Здоровье СКУД». У объектов на ZKTeco вкладка отправляет туда же, в «Здоровье СКУД»."}]},{key:"skud-manual",title:"Кто решает о пропуске: автоматический и ручной режимы",lead:"Выбирается в «СКУД → Оборудование и настройка» → «Кто решает о пропуске». Только для терминалов Hikvision.",blocks:[{t:"li",s:"«Автоматический» — турникет открывает проход сам, по пропуску. Так работает большинство объектов."},{t:"li",s:"«Ручной — пропускает работник» — терминал подсказывает, кто подошёл, а открывает работник на экране охраны. В журнале записано, кто именно пропустил."},{t:"li",s:"«Ручной по списку» — терминал не подсказывает: работник сам находит жильца по этажу, комнате или фамилии и открывает проход. Пропуска с терминалов при этом снимаются отдельной кнопкой «Снять пропуска»."},{t:"warn",s:"В ручном режиме, если CRM недоступна, не пройдёт никто. Включать его можно, только когда у охраны есть механический ключ или кнопка открытия."},{t:"note",s:"Обратно из «Ручного по списку»: сначала «Вернуть пропуска» (это около получаса), потом «Автоматический». В обратном порядке турникет начнёт открывать сам, но пропусков на нём ещё не будет — не пройдёт никто."}]},{key:"passlog",title:"Журнал проходов",lead:"Все входы и выходы через турникеты — в одном журнале.",blocks:[{t:"img",src:"/help/access.png",caption:"Раздел «СКУД»: вкладки сверху переключают журнал, проверку по камере, проживание и терминалы.",pins:[{n:1,x:10.1,y:38.6,label:"Раздел «СКУД» в меню слева."},{n:2,x:42.6,y:13.5,label:"Вкладки: «Журнал событий» — кто и когда прошёл; «Проверить по камере» — не провёл ли жилец постороннего; «Фактическое проживание» — кто зарегистрирован, но не живёт; «Турникеты» — состояние терминалов. У администрации ещё «Оборудование и настройка» и «Здоровье СКУД»."}]},{t:"li",s:"Событие прохода: жилец, время, считыватель Вход или Выход."},{t:"li",s:"Фильтры по дате и человеку."},{t:"li",s:"Основа для «фактического проживания» и «кто внутри»."},{t:"note",s:"Какой терминал «вход», а какой «выход» — задаётся у каждого терминала в «СКУД → Оборудование и настройка» (поле «Сторона»)."}]},{key:"inside",title:"Кто внутри / снаружи",lead:"По последнему проходу система показывает, кто сейчас на объекте.",blocks:[{t:"li",s:"Внутри — последний проход был на вход."},{t:"li",s:"Снаружи — последний проход на выход."},{t:"li",s:"Нет данных — проходов не было или терминал не опознан (это вопрос к настройке СКУД, а не к человеку)."},{t:"tip",s:"Удобно для пересчёта людей и контроля во время обхода."}]}]},{key:"block",label:"Блокировка / разблокировка",articles:[{key:"block",title:"Заблокировать жильца",lead:"Блокировка снимает доступ на турникет мгновенно — одним нажатием.",blocks:[{t:"img",src:"/help/resident-card.png",caption:"Карточка жильца. Все действия над человеком — отсюда.",pins:[{n:1,x:91.6,y:21.9,label:"Светофор регистрации: «В порядке» зелёным, жёлтым — скоро истекает, красным — просрочено."},{n:2,x:72.2,y:32.2,label:"Комната и этаж."},{n:3,x:72.2,y:48.3,label:"«Переселение жильца» — выберите новую комнату и нажмите галочку: человек переедет. Охране этого блока нет."},{n:4,x:80.2,y:77.4,label:"«Переотправить на турникет» — если человек не проходит, а по документам всё в порядке."},{n:5,x:71.2,y:96.7,label:"«Заблокировать» — закрывает пропуск. Человек остаётся жильцом, но турникет его не пустит."},{n:6,x:89.9,y:96.7,label:"«Выселить» — человек уезжает совсем и попадает в раздел «Уехавшие»."}]},{t:"warn",s:"Блокировка и выселение — разные вещи. Заблокированный продолжает числиться жильцом и занимать место, ему по-прежнему меняют бельё. Выселенный освобождает место; с миграционного учёта его снимают отдельно — выселение само по себе этого не делает."},{t:"img",src:"/help/blocks.png",caption:"Раздел «Заблокированные»: у кого закрыт пропуск и по какой причине.",pins:[{n:1,x:17.3,y:30.3,label:"Раздел в меню. Цифра — сколько человек сейчас заблокировано."},{n:2,x:42.4,y:13.4,label:"Вкладка «Нарушения» — штрафы и нарушения режима (открытые и история)."},{n:3,x:90.2,y:50.8,label:"В колонке причины видно, кто закрыл пропуск: «Автоблок» (система сама — например, нет проходов 48 часов) или «Вручную» (человек, причина записана)."}]},{t:"step",s:"Откройте карточку жильца → «Заблокировать», укажите причину."},{t:"p",s:"Доступ на турникете снимается сразу; в карточке видны статус и причина."},{t:"note",s:"Блокировка — временное ограничение доступа, а не выселение. Место и история сохраняются."}]},{key:"unblock",title:"Снять блокировку",lead:"Разблокировка возвращает доступ так же мгновенно.",blocks:[{t:"step",s:"В карточке жильца нажмите «Разблокировать»."},{t:"p",s:"Доступ восстанавливается моментально, пропуск снова активен."},{t:"tip",s:"После разблокировки система сама пересинхронизирует жильца на турникет."}]}]},{key:"living",label:"Фактическое проживание",articles:[{key:"living",title:"Кто живёт, а кто отмечается",lead:"По проходам через турникет видно, кто реально живёт на объекте, а кто только заходит отметиться. Объективная доказательная база и защита бизнеса.",blocks:[{t:"h",s:"Что видно"},{t:"li",s:"Полное время нахождения на объекте и отсутствия."},{t:"li",s:"По каждой ночи (окно с 16:00 до 16:00 следующего дня, например «ночь 13→14»): «внутри N ч» — столько человек был за турникетом за эти сутки, «ниже нормы», «не заходил» или «нет данных». В шапке — «по норме N из M ночей»."},{t:"li",s:"«Внутри 5 ч, с 22:00 до 08:00 — нет» — норму набрал, но не ночью (например, был с 16:00 до 21:00 и ушёл). «Внутри 24 ч · не выходил» — сутки целиком внутри: болел или выходной."},{t:"li",s:"«Выход не отмечен с 9 окт. 14:54» (серым) — человек вошёл, и прохода нет больше 36 часов: он может лежать в комнате, а может уйти за кем-то в спину. Это не обвинение и в норму не идёт. Как только он пройдёт турникет, CRM сама допишет эти ночи: вышел — «был», снова вошёл — «нет данных»."},{t:"li",s:"Кто давно не проходил («нет проходов»)."},{t:"h",s:"Как считается"},{t:"li",s:"Ночь засчитывается, если за неё (с 16:00 до 16:00) человек набрал внутри нужные часы (по умолчанию 4) — в любое время и любыми кусками."},{t:"li",s:"Время суток не важно: ночник спит утром и днём, и это такое же проживание. Короткая отлучка (покурить, за хлебом) счёт не разрывает."},{t:"tip",s:"Порог часов настраивается на объекте: «СКУД → Фактическое проживание» → «Нужно часов» (тот же блок — в «Настройки → Проживание»). Там же «Период, дней» — за сколько суток показывать шкалу (можно до 90)."},{t:"note",s:"Серая клетка «нет данных» — это не обвинение: либо молчали турникеты, либо проход пришёл с терминала, который CRM не опознала. Во втором случае чинить надо СКУД: «Оборудование и настройка» → «Проверить связь»."},{t:"note",s:"Зачем: объективные данные защищают от претензий по «фиктивной регистрации» — есть чем подтвердить, что человек живёт."}]},{key:"nopass",title:"«Нет проходов»",lead:"Список тех, кто давно не проходил через турникет — кандидаты на проверку.",blocks:[{t:"li",s:"Отсортировано по числу дней без прохода."},{t:"li",s:"Проверьте: съехал, в отпуске или потерялся из учёта."},{t:"li",s:"По итогу — выселить, снять с учёта или оставить."},{t:"tip",s:"Можно включить автоблокировку тех, у кого нет проходов, — доступ сам ограничится до выяснения."}]}]},{key:"rounds",label:"Обход онлайн",articles:[{key:"rounds",title:"Обход с телефона",lead:"Обход по комнатам ведётся со смартфона в реальном времени — отметки сразу в системе.",blocks:[{t:"mock",id:"rounds-room",caption:"Комната раскрыта: под каждым жильцом — две кнопки, под комнатой — три.",pins:[{n:1,label:"Нажмите на комнату — раскроется список тех, кто в ней живёт по документам."},{n:2,label:"✓ — человек на месте. Нажали второй раз по той же кнопке — отметка снимается."},{n:3,label:"✗ — не нашли. Сразу спросит причину: «не открыли», «на работе», «соседи: уехал». Причину можно пропустить, обход не встанет."},{n:4,label:"«Порядок» — в комнате чисто. «Замечания» — что не так (за грубое нарушение попросит фото). «Лишний» — нашли человека, которого нет в списке."}]},{t:"mock",id:"rounds-pending",caption:"Полоса появляется сама, когда пропала связь.",pins:[{n:1,label:"Столько отметок лежит на телефоне и ещё не ушло на сервер. Отмечать можно дальше — ничего не потеряется."},{n:2,label:"«Отправить» — досылает вручную. Обычно не нужно: как появится связь, уйдут сами за 20 секунд."}]},{t:"warn",s:"Полоса горит — не закрывайте обход. Кнопка «Завершить обход» сама попробует дослать и не даст закончить, пока отметки не ушли: иначе у директора обход будет выглядеть наполовину пустым."},{t:"tip",s:"В мёртвой зоне (лестничный пролёт, дальний конец коридора) связь пропадает на минуту — это нормально. Просто идите дальше и отмечайте."},{t:"step",s:"Откройте раздел «Обход» на телефоне."},{t:"step",s:"Идёте по комнатам и отмечаете, кто на месте — отметки сохраняются онлайн."},{t:"step",s:"Результат сразу виден в CRM и попадает в журнал обходов."},{t:"tip",s:"Компьютер не нужен — весь обход проходит с телефона."}]},{key:"rounds-log",title:"Журнал обходов",lead:"История всех обходов: кто проводил, когда и с какими отметками.",blocks:[{t:"li",s:"Дата и время обхода, кто проводил."},{t:"li",s:"Отметки по комнатам и жильцам."},{t:"note",s:"Журнал — доказательство, что обход действительно проводился."}]}]},{key:"linen",label:"Постельные принадлежности",articles:[{key:"linen",title:"Учёт постельного белья",lead:"Выдача и смена белья ведутся автоматически — видно, кому и когда меняли, без бумажных журналов.",blocks:[{t:"mock",id:"linen-issue",caption:"Выдача по штрих-коду: сканировать быстрее, чем искать в списке.",pins:[{n:1,label:"Наведите камеру телефона на штрих-код жильца — он на его комплекте. Жилец найдётся сам."},{n:2,label:"Система сразу покажет, когда меняли в прошлый раз. Красным — если пора менять."},{n:3,label:"«Записать выдачу» — отметка уходит в историю жильца и снимает счётчик просрочки."}]},{t:"note",s:"Бельё выдаём и заблокированным тоже — санитария важнее наказания. Не выдаём только выселенным."},{t:"li",s:"Выдача белья при заселении."},{t:"li",s:"Смены белья и их даты."},{t:"li",s:"История по каждому жильцу."},{t:"tip",s:"Видно, кому пора менять бельё — удобно для роли «Прачечная»."},{t:"note",s:"Если на объекте бельё выдают без CRM, директор выключает учёт: «Настройки → Бельё и прачечная → Бельё ведётся в CRM». Тогда на этом объекте нет счётчика «без белья», мониторинга прачечной, напоминаний и заданий обхода по белью, а автоблокировка по белью не срабатывает, даже если включена. Вверху экрана «Постельное бельё» написано, что учёт выключен."},{t:"li",s:"«Инвентаризация» (кнопка наверху раздела, рядом со «Списанием») — пересчитали склад руками раз в месяц: впишите, сколько на самом деле лежит простыней, пододеяльников и наволочек. Рядом видно, сколько числится по CRM и какая разница. «Провести» — CRM доведёт остаток до ваших цифр и запишет разницу строкой «Инвентаризация» во вкладке «История склада». Позицию, которую не считали, оставьте пустой. Проводят управленцы."},{t:"note",s:"«Списание» — когда знаете, что именно ушло (порвали, выбросили). «Инвентаризация» — когда просто пересчитали и цифра не сошлась: разницу CRM посчитает сама."}]},{key:"laundry-ledger",title:"Расчёты с прачечной",lead:"Вкладка «Прачечная» — таблица на месяц: строка на каждый день. В строке — сколько грязного отдали в этот день и сколько чистого прачечная привезла ЗА этот день.",blocks:[{t:"li",s:"Таблица заполняется прямо в клетках, как в Excel: нажмите на клетку, впишите число, Enter или Tab — сохранено. Esc — отменить, пустая клетка — очистить. Месяц переключается стрелками, новый открывается сам."},{t:"li",s:"Утром впишите в строку сегодняшнего дня «Отдали грязного, кг» — вес с весов. Когда прачечная привезла чистое за этот день (обычно назавтра), в ту же строку — вес по накладной, наш вес с весов и штуки: простыни, пододеяльники, наволочки."},{t:"li",s:"Штуки сразу приходуются на склад готового белья — второй раз через «Закупку» вводить не надо. Поправили число штук — склад поправится на разницу."},{t:"li",s:"«ждём» в строке — грязное отдали, а чистого за этот день ещё нет. Сумма таких дней и есть «У прачечной сейчас» наверху."},{t:"li",s:"Привезли за один день в два захода — впишите в клетку общую сумму."},{t:"li",s:"Привезли чистое за день, отгрузки которого в CRM нет (увезли до начала учёта или забыли вписать): впишите привоз в строку того дня как обычно. В последней колонке появится оранжевое «нет отгрузки?». Знаете вес отгрузки — впишите его в «Отдали грязного». Не взвешивали — нажмите «нет отгрузки?»: штуки останутся на складе, а в «Чистое − грязное» за месяц привоз не пойдёт, в «Итого» он виден отдельно: «+N кг вне счёта». Ошиблись — нажмите «вне счёта ×», отметка снимется. Вес отгрузки задним числом не придумывайте: на него ссылаются в разговоре с прачечной."},{t:"li",s:"«Мешков» — две колонки: сколько мешков грязного отдали и сколько мешков чистого привезли за этот день. Мешки считают при передаче из рук в руки — расхождение по ним видно сразу, ещё до взвешивания."},{t:"li",s:"«Готовых комплектов» — сколько полных комплектов вернулось, по самой малочисленной позиции (45 простыней, 44 пододеяльника, 47 наволочек — 44 комплекта). В «Итого» — сколько обернулось за месяц."},{t:"li",s:"Кнопка «Excel» над таблицей скачивает месяц файлом — например, приложить к претензии прачечной."},{t:"note",s:"Отдельных кнопок «Отдали в стирку» и «Приехало чистое» больше нет — всё вносится в таблицу. «Грязное на объекте» — сколько раз меняли бельё после последней вписанной отгрузки: машина увозит всё накопленное."},{t:"li",s:"«Цена стирки, ₽ за кг» — поле рядом с кнопками над таблицей (то же поле — в «Настройки → Бельё и прачечная»). Впишите цену из договора и нажмите Enter: недовес начнёт считаться в рублях переплаты. Цену и вес позиций меняет администрация — у охраны и прачечной эти поля только для чтения."},{t:"li",s:"«Недовес» — накладная минус наши весы по тому же чистому белью. Прачечная берёт деньги за вес накладной, поэтому недовес — прямая переплата. Красным — больше порога (по умолчанию 2 %, меняется в «Вес позиций»). Итог за всё время — крупно над таблицей; если старое закрыли с прачечной, в «Вес позиций» поставьте «Считать недовес с» — итог начнётся с этого дня, прошлые месяцы в таблице останутся как были."},{t:"warn",s:"Поймали недовес больше 2 %: пока водитель здесь, впишите в его накладную «принято с расхождением, по весам объекта N кг», пусть распишется, и сфотографируйте весы с бельём. Без подписи их стороны спор превращается в «у вас весы врут». Для спора нужны весы с поверкой."},{t:"note",s:"Стереть отгрузку (очистить клетку «Отдали») может только управленец. Каждая запись и правка попадает в журнал действий."},{t:"tip",s:"Колонка «Чистое − грязное» почти всегда в минусе: грязное бельё тяжелее чистого. Смотрите на недовес — он сравнивает одно и то же сухое бельё."}]}]},{key:"firms",label:"Фирмы и квоты",articles:[{key:"firm",title:"Карточка фирмы",lead:"Фирма — контрагент, который селит у вас работников. В карточке — реквизиты, объекты и квоты мест.",blocks:[{t:"img",src:"/help/companies.png",caption:"Раздел «Фирмы»: контрагенты, которые платят за места.",pins:[{n:1,x:41.8,y:34.3,label:"Значки на карточке фирмы: счёт, «Плательщики», ключ — доступ в кабинет, карандаш — карточка фирмы (реквизиты, оплата на объекте, квота мест), крестик — убрать фирму."}]},{t:"li",s:"Название, ИНН, КПП, контакты — одни на всю сеть: карточка фирмы одна, даже если фирма селит людей на несколько объектов. Заводите фирму, которая уже есть в сети, — CRM предложит «Привязать к нашему объекту» вместо второй карточки."},{t:"li",s:"Оплата на объекте — способ расчёта, цена за место, договор № и дата, почта для счетов — у каждого объекта свои и правятся для объекта, выбранного в шапке. Договор печатается в счёте строкой «Основание»: первый счёт берёт его из карточки, следующие — из предыдущего счёта. Пусто — счёт выйдет без основания; почта для счетов пустая — счёт уйдёт на общую почту фирмы."},{t:"li",s:"Объекты, где работает фирма."},{t:"li",s:"Квота мест на каждом объекте и сколько занято / свободно. Занятыми считаются и заблокированные: место за ними сохраняется, и в счёте фирме они есть. Квота не заведена — так и написано, «не задана»: ноль читался бы как «мест нет»."},{t:"li",s:"Кнопка с ключом — «Доступ в кабинет»: выдать представителю фирмы логин в её личный кабинет, отключить его или выдать новый пароль. Выдаёт директор сети. Фирма увидит только своих людей (ФИО, объект, комната, статус) и свои места — паспортов, сроков регистрации, причин блокировки и чужих фирм в кабинете нет, загрузить она ничего не может. Пароль временный и показывается один раз, при выдаче: в базе он лежит только отпечатком. Рядом с ним кнопка «Отправить на почту фирмы» — письмо уходит на почту из карточки фирмы (впишите её в «Редактировать»), и пароль не пересылается в переписке; при первом входе фирма придумает свой. Логины фирм видны на экране «Сотрудники» отдельной группой «Контрагенты». Если две карточки одной фирмы объединили, логин старой карточки появится здесь отключённым с пометкой «был у карточки «…»» — нажмите «Вернуть доступ», если этим входом снова будут пользоваться. Вход больше не нужен совсем (пробный, прораб сменился) — корзина «Удалить вход»: вход пропадёт из списка и сразу перестанет работать, а логин освободится — его можно выдать заново, этой же или другой фирме. Вернуть удалённый вход нельзя, только выдать новый; история его действий остаётся в журнале. Если вход нужен закрыть на время — не удаляйте, а отключите: тогда его можно вернуть."},{t:"li",s:"Галочка «Пометки жильцов попадают в выгрузку списка в Excel»: включите фирме, которой вы отдаёте список с вашими пометками; по умолчанию выключена — пометка бывает служебной."},{t:"li",s:"Фирма ушла — крестик на карточке. Если у фирмы ещё живут люди или за ней закреплены комнаты, CRM попросит сначала перевести их в другую фирму. Если у фирмы есть история (учёт занятых мест по дням, счета, логин в кабинет), удалить её нельзя — по этим записям сверяются с фирмой и спорят о деньгах. Тогда CRM сразу предложит «Убрать в архив»: фирма пропадёт из списка и из выбора при заселении, записать на неё человека будет нельзя, её кабинет закроется, а счета, долги и история останутся. Архив — кнопка «Архив фирм» внизу страницы, там же «Вернуть», если фирма пришла снова (не заводите её второй раз — история разделится на две карточки)."},{t:"mock",id:"firm-quota",pins:[{n:1,label:"Квота мест — задаётся на каждый объект отдельно."},{n:2,label:"«Свободно» считается автоматически: квота − занято."}]},{t:"tip",s:"Квоты на разных объектах независимы: изменение на одном не тронет другой."}]},{key:"floating",title:"Режим «плавающие места»",lead:"Свободные места фирмы не привязаны к комнатам: свободно = квота объекта − факт. Комнаты сборные.",blocks:[{t:"li",s:"Пустое место — ничьё, не закреплено за фирмой."},{t:"li",s:"Свободно у фирмы = квота объекта − факт (52 − 44 = 8)."},{t:"li",s:"В одной комнате могут жить разные фирмы."},{t:"li",s:"Каждое место можно закрепить за своей фирмой: в списке жильцов двойной клик по фирме в строке «МЕСТО N» — и выбрать её из списка. То же есть в карточке комнаты («Места по фирмам»)."},{t:"li",s:"Место без фирмы остаётся ничьим — так и должно быть, пока не решили, чьё оно."},{t:"li",s:"Свободные места фирмы в комнате = закреплено за ней − её жильцы, живущие в этой комнате."},{t:"li",s:"Фирму жильца закрепление места не меняет — её ставят в карточке человека."},{t:"li",s:"При заселении наверх всплывают комнаты, где уже живёт фирма (★)."},{t:"note",s:"Подходит объектам, где состав постоянно меняется. Включается на объекте в настройках («Настройки» → «Места фирм»); включение снимает закрепление комнат за фирмами."}]},{key:"protected",title:"Режим «закреплённые комнаты»",lead:"Классический режим: комнаты закреплены за фирмой, свободные места видны как слоты в этих комнатах.",blocks:[{t:"li",s:"За фирмой закрепляются комнаты."},{t:"li",s:"Свободные места — пустые слоты в её комнатах."},{t:"li",s:"Кабинет фирмы видит именно свои комнаты и места."},{t:"note",s:"Режим по умолчанию. Подходит, когда фирмы живут отдельными блоками."},{t:"tip",s:"Если комнаты стали сборными — переключите объект на «плавающие места»."}]}]},{key:"settings",label:"Настройки объекта и сети",articles:[{key:"set-privacy",title:"Персональные данные: политика и реквизиты оператора",lead:"Директор: «Настройки» → «Сеть» → «Персональные данные». Обязательная настройка перед началом работы.",blocks:[{t:"p",s:"Закон требует, чтобы политика обработки персональных данных была опубликована для любого посетителя. Она открывается без входа по адресу /privacy вашей CRM, на неё ссылаются все формы, где человек оставляет данные."},{t:"li",s:"Вверху — реквизиты оператора: наименование организации, адрес, почта и телефон для обращений, ответственный за обработку данных."},{t:"li",s:"Ниже — текст политики и номер текущей редакции. «Сохранить и опубликовать» заводит новую редакцию: заявки запоминают, с какой именно человек согласился."},{t:"li",s:"«Посмотреть, как видит посетитель» открывает публичную страницу."},{t:"warn",s:"Пока вы не сохранили свой текст, опубликована наша заготовка. Экран об этом пишет. Заготовку показывают юристу: утверждает текст ваш юрист, отвечаете за него вы как оператор."},{t:"warn",s:"Незаполненные места вида {{OPERATOR_INN}} видны посетителям, пока реквизиты не заполнены и не сохранены."}]},{key:"set-subscription",title:"Подписка и плашка «Работа приостановлена»",lead:"Директор: «Настройки» → «Сеть» → «Подписка» (все объекты) и «Настройки» → «Объект» → «Подписка объекта» (один).",blocks:[{t:"li",s:"Сводка: «Объектов», «Подключено», «Бесплатно», «Скоро продление», «Просрочено», «Приостановлено», «Плата в месяц», ниже — «Подписки по объектам»."},{t:"li",s:"Объект: тариф, стоимость, вместимость, «Оплачено по», история оплат и изменений."},{t:"li",s:"«Активна» — всё работает. «Скоро продление» — период кончается, пора платить. «Просрочена» — срок оплаты прошёл, работа не останавливается. «Приостановлена» — сотрудники не могут сохранять изменения. «Не подключён» — объект заведён, к подписке не привязан, работе не мешает."},{t:"note",s:"Подключает, принимает оплату и приостанавливает поставщик blaqit.CRM. У вас на экране состояние и история; чтобы что-то изменить, свяжитесь с поставщиком."},{t:"tip",s:"При просрочке и приостановке у сотрудников сверху появляется цветная плашка: при приостановке «Изменения сейчас не сохраняются. Данные на месте, турникеты работают как обычно». Увидели её — не жмите «Сохранить» снова и снова, а сообщите директору."}]},{key:"set-backups",title:"Резервные копии",lead:"Директор: «Настройки» → «Сеть» → «Резервные копии». Копии базы делаются сами каждую ночь.",blocks:[{t:"li",s:"«Создать копию сейчас» — когда нужна свежая перед важной работой. Готовая копия выгружается в хранилище."},{t:"li",s:"Восстановление идёт через поддержку blaqit: оно возвращает карточки всех жильцов к моменту копии и отменяет то, что администраторы сделали после."},{t:"li",s:"Восстановление меняет только карточки жильцов (ФИО, комната, статус, документы). Комнаты, фирмы, юр. лица, настройки и фотографии не трогает; проходы, нарушения и выдачи белья не возвращает."},{t:"warn",s:"Пропали или испортились данные — сразу пишите нам и ничего не правьте руками: чем меньше изменений после копии, тем меньше потеряется."}]},{key:"set-appearance",title:"Оформление сети",lead:"Директор: «Настройки» → «Сеть» → «Оформление».",blocks:[{t:"li",s:"Акцентный цвет — кнопки, активное меню, выделения у всех сотрудников. Изменения видны сразу, «Применить оформление» сохраняет."},{t:"li",s:"Название сети (показывается во вкладке браузера), ссылки на сайт и Телеграм (показываются на публичной форме заявки)."},{t:"li",s:"Ссылка на публичную форму заявки — её можно вставить на сайт и в Телеграм; кнопка «Копировать»."},{t:"li",s:"Внизу «Версия сервера»: когда CRM обновляли в последний раз — удобно, если спрашивают «обновилось или нет»."},{t:"note",s:"Логотип меняется на сервере файлом и от вас не требуется — обратитесь к поддержке."}]},{key:"set-consents",title:"Документы на подпись: тексты согласий",lead:"Директор и администратор: «Настройки» → «Объект» → «Документы на подпись».",blocks:[{t:"li",s:"Четыре документа пакета: «Согласие на ПД», «Проход по пропуску», «Правила проживания», «Пожарный инструктаж»."},{t:"li",s:"«Согласие на ПД» нужно всегда: без него нельзя ни заселять, ни подавать в МВД. «Правила проживания» и «Пожарный инструктаж» замените правилами своего объекта."},{t:"li",s:"«Проход по пропуску» — человек разрешает использовать свою фотографию для пропуска. Если объект фото в пропуске не использует, документ выключается."},{t:"li",s:"Можно вернуть заготовку; уже подписанные листы от правки текста не меняются."},{t:"warn",s:"Тексты согласий утверждает юрист клиента, мы их не сочиняем."}]},{key:"set-other",title:"Остальные разделы настроек объекта",lead:"Директор и администратор: «Настройки» → «Объект» (выберите объект в шапке).",blocks:[{t:"li",s:"Профиль — адрес, телефон и почта объекта. Сверху «Готовность объекта»: CRM сама проверяет профиль, комнаты, юр. лицо, турникеты и миграционный учёт."},{t:"li",s:"Комнаты и юр. лица — какое юр. лицо (ЭЦП) у каких комнат."},{t:"li",s:"Миграционный учёт — режим объекта (Контур, бумажные бланки, Госуслуги): от него зависит, какие вкладки есть в «Миграционном контроле»."},{t:"li",s:"Турникеты и Проживание — те же экраны, что в «СКУД» («Оборудование и настройка», пороги проживания)."},{t:"li",s:"Бельё и прачечная — этикетка белья и цена стирки с весами."},{t:"li",s:"Блокировки — правила, по которым CRM сама закрывает пропуск."},{t:"li",s:"Уведомления — таблица «кому приходит тревога у турникета» (незнакомый, выселенный, заблокированный у турникета, открыл турникет 3 раза и больше): отметьте роли — охрана, администратор, директор."},{t:"li",s:"Места фирм — переключатель «плавающие места» (статья «Режим плавающие места»)."},{t:"li",s:"Мой профиль — свой пароль, тема, автовыход. Есть у каждой роли."}]},{key:"set-kontur",title:"Доступы Контур",lead:"Чтобы отправлять уведомления и сверяться с ФМС, у объекта должны быть доступы к Контур.ФМС.",blocks:[{t:"step",s:"«Настройки» → «Объект» → «Контур.ФМС»: логин и пароль кабинета."},{t:"step",s:"Можно добавить несколько кабинетов/юр.лиц — отправка пойдёт под нужным."},{t:"warn",s:"Название кабинета пишите точно как название юр. лица в CRM (кавычки и большие буквы не важны): «ООО Ромашка» — это кабинет юр. лица «ООО «Ромашка»», но не «ООО Ромашка Плюс». Кабинет выбирается по юр. лицу жильца; не нашёлся или нашлись два — CRM откажет и назовёт причину, а не отправит из первого попавшегося: уведомление из кабинета чужого юр. лица для МВД не подано."},{t:"warn",s:"Пароли хранятся зашифрованными и наружу не показываются — только маска."}]},{key:"set-skud",title:"Настройки СКУД",lead:"Всё о турникетах объекта — в разделе «СКУД» → вкладка «Оборудование и настройка» (тот же экран — в «Настройки → Турникеты») (видят администратор и директор).",blocks:[{t:"li",s:"Система турникетов объекта: Hikvision, ZKTeco или «Без турникетов». Новые объекты — на Hikvision."},{t:"li",s:"«Добавить терминал» — название, адрес, логин и пароль терминала и «Сторона»: вход или выход. У каждого терминала — «Проверить связь», «Настроить проходы» (терминал начнёт присылать проходы в CRM) и «Сверить время»."},{t:"li",s:"«Как CRM управляет терминалами» — напрямую или через мостик, небольшую программу на компьютере охраны. Мостик нужен, только если сервер не видит терминалы по сети."},{t:"li",s:"«Кто решает о пропуске» — автоматический или ручной режим (статья «Кто решает о пропуске» в разделе «Проходы и СКУД»)."},{t:"li",s:"«Жильцы на турникетах»: «Загрузить всех жильцов» — при запуске объекта и после замены терминала; «Сверить и исправить» — найти выселенных, которые ещё могут пройти, и живущих, которых нет на турникете."},{t:"note",s:"От «Стороны» терминала зависит, как считается «кто внутри / снаружи» и расчёт ночей. Терминал, который CRM не опознала, даёт «нет данных»."},{t:"note",s:"На объекте с турникетами ZKTeco здесь же — адрес, логин и пароль программы ZKBio на компьютере охраны и имена считывателей «Вход» и «Выход»."}]},{key:"set-agent",title:"Привязка мостика на компьютере охраны",lead:"Нужна, только если сервер не видит терминалы напрямую (или объект на ZKTeco). Делается один раз, по коду.",blocks:[{t:"step",s:"В разделе «СКУД» → «Оборудование и настройка» нажмите «Сгенерировать код привязки» (код действует ограниченное время)."},{t:"step",s:"Передайте код тому, кто ставит программу на компьютер охраны: по этому коду программа сама получит из CRM все настройки объекта."},{t:"tip",s:"Дальше настройки объекта меняются в CRM — к компьютеру охраны ходить не нужно."}]}]},{key:"glossary",label:"Словарь",articles:[{key:"terms",title:"Словарь: что значат слова в CRM",lead:"Короткие пояснения для тех, кто в хостеле недавно.",blocks:[{t:"h",s:"Люди и организации"},{t:"li",s:"Объект — один хостел сети. Сеть — все ваши объекты вместе."},{t:"li",s:"Фирма — организация, которая селит у вас своих работников и платит за места. Её сотрудники в CRM — жильцы."},{t:"li",s:"Юр. лицо — организация-принимающая сторона, от имени которой подаются уведомления. У каждой комнаты своё юр. лицо."},{t:"li",s:"ЭЦП — электронная подпись юр. лица. Без неё уведомление в Контур.ФМС не уйдёт. В CRM так и пишут: «юр. лицо (ЭЦП)»."},{t:"h",s:"Миграционный учёт"},{t:"li",s:"ФМС — прежнее название миграционной службы. Сегодня уведомления принимает МВД; слово «ФМС» осталось в названиях («Контур.ФМС»)."},{t:"li",s:"Контур.ФМС — сервис, через который на объектах с Контуром подаются уведомления. Логины кабинетов — «Настройки» → «Объект» → «Контур.ФМС»."},{t:"li",s:"Госуслуги — другой путь подачи: CRM подаёт уведомление сама, если объект переведён на этот режим."},{t:"li",s:"Бумажный учёт — объект, где уведомления печатают на бланках и носят в МВД. «Талон» (отрывная часть) — подтверждение, что пришло обратно; без отметки «Талон вернулся» CRM не считает человека поставленным на учёт."},{t:"li",s:"Уведомление о прибытии — сообщение в МВД, что иностранец поселился; о выбытии (убытии) — что уехал. У каждого свой срок в рабочих днях."},{t:"li",s:"Постановка на учёт и снятие с учёта — это эти два уведомления. Уехал — человека обязательно снимают."},{t:"li",s:"Регистрация до — дата, до которой человек поставлен на учёт. Жёлтая — осталось 7 дней или меньше, красная — истекла."},{t:"li",s:"Патент — у безвизовых иностранцев разрешение на работу. РНР — разрешение на работу у визовых (вместо патента). В CRM колонка так и называется «Патент / РНР»."},{t:"li",s:"ВНЖ — вид на жительство. Цифровой ID (MAX) — способ заселить гражданина РФ без бумажного паспорта по QR-коду."},{t:"li",s:"Просрочка — регистрация уже закончилась. Это риск штрафа хостелу, поэтому «Просрочка» должна быть пустой."},{t:"h",s:"Турникеты"},{t:"li",s:"СКУД — система контроля и управления доступом: турникеты, пропуска и журнал проходов. Раздел меню так и называется."},{t:"li",s:"Пропуск — фотография жильца в карточке; по ней турникет пускает или не пускает."},{t:"li",s:"Терминал — устройство у турникета (Hikvision или ZKTeco). «Сторона» терминала — вход или выход: от неё зависит, кто внутри."},{t:"li",s:"СКУД ID — номер человека на турникете. Его видно в журнале проходов."},{t:"li",s:"Мостик — небольшая программа на компьютере охраны, через которую CRM говорит с терминалами, если не видит их по сети. ZKBio — программа турникетов ZKTeco на том же компьютере."},{t:"li",s:"Блокировка — закрытый пропуск: турникет такого человека не пускает, а причина записана."},{t:"h",s:"Места и деньги"},{t:"li",s:"Квота мест — сколько мест у фирмы. Два режима: «закреплённые комнаты» (комнаты закреплены за фирмой) и «плавающие места» (свободно = квота объекта минус занятые)."},{t:"li",s:"Продано мест — места, за которые фирма должна платить по своему режиму; это не поступившие деньги."},{t:"li",s:"Нарушение — штраф жильцу или фирме. Оплатить, снять или просрочить его можно в «Заблокированные» → «Нарушения»."}]}]}];export{o as F,r as M,s as R,a,n as g};
